def get_xlsx_cell_value__e1554c2c(env, config):
    """Get a specific cell value from xlsx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell'

    Returns:
        Cell value (numeric, string, or None)
    """
    vm_path = config.get('path', '/home/user/SmallBalanceSheet.xlsx')
    sheet_idx = config.get('sheet', 0)
    cell_addr = config.get('cell', 'A1')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp_file:
        tmp_file.write(file_bytes)
        tmp_path = tmp_file.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell_value = ws[cell_addr].value
        wb.close()
        return cell_value
    finally:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)

