def get_xlsx_average_value__0ea2a1d3eca19edbbb06cd91771ccf92(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Extract the calculated average value from Sheet2 and verify it uses a formula.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'value', 'has_formula', 'formula', 'references_sheet1' keys, or None
    """
    file_path = config.get('path', '/home/user/SmallBalanceSheet.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_formulas = openpyxl.load_workbook(tmp_path, data_only=False)
        wb_values = openpyxl.load_workbook(tmp_path, data_only=True)
        if len(wb_formulas.sheetnames) < 2:
            return None
        ws_formulas = wb_formulas.worksheets[1]
        ws_values = wb_values.worksheets[1]
        found_cell = None
        found_value = None
        found_formula = None
        for row in range(1, 11):
            for col in range(1, 11):
                cell = ws_formulas.cell(row=row, column=col)
                value = ws_values.cell(row=row, column=col).value
                if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
                    formula = cell.value
                    if 'AVERAGE' in formula.upper():
                        found_cell = cell.coordinate
                        found_formula = formula
                        found_value = value
                        break
            if found_cell:
                break
        if found_cell is None:
            for row in range(1, 11):
                for col in range(1, 11):
                    value = ws_values.cell(row=row, column=col).value
                    if value is not None:
                        try:
                            val_float = float(value)
                            if 39000 < val_float < 40000:
                                found_value = val_float
                                found_cell = ws_values.cell(row=row, column=col).coordinate
                                break
                        except (ValueError, TypeError):
                            continue
                if found_value is not None:
                    break
        if found_value is None:
            return None
        references_sheet1 = False
        if found_formula:
            if 'Sheet1!' in found_formula or 'Sheet1.' in found_formula or '$Sheet1.' in found_formula:
                references_sheet1 = True
        result = {'value': float(found_value) if found_value is not None else None, 'has_formula': found_formula is not None, 'formula': found_formula, 'references_sheet1': references_sheet1, 'cell_location': found_cell}
        return result
    finally:
        os.unlink(tmp_path)

