def get_xlsx_top_passrate_unis__d4e78c3520d16e262ee3239490bc55d3(env, config: Dict[str, Any]) -> Dict[str, str]:
    """Extract the university with highest pass rate for specified years from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key and 'years' list

    Returns:
        Dictionary mapping year to university name with highest pass rate
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        headers = []
        for col_idx in range(2, ws.max_column + 1):
            cell_value = ws.cell(1, col_idx).value
            if cell_value:
                headers.append(str(cell_value))
        years_to_check = config.get('years', [])
        for row_idx in range(2, ws.max_row + 1):
            year_cell = ws.cell(row_idx, 1).value
            if year_cell is None:
                continue
            year_str = str(year_cell)
            if year_str in years_to_check:
                max_rate = -1
                max_uni = None
                for col_idx in range(2, ws.max_column + 1):
                    cell_value = ws.cell(row_idx, col_idx).value
                    if cell_value is not None and isinstance(cell_value, (int, float)):
                        if cell_value > max_rate:
                            max_rate = cell_value
                            max_uni = headers[col_idx - 2]
                if max_uni:
                    result[year_str] = max_uni
        return result
    finally:
        os.unlink(tmp_path)

