def get_xlsx_table_data__f918ebce432b3a8956b1f7dd26a64d11(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract complete table data including headers, rows, and cell data.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dictionary with 'headers', 'rows', 'row_count', and structured 'data' keys
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'headers': [], 'rows': [], 'row_count': 0, 'data': []}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'headers': [], 'rows': [], 'row_count': 0, 'data': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        headers = []
        rows = []
        data = []
        for (row_idx, row) in enumerate(ws.iter_rows(values_only=True), start=1):
            if row_idx == 1:
                if row and any(row):
                    headers = [str(cell).strip() if cell else '' for cell in row]
                    continue
            if row and any(row):
                row_data = [str(cell).strip() if cell else '' for cell in row]
                if any((cell for cell in row_data)):
                    rows.append(row_data)
                    if headers:
                        row_dict = {}
                        for (i, header) in enumerate(headers):
                            if i < len(row_data):
                                row_dict[header] = row_data[i]
                        data.append(row_dict)
        return {'headers': headers, 'rows': rows, 'row_count': len(rows), 'data': data}
    finally:
        os.unlink(tmp_path)

