def get_pptx_table_cell__1937923d(env, config):
    """Get a specific cell value from a PowerPoint table.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'slide_index', 'row', 'col'

    Returns:
        str: The cell text content
    """
    path = config['path']
    slide_index = config['slide_index']
    row = config['row']
    col = config['col']
    local_path = get_vm_file(env, {'path': path, 'dest': os.path.basename(path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    for shape in slide.shapes:
        if shape.has_table:
            table = shape.table
            return table.rows[row].cells[col].text
    return None

def get_xlsx_specific_cells__68fb47fb(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Read specific cells from an XLSX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', and 'cells' (list of cell addresses)

    Returns:
        Dict mapping cell addresses to their values
    """
    vm_path = config.get('path', '')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return {}
    wb = openpyxl.load_workbook(BytesIO(file_bytes), data_only=True)
    ws = wb.active
    cells_to_check = config.get('cells', [])
    result = {}
    for cell_addr in cells_to_check:
        try:
            cell_value = ws[cell_addr].value
            result[cell_addr] = cell_value
        except Exception:
            result[cell_addr] = None
    return result

def get_xlsx_cell_value__603f3b90(env, config):
    """
    Get the value of a specific cell in an xlsx file.

    Args:
        env: Environment object
        config: Configuration dict with keys:
            - path: Path to the xlsx file
            - sheet: Sheet index (0-based) or sheet name
            - cell: Cell coordinate (e.g., "C10")

    Returns:
        str or number: The cell value, or None if cell is empty or error occurs
    """
    path = config.get('path')
    sheet = config.get('sheet', 0)
    cell_coord = config.get('cell')
    logger.debug(f'Reading xlsx cell: path={path}, sheet={sheet}, cell={cell_coord}')
    try:
        wb = openpyxl.load_workbook(path, data_only=True)
        if isinstance(sheet, int):
            ws = wb.worksheets[sheet]
        else:
            ws = wb[sheet]
        cell_value = ws[cell_coord].value
        wb.close()
        logger.debug(f'Cell {cell_coord} value: {cell_value}')
        return cell_value
    except FileNotFoundError:
        logger.error(f'File not found: {path}')
        return None
    except IndexError:
        logger.error(f'Sheet index {sheet} out of range')
        return None
    except KeyError:
        logger.error(f'Sheet {sheet} not found')
        return None
    except Exception as e:
        logger.error(f'Error reading xlsx cell: {e}')
        return None

