        return {'column_a_header': str(column_a_header).strip() if column_a_header else '', 'column_a_data': column_a_data, 'column_b_header': str(column_b_header).strip() if column_b_header else '', 'column_b_data': column_b_data, 'column_c_header': str(column_c_header).strip() if column_c_header else '', 'column_c_data': column_c_data, 'column_d_header': str(column_d_header).strip() if column_d_header else '', 'column_d_data': column_d_data, 'column_e_header': str(column_e_header).strip() if column_e_header else '', 'column_e_data': column_e_data}
