def get_xlsx_cell_value__068abfcb(env, config: Dict[str, Any]) -> Any:
    """
    Get the value of a specific cell from an XLSX file.

    Args:
        env: Environment object
        config: Configuration dict with keys:
            - path: str, path to the xlsx file on VM
            - dest: str, destination filename (for compatibility)
            - sheet: int or str, sheet index or name
            - cell: str, cell coordinate (e.g., "G2")

    Returns:
        The value of the cell (can be number, string, formula result, etc.)
    """
    try:
        file_path = config.get('path')
        if not file_path:
            logger.error('No file path provided in config')
            return None
        logger.info(f'Loading workbook from: {file_path}')
        workbook = openpyxl.load_workbook(filename=file_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        if isinstance(sheet_idx, int):
            sheet_names = workbook.sheetnames
            if sheet_idx >= len(sheet_names):
                logger.error(f'Sheet index {sheet_idx} out of range. Available sheets: {sheet_names}')
                return None
            sheet = workbook[sheet_names[sheet_idx]]
            logger.info(f'Using sheet at index {sheet_idx}: {sheet_names[sheet_idx]}')
        else:
            sheet = workbook[sheet_idx]
            logger.info(f'Using sheet: {sheet_idx}')
        cell_coord = config.get('cell')
        if not cell_coord:
            logger.error('No cell coordinate provided in config')
            return None
        cell = sheet[cell_coord]
        value = cell.value
        logger.info(f'Cell {cell_coord} value: {value} (type: {type(value).__name__})')
        workbook.close()
        return value
    except FileNotFoundError as e:
        logger.error(f'File not found: {file_path} - {e}')
        return None
    except Exception as e:
        logger.error(f'Error reading cell value from xlsx: {e}')
        return None

def get_xlsx_row_count__c5191f15f5cc4ee099471a13a564d922(env, config: Dict[str, Any]) -> int:
    """
    Count the number of non-empty rows in an Excel file (excluding header if specified).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'sheet' (sheet index),
                'exclude_header' (bool, whether to exclude first row from count)

    Returns:
        Number of non-empty rows
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return 0
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        exclude_header = config.get('exclude_header', False)
        non_empty_count = 0
        start_row = 2 if exclude_header else 1
        for row in ws.iter_rows(min_row=start_row, values_only=True):
            if any((cell is not None for cell in row)):
                non_empty_count += 1
        return non_empty_count
    finally:
        os.unlink(tmp_path)

def get_xlsx_column_values__2f3232fe(env, config):
    """Get all values from a specific column range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (int), 'range' (str like "A2:A20")

    Returns:
        List of values from the specified range (excluding None values)
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    file_path = get_vm_file(env, {'path': config['path'], 'dest': os.path.basename(config['path'])})
    if file_path is None:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return []
    wb = openpyxl.load_workbook(file_path, data_only=True)
    if isinstance(config['sheet'], int):
        ws = wb.worksheets[config['sheet']]
    else:
        ws = wb[config['sheet']]
    cell_range = config['range']
    values = []
    for row in ws[cell_range]:
        for cell in row:
            if cell.value is not None:
                values.append(cell.value)
    return values

def get_xlsx_row_count__75a9838c1218e06140616c4506e2d4fe(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Count the total number of data rows with proper content in the bookkeeping spreadsheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        dict: Dictionary with row count and content quality information
            - total_rows: Total number of rows with data
            - valid_rows: Number of rows with both description and amount
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'total_rows': 0, 'valid_rows': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        total_rows = 0
        valid_rows = 0
        for row_idx in range(3, ws.max_row + 1):
            desc_cell = ws.cell(row=row_idx, column=1)
            amount_cell = ws.cell(row=row_idx, column=2)
            if desc_cell.value:
                total_rows += 1
                if amount_cell.value is not None:
                    valid_rows += 1
        return {'total_rows': total_rows, 'valid_rows': valid_rows}
    finally:
        os.unlink(tmp_path)

def get_xlsx_cell_fill__151f3fa2147481ad5b43ba8dec5685ee(env, config):
    """Get cell fill color and verify it contains max value from Old ID column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell' keys

    Returns:
        dict: {
            'has_fill': bool,
            'color': str or None,
            'cell_value': float or None,
            'is_max_in_column': bool,
            'max_value': float or None,
            'max_cell_address': str or None
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_fill': False, 'color': None, 'cell_value': None, 'is_max_in_column': False, 'max_value': None, 'max_cell_address': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cell_addr = config['cell']
        cell = ws[cell_addr]
        has_fill = False
        color = None
        wb_format = openpyxl.load_workbook(tmp_path, data_only=False)
        ws_format = wb_format.worksheets[sheet_idx]
        cell_format = ws_format[cell_addr]
        if cell_format.fill and cell_format.fill.start_color:
            color_val = cell_format.fill.start_color.rgb
            if color_val and color_val != '00000000':
                has_fill = True
                if isinstance(color_val, str):
                    color = color_val[-6:] if len(color_val) == 8 else color_val
                else:
                    color = str(color_val)
        cell_value = cell.value
        try:
            cell_value = float(cell_value) if cell_value is not None else None
        except (ValueError, TypeError):
            cell_value = None
        column_letter = 'C'
        max_value = None
        max_cell_address = None
        for row in range(2, ws.max_row + 1):
            cell_ref = f'{column_letter}{row}'
            cell_obj = ws[cell_ref]
            val = cell_obj.value
            try:
                val_float = float(val) if val is not None else None
                if val_float is not None:
                    if max_value is None or val_float > max_value:
                        max_value = val_float
                        max_cell_address = cell_ref
            except (ValueError, TypeError):
                continue
        is_max_in_column = False
        if cell_value is not None and max_value is not None:
            is_max_in_column = abs(cell_value - max_value) < 0.01
        return {'has_fill': has_fill, 'color': color, 'cell_value': cell_value, 'is_max_in_column': is_max_in_column, 'max_value': max_value, 'max_cell_address': max_cell_address}
    finally:
        os.unlink(tmp_path)

