def get_cell_number_format__5f4b163b(env, config: dict):
    """
    Extract the number format of cells in a column in LibreOffice Calc.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet', 'column' parameters

    Returns:
        list of dicts with cell ref, value, and number_format for each cell in the column
    """
    file_bytes = env.controller.get_file(config['path'])
    if file_bytes is None:
        return None
    cache_path = os.path.join(env.cache_dir, config['dest'])
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    sheet_idx = config.get('sheet', 0)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    column = config.get('column', 'C')
    cell_formats = []
    for row_idx in range(2, ws.max_row + 1):
        cell_ref = f'{column}{row_idx}'
        cell = ws[cell_ref]
        if cell.value is None or cell.value == '':
            break
        number_format = cell.number_format if cell else None
        cell_formats.append({'cell': cell_ref, 'value': cell.value, 'number_format': number_format})
    return cell_formats

