def get_xlsx_ages_and_highlight__599223fb612f6c3c3362c3de00669490(env, config):
    """Extract all ages and highlighting information from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path (e.g., "/home/user/file.xlsx")
            - sheet: Sheet index (0-based) or sheet name
            - age_column: Column letter for ages (e.g., "D")
            - birthday_column: Column letter for birthdays (e.g., "C")
            - start_row: First data row (1-based, default 2)
            - end_row: Last data row (1-based, optional)
            - highlight_columns: List of columns to check for highlighting (e.g., ["B", "C", "D"])

    Returns:
        Dict with:
            - ages: List of tuples (row_num, age_value, birthday, expected_age) for all employees
            - highlighted_row: Row number that is highlighted (or None)
            - highlighted_color: Color code of the highlighted row (or None)
            - max_age_row: Row number with maximum age (or None)
    """
    file_path = config.get('path')
    if not file_path:
        return {'ages': [], 'highlighted_row': None, 'highlighted_color': None, 'max_age_row': None}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'ages': [], 'highlighted_row': None, 'highlighted_color': None, 'max_age_row': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_ref = config.get('sheet', 0)
        if isinstance(sheet_ref, int):
            ws = wb.worksheets[sheet_ref]
        else:
            ws = wb[sheet_ref]
        age_col = config.get('age_column', 'D')
        birthday_col = config.get('birthday_column', 'C')
        start_row = config.get('start_row', 2)
        end_row = config.get('end_row', ws.max_row)
        highlight_cols = config.get('highlight_columns', ['B', 'C', 'D'])
        ages = []
        max_age = None
        max_age_row = None
        highlighted_row = None
        highlighted_color = None
        current_year = datetime.now().year
        for row_num in range(start_row, end_row + 1):
            age_cell = ws[f'{age_col}{row_num}']
            age_value = age_cell.value
            birthday_cell = ws[f'{birthday_col}{row_num}']
            birthday_value = birthday_cell.value
            if age_value is not None:
                try:
                    age = int(age_value) if not isinstance(age_value, int) else age_value
                    expected_age = None
                    if birthday_value:
                        if isinstance(birthday_value, datetime):
                            birth_year = birthday_value.year
                            expected_age = current_year - birth_year
                        elif isinstance(birthday_value, str):
                            for fmt in ['%m/%d/%Y', '%Y-%m-%d', '%d/%m/%Y', '%m-%d-%Y']:
                                try:
                                    birth_date = datetime.strptime(birthday_value, fmt)
                                    expected_age = current_year - birth_date.year
                                    break
                                except ValueError:
                                    continue
                    ages.append((row_num, age, birthday_value, expected_age))
                    if max_age is None or age > max_age:
                        max_age = age
                        max_age_row = row_num
                except (ValueError, TypeError):
                    pass
        for row_num in range(start_row, end_row + 1):
            highlighted_count = 0
            row_color = None
            for col in highlight_cols:
                cell = ws[f'{col}{row_num}']
                if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
                    color = cell.fill.start_color.rgb
                    if color and isinstance(color, str) and (color not in ['00000000', 'FFFFFFFF']):
                        highlighted_count += 1
                        if row_color is None:
                            row_color = color[2:] if len(color) == 8 else color
            if highlighted_count == len(highlight_cols):
                highlighted_row = row_num
                highlighted_color = row_color
                break
        return {'ages': ages, 'highlighted_row': highlighted_row, 'highlighted_color': highlighted_color, 'max_age_row': max_age_row}
    finally:
        os.unlink(tmp_path)

