def get_xlsx_earliest_date__f38b7ed1(env, config):
    """Find the earliest publication date in the spreadsheet.

    Args:
        env: DesktopEnv instance
        config: dict with 'path', 'sheet', 'column' (date column letter)

    Returns:
        Earliest date as string
    """
    import os
    from desktop_env.evaluators.getters.file import get_vm_file
    from datetime import datetime
    vm_path = config['path']
    sheet_idx = config.get('sheet', 0)
    column = config['column']
    local_path = get_vm_file(env, {'path': vm_path, 'dest': os.path.basename(vm_path)})
    if local_path is None:
        return None
    wb = openpyxl.load_workbook(local_path, data_only=True)
    ws = wb.worksheets[sheet_idx] if isinstance(sheet_idx, int) else wb[sheet_idx]
    dates = []
    for row in range(2, ws.max_row + 1):
        cell_value = ws[f'{column}{row}'].value
        if cell_value:
            try:
                if isinstance(cell_value, str):
                    date_obj = datetime.strptime(cell_value, '%Y/%m/%d')
                    dates.append(date_obj)
            except:
                pass
    wb.close()
    if dates:
        earliest = min(dates)
        return earliest.strftime('%Y/%m/%d')
    return None

