def get_xlsx_cell_format__33598a41(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get cell formatting information from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell' keys

    Returns:
        Dict with formatting info (fill_color, font_color, etc.)
    """
    file_path = config.get('path', '')
    sheet_name = config.get('sheet', '')
    cell_address = config.get('cell', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        if sheet_name.isdigit():
            ws = wb.worksheets[int(sheet_name)]
        else:
            ws = wb[sheet_name]
        cell = ws[cell_address]
        format_info = {'has_fill': cell.fill is not None and cell.fill.start_color is not None and (cell.fill.start_color.rgb not in [None, '00000000']), 'fill_color': None, 'value': cell.value}
        if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
            rgb = cell.fill.start_color.rgb
            if rgb and rgb != '00000000':
                format_info['fill_color'] = rgb
        return format_info
    finally:
        import os
        os.unlink(tmp_path)

