def get_xlsx_oldest_employee__6a0adc3d(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get the oldest employee from an Excel file.

    This function reads the Excel file and determines the oldest employee
    based on their birthdate. It returns the name found in cell E2 where
    the task requires the user to write the oldest employee's name, and
    also verifies that ages were calculated in column D.

    Args:
        env: Environment object
        config: Configuration dict with 'path' and 'sheet' keys

    Returns:
        dict: Dictionary with 'employee_name' (value in E2), 'ages_calculated' (bool),
              'age_values' (list of ages in column D), and 'birthdate_values' (list)
    """
    try:
        file_path = config.get('path')
        sheet_idx = config.get('sheet', 0)
        if not file_path:
            logger.error('No file path provided in config')
            return {'employee_name': None, 'ages_calculated': False}
        wb = openpyxl.load_workbook(file_path, data_only=True)
        if isinstance(sheet_idx, int):
            sheet = wb.worksheets[sheet_idx]
        else:
            sheet = wb[sheet_idx]
        e2_value = sheet['E2'].value
        ages = []
        birthdates = []
        ages_calculated = False
        row = 2
        while True:
            birthdate_cell = sheet[f'C{row}'].value
            age_cell = sheet[f'D{row}'].value
            if birthdate_cell is None:
                break
            birthdates.append(birthdate_cell)
            ages.append(age_cell)
            row += 1
        if ages and all((isinstance(age, (int, float)) and age > 0 for age in ages)):
            ages_calculated = True
            if not all((0 <= age <= 150 for age in ages)):
                ages_calculated = False
        wb.close()
        result = {'employee_name': e2_value.strip() if e2_value and isinstance(e2_value, str) else e2_value, 'ages_calculated': ages_calculated, 'age_values': ages, 'birthdate_values': birthdates}
        logger.info(f"Found employee name in E2: {result['employee_name']}")
        logger.info(f'Ages calculated: {ages_calculated}, Found {len(ages)} age values')
        return result
    except Exception as e:
        logger.error(f'Error reading Excel file: {e}')
        return {'employee_name': None, 'ages_calculated': False}

