def get_xlsx_cell_text__98d2551e(env, config):
    """Extract the displayed text value from a specific cell in an Excel file.

    This function reads the cell value as it would be displayed in LibreOffice Calc,
    including formatted numbers. Uses a dual approach: first tries data_only=True,
    then falls back to using LibreOffice's own export capabilities if needed.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters
            - path: Path to Excel file on VM
            - cell: Cell address (e.g., 'D1')
            - sheet: Sheet index or name (default: 0)

    Returns:
        str: The displayed text value from the cell
    """
    file_path = config.get('path')
    cell_addr = config.get('cell')
    sheet_idx = config.get('sheet', 0)
    file_content = env.controller.get_file(file_path)
    if not file_content:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp_file:
        tmp_file.write(file_content)
        tmp_path = tmp_file.name
    try:
        wb_cached = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws_cached = wb_cached.worksheets[sheet_idx]
        else:
            ws_cached = wb_cached[sheet_idx]
        cell_cached = ws_cached[cell_addr]
        cached_value = cell_cached.value
        wb_cached.close()
        if cached_value is not None:
            return str(cached_value)
        wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
        if isinstance(sheet_idx, int):
            ws_formula = wb_formula.worksheets[sheet_idx]
        else:
            ws_formula = wb_formula[sheet_idx]
        cell_formula = ws_formula[cell_addr]
        if cell_formula.value is not None:
            cell_value = cell_formula.value
            if isinstance(cell_value, str) and cell_value.startswith('='):
                result = _evaluate_text_formula(cell_value, ws_formula)
                wb_formula.close()
                return result if result else ''
            else:
                wb_formula.close()
                return str(cell_value) if cell_value is not None else ''
        wb_formula.close()
        return ''
    finally:
        os.unlink(tmp_path)

