def get_xlsx_top_cell_title__b985b2a4e8be32e6adbcbc28cd034e20(env, config):
    """Get complete data from the top_10 sheet including headers, all movie data, and ratings.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'sheet' (sheet name or index)

    Returns:
        dict: Contains headers, movies list with titles and ratings, and row count
              {
                  'headers': list of header values,
                  'movies': [{'title': str, 'rating': float}, ...],
                  'row_count': int (data rows, excluding header)
              }
              Returns None if sheet doesn't exist
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_name = config.get('sheet', 0)
        if isinstance(sheet_name, int):
            ws = wb.worksheets[sheet_name]
        else:
            if sheet_name not in wb.sheetnames:
                return None
            ws = wb[sheet_name]
        headers = []
        for col in range(1, ws.max_column + 1):
            header_value = ws.cell(1, col).value
            headers.append(header_value if header_value else '')
        movies = []
        row_count = 0
        for row in range(2, ws.max_row + 1):
            title_value = ws.cell(row, 1).value
            if title_value is None:
                break
            row_count += 1
            rating_value = ws.cell(row, 3).value
            try:
                rating = float(rating_value) if rating_value is not None else 0.0
            except (ValueError, TypeError):
                rating = 0.0
            movies.append({'title': str(title_value).strip() if title_value else '', 'rating': rating})
        return {'headers': headers, 'movies': movies, 'row_count': row_count}
    finally:
        os.unlink(tmp_path)

