def get_xlsx_multiple_cells__8467ab0e(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract values and formulas from multiple cells in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet' (0-indexed), 'cells' (dict of label: cell_ref)

    Returns:
        Dict with:
        - 'values': labels mapped to cell values (calculated)
        - 'formulas': labels mapped to cell formulas (or None if no formula)
        - 'labels': dict mapping label_cells to their text values
    """
    from desktop_env.evaluators.getters import file as file_getters
    local_path = file_getters.get_vm_file(env, config)
    wb = openpyxl.load_workbook(local_path, data_only=False)
    sheet_idx = config.get('sheet', 0)
    ws = wb.worksheets[sheet_idx]
    cells = config.get('cells', {})
    result = {'values': {}, 'formulas': {}, 'labels': {}}
    for (label, cell_ref) in cells.items():
        cell = ws[cell_ref]
        result['values'][label] = cell.value
        if cell.data_type == 'f':
            result['formulas'][label] = cell.value
        else:
            result['formulas'][label] = None
    label_cells = config.get('label_cells', {})
    for (label_key, label_cell_ref) in label_cells.items():
        result['labels'][label_key] = ws[label_cell_ref].value
    wb.close()
    return result

