def get_xlsx_highlighting__af058823(env, config: dict) -> Dict[str, Any]:
    """Get highlighting info from Excel file.
    
    Args:
        env: DesktopEnv instance
        config: Config with 'path' and 'dest' keys
        
    Returns:
        Dictionary with cell highlighting information
    """
    import os
    vm_path = config.get('path', '')
    file_content = env.controller.get_file(vm_path)
    if not file_content:
        return {'error': 'Failed to get file from VM'}
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp_file:
        tmp_file.write(file_content)
        tmp_path = tmp_file.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        highlighted_cells = []
        for row in range(1, 51):
            for col in range(1, 7):
                cell = ws.cell(row=row, column=col)
                if cell.fill and cell.fill.start_color:
                    color_value = cell.fill.start_color.rgb
                    if color_value and color_value not in ['00000000', 'FFFFFFFF', None]:
                        if len(color_value) == 8:
                            color_value = color_value[2:]
                        highlighted_cells.append({'cell': cell.coordinate, 'color': color_value.lower() if color_value else None})
        wb.close()
        return {'highlighted_cells': highlighted_cells}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_xlsx_all_students_grading__5166e9713ef2b3a5eb2cb8ffb49207d2(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get comprehensive grading information for all students including individual question scores and total grades.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict containing grading data for all students, or empty dict if file not accessible
    """
    file_path = config.get('path')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {'students': [], 'all_students_graded': True, 'individual_scores_recorded': True, 'total_scores_recorded': True}
        for row in range(2, 12):
            student_id_cell = ws.cell(row=row, column=1).value
            if not student_id_cell:
                result['all_students_graded'] = False
                continue
            student_data = {'student_id': str(student_id_cell), 'individual_scores': [], 'total_grade': None, 'has_all_individual_scores': True, 'has_total_grade': False}
            for col in range(2, 12):
                score = ws.cell(row=row, column=col).value
                if score is not None and isinstance(score, (int, float)):
                    student_data['individual_scores'].append(int(score))
                else:
                    student_data['has_all_individual_scores'] = False
                    result['individual_scores_recorded'] = False
            total_grade = ws.cell(row=row, column=13).value
            if total_grade is not None and isinstance(total_grade, (int, float)):
                student_data['total_grade'] = int(total_grade)
                student_data['has_total_grade'] = True
            else:
                result['total_scores_recorded'] = False
            result['students'].append(student_data)
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_budget_sheet__3748f05e4a95ed12bedb27743158a829(env, config):
    """
    Extract budget sheet data from a LibreOffice Calc .xlsx file and verify budget-specific content.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the .xlsx file on VM

    Returns:
        dict: Dictionary containing file existence, structure validation, and budget-specific checks
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'exists': False, 'has_structure': False, 'has_income_category': False, 'has_expense_category': False, 'budget_keywords_found': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        has_structure = ws.max_row > 0 and ws.max_column > 0
        budget_keywords = ['income', 'expense', 'budget', 'total', 'revenue', 'cost', 'spending']
        found_keywords = set()
        has_income = False
        has_expense = False
        for row in ws.iter_rows(values_only=True):
            for cell_value in row:
                if cell_value is not None:
                    cell_str = str(cell_value).lower().strip()
                    if 'income' in cell_str or 'revenue' in cell_str:
                        has_income = True
                        found_keywords.add('income')
                    if 'expense' in cell_str or 'spending' in cell_str or 'cost' in cell_str:
                        has_expense = True
                        found_keywords.add('expense')
                    for keyword in budget_keywords:
                        if keyword in cell_str:
                            found_keywords.add(keyword)
        wb.close()
        return {'exists': True, 'has_structure': has_structure, 'has_income_category': has_income, 'has_expense_category': has_expense, 'budget_keywords_found': sorted(list(found_keywords)), 'dimensions': f'{ws.max_row}x{ws.max_column}'}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

