def get_xlsx_cell_colors__c851ef7c(env, config: dict) -> Dict[str, Any]:
    """Extract background colors for all cells in the specified sheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict mapping cell coordinates to their RGB background colors (as hex strings)
    """
    vm_path = config.get('path', '/home/user/Calendar_Highlight_Weekend_Days.xlsx')
    dest = config.get('dest', 'Calendar_Highlight_Weekend_Days.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    import os
    cache_dir = env.cache_dir
    local_path = os.path.join(cache_dir, dest)
    os.makedirs(os.path.dirname(local_path), exist_ok=True)
    with open(local_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(local_path)
    ws = wb.active
    cell_colors = {}
    for row in ws.iter_rows():
        for cell in row:
            if cell.fill and cell.fill.start_color:
                color = cell.fill.start_color.rgb
                if color and color != '00000000':
                    if len(color) == 8:
                        hex_color = f'#{color[2:].upper()}'
                    else:
                        hex_color = f'#{color.upper()}'
                    cell_colors[cell.coordinate] = hex_color
    wb.close()
    return cell_colors

def get_xlsx_period_rate_min__fb10ed6d3d541f23d60c3749f2188910(env, config):
    """Extract the minimum period rate value and its location from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {
            'min_row': int,
            'min_value': float,
            'cell': str,
            'has_blue_font': bool,
            'column_header': str,
            'total_data_rows': int,
            'all_numeric': bool,
            'calculation_sample_correct': bool
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        period_rate_col = None
        column_header = None
        for col in range(1, ws.max_column + 1):
            cell_value = ws.cell(row=1, column=col).value
            if cell_value and str(cell_value).strip() == 'Period Rate (%)':
                period_rate_col = col
                column_header = str(cell_value).strip()
                break
        if period_rate_col is None:
            return {}
        annual_rate_col = None
        period_per_year_col = None
        for col in range(1, ws.max_column + 1):
            cell_value = ws.cell(row=1, column=col).value
            if cell_value:
                header = str(cell_value).strip()
                if 'Annual Rate' in header:
                    annual_rate_col = col
                elif 'Period per year' in header:
                    period_per_year_col = col
        total_data_rows = 0
        all_numeric = True
        min_value = None
        min_row = None
        for row in range(2, ws.max_row + 1):
            cell = ws.cell(row=row, column=period_rate_col)
            cell_value = cell.value
            if cell_value is not None:
                total_data_rows += 1
                if cell.data_type != 'n':
                    all_numeric = False
                if isinstance(cell_value, (int, float)):
                    if min_value is None or cell_value < min_value:
                        min_value = cell_value
                        min_row = row
                else:
                    all_numeric = False
        if min_row is None:
            return {}
        from openpyxl.utils import get_column_letter
        col_letter = get_column_letter(period_rate_col)
        cell_address = f'{col_letter}{min_row}'
        cell = ws.cell(row=min_row, column=period_rate_col)
        has_blue_font = False
        if cell.font and cell.font.color:
            color_rgb = cell.font.color.rgb
            if color_rgb:
                if isinstance(color_rgb, str):
                    if color_rgb.lower() in ['ff0000ff', '0000ff', '000000ff']:
                        has_blue_font = True
        calculation_sample_correct = False
        if annual_rate_col and period_per_year_col:
            sample_rows = [2, min_row, min(ws.max_row, 10)]
            correct_count = 0
            for row in sample_rows:
                annual_rate = ws.cell(row=row, column=annual_rate_col).value
                period_per_year = ws.cell(row=row, column=period_per_year_col).value
                period_rate = ws.cell(row=row, column=period_rate_col).value
                if annual_rate is not None and period_per_year is not None and (period_rate is not None) and (period_per_year != 0):
                    expected = annual_rate / period_per_year
                    if abs(period_rate - expected) < 0.0001:
                        correct_count += 1
            if correct_count >= 2:
                calculation_sample_correct = True
        return {'min_row': min_row, 'min_value': min_value, 'cell': cell_address, 'has_blue_font': has_blue_font, 'column_header': column_header, 'total_data_rows': total_data_rows, 'all_numeric': all_numeric, 'calculation_sample_correct': calculation_sample_correct}
    finally:
        os.unlink(tmp_path)

