def get_xlsx_specific_cells__e4e6ace8(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Read specific cells from an XLSX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', and 'cells' (list of cell addresses)

    Returns:
        Dict mapping cell addresses to their values
    """
    vm_path = config.get('path', '')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return {}
    wb = openpyxl.load_workbook(BytesIO(file_bytes), data_only=True)
