def get_xlsx_age_data__17c3ae0a38bddd4efd9ebe0c3f1152f0(env, config):
    """Extract age calculation data from Excel file.

    This getter reads:
    1. All birthday values (column C, rows 2-29)
    2. All age values (column D, rows 2-29)
    3. Average value in cell D30

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path (e.g., "/home/user/Employee_Age_By_Birthday.xlsx")
            - sheet: Sheet index (0-based) or sheet name (default: 0)

    Returns:
        dict: {
            'birthdays': list of datetime objects or None for each employee,
            'ages': list of numeric values or None for each employee,
            'average': numeric value or None from cell D30,
            'age_count': number of filled age cells
        }
    """
    file_path = config.get('path')
    if not file_path:
        return {'birthdays': [], 'ages': [], 'average': None, 'age_count': 0}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'birthdays': [], 'ages': [], 'average': None, 'age_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_ref = config.get('sheet', 0)
        if isinstance(sheet_ref, int):
            ws = wb.worksheets[sheet_ref]
        else:
            ws = wb[sheet_ref]
        birthdays = []
        for row in range(2, 30):
            cell_value = ws[f'C{row}'].value
            birthdays.append(cell_value)
        ages = []
        age_count = 0
        for row in range(2, 30):
            cell_value = ws[f'D{row}'].value
            ages.append(cell_value)
            if cell_value is not None and isinstance(cell_value, (int, float)):
                age_count += 1
        average = ws['D30'].value
        return {'birthdays': birthdays, 'ages': ages, 'average': average, 'age_count': age_count}
    finally:
        os.unlink(tmp_path)

def get_tb_digest_xlsx__b6ecd864d1dd0f24d97ae590f2c596e8(env, config):
    """Extract digest emails data from Excel report.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of dicts with email data from the Excel file
    """
    file_path = config.get('path', '')
    if not file_path:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        emails = []
        for row_idx in range(2, ws.max_row + 1):
            sender_name = ws.cell(row_idx, 1).value
            subject = ws.cell(row_idx, 2).value
            date_value = ws.cell(row_idx, 3).value
            if isinstance(date_value, datetime):
                date = date_value.strftime('%Y-%m-%d')
            elif isinstance(date_value, str):
                date = date_value
            else:
                date = str(date_value) if date_value is not None else ''
            if sender_name or subject:
                emails.append({'sender_name': sender_name, 'subject': subject, 'date': date})
        return emails
    finally:
        os.unlink(tmp_path)

