def get_calc_file_data__2bd59342(env, config) -> Dict[str, Any]:
    """
    Get data from LibreOffice Calc file to verify chart creation.

    This getter extracts:
    1. Whether the file exists and was modified
    2. Basic file metadata (size, modification time)
    3. Spreadsheet structure (sheets, columns, data ranges)
    4. Number of order IDs (expected number of charts)
    5. Chart detection via multiple methods (sheet charts, drawing objects, embedded objects)
    6. Chart type verification (column charts)
    7. Data range verification (Jan, Feb, Mar columns)

    Args:
        env: Environment object with controller to access VM files
        config: Configuration dict containing 'path' key with file path

    Returns:
        dict: File data including metadata, structure info, and chart details
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'exists': False, 'error': 'No file path provided'}
    try:
        file_bytes = env.controller.get_file(file_path)
    except Exception as e:
        return {'exists': False, 'error': f'Failed to get file: {str(e)}'}
    if not file_bytes:
        return {'exists': False, 'error': 'File not found or empty'}
    result = {'exists': True, 'file_size': len(file_bytes), 'path': file_path}
    try:
        import openpyxl
        from openpyxl.chart import BarChart, ColumnChart
        with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            wb = openpyxl.load_workbook(tmp_path, data_only=True, keep_vba=False)
            ws = wb.active
            max_row = ws.max_row
            max_col = ws.max_column
            result['max_row'] = max_row
            result['max_col'] = max_col
            headers = []
            for col in range(1, max_col + 1):
                cell_value = ws.cell(1, col).value
                headers.append(str(cell_value) if cell_value is not None else '')
            result['headers'] = headers
            result['has_chart_column'] = 'Chart' in headers
            order_id_count = 0
            if max_row > 1:
                order_id_count = max_row - 1
            result['order_id_count'] = order_id_count
            data_rows = []
            for row in range(2, min(6, max_row + 1)):
                row_data = []
                for col in range(1, max_col + 1):
                    cell_value = ws.cell(row, col).value
                    row_data.append(cell_value)
                data_rows.append(row_data)
            result['sample_data'] = data_rows
            expected_cols = ['Order ID', 'Jan', 'Feb', 'Mar', 'Chart']
            has_expected_structure = all((col in headers for col in expected_cols))
            result['has_expected_structure'] = has_expected_structure
            jan_col = headers.index('Jan') + 1 if 'Jan' in headers else None
            feb_col = headers.index('Feb') + 1 if 'Feb' in headers else None
            mar_col = headers.index('Mar') + 1 if 'Mar' in headers else None
            result['has_jan_feb_mar_cols'] = all([jan_col, feb_col, mar_col])
            chart_count = 0
            column_chart_count = 0
            charts_with_correct_data = 0
            if hasattr(ws, '_charts'):
                for chart in ws._charts:
                    chart_count += 1
                    is_column_chart = isinstance(chart, ColumnChart) or (isinstance(chart, BarChart) and getattr(chart, 'type', None) == 'col')
                    if is_column_chart:
                        column_chart_count += 1
                    try:
                        if hasattr(chart, 'series') and chart.series:
                            for series in chart.series:
                                if hasattr(series, 'val') and series.val:
                                    ref = str(series.val)
                                    if any((col in ref.upper() for col in ['B', 'C', 'D'])):
                                        charts_with_correct_data += 1
                                        break
                    except:
                        pass
            drawing_count = 0
            if hasattr(ws, '_drawings'):
                drawing_count = len(ws._drawings)
            elif hasattr(ws, '_images'):
                drawing_count = len(ws._images)
            chart_count = max(chart_count, drawing_count)
            result['chart_count'] = chart_count
            result['column_chart_count'] = column_chart_count
            result['charts_with_correct_data'] = charts_with_correct_data
            chart_col_idx = None
            if 'Chart' in headers:
                chart_col_idx = headers.index('Chart') + 1
            chart_cells_with_content = 0
            if chart_col_idx:
                for row in range(2, max_row + 1):
                    cell = ws.cell(row, chart_col_idx)
                    has_content = cell.value is not None or cell.hyperlink is not None or (hasattr(cell.fill, 'fgColor') and hasattr(cell.fill.fgColor, 'rgb') and (cell.fill.fgColor.rgb not in ['00000000', None]))
                    if has_content:
                        chart_cells_with_content += 1
            result['chart_cells_with_content'] = chart_cells_with_content
            wb.close()
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
    except ImportError:
        result['error'] = 'openpyxl not available - cannot parse file structure'
    except Exception as e:
        result['error'] = f'Failed to parse file: {str(e)}'
    return result

