def get_xlsx_dept_employees__343b0a84fd44790d4ed7b7f9379c462a(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract employees from a specific department in Excel file with full evaluation data.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'department' keys

    Returns:
        Dict containing employee names, department verification, column count, and headers
    """
    file_path = config.get('path', '/home/user/Desktop/IT_employees.xlsx')
    target_dept = config.get('department', 'IT')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'employees': [], 'has_evaluation_columns': False, 'department_verified': False, 'column_count': 0, 'headers': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        headers = []
        if ws.max_row > 0:
            for cell in ws[1]:
                if cell.value:
                    headers.append(str(cell.value))
        column_count = len(headers)
        employees = []
        all_departments_match = True
        dept_col_idx = None
        for (idx, header) in enumerate(headers):
            if header and ('department' in header.lower() or 'dept' in header.lower()):
                dept_col_idx = idx
                break
        for row_idx in range(2, ws.max_row + 1):
            row = ws[row_idx]
            employee_name = row[0].value
            if employee_name:
                employees.append(str(employee_name))
                if dept_col_idx is not None:
                    dept_value = row[dept_col_idx].value
                    if dept_value and str(dept_value).strip() != target_dept:
                        all_departments_match = False
        has_evaluation_columns = column_count >= 3
        return {'employees': employees, 'has_evaluation_columns': has_evaluation_columns, 'department_verified': all_departments_match and dept_col_idx is not None, 'column_count': column_count, 'headers': headers}
    finally:
        os.unlink(tmp_path)

def get_xlsx_specific_cells__b4f4e785(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Read specific cells from an XLSX file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', and 'cells' (list of cell addresses)

    Returns:
        Dict mapping cell addresses to their values
    """
    vm_path = config.get('path', '')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return {}
    wb = openpyxl.load_workbook(BytesIO(file_bytes), data_only=True)
    ws = wb.active
    cells_to_check = config.get('cells', [])
    result = {}
    for cell_addr in cells_to_check:
        try:
            cell_value = ws[cell_addr].value
            result[cell_addr] = cell_value
        except Exception:
            result[cell_addr] = None
    return result

