def get_pptx_table_cell_fill__c47e2298751cc0e01453918ec2689495(env, config):
    """Check if a specific table cell has a fill color.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (file path), 'slide_idx' (0-based),
                'shape_idx' (0-based), 'row' (0-based), 'col' (0-based)

    Returns:
        dict: {'has_fill': bool, 'rgb': tuple or None} - RGB tuple if solid fill exists
    """
    file_path = config['path']
    slide_idx = config['slide_idx']
    shape_idx = config['shape_idx']
    row = config['row']
    col = config['col']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'has_fill': False, 'rgb': None}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide = prs.slides[slide_idx]
        shape = slide.shapes[shape_idx]
        if shape.has_table:
            table = shape.table
            cell = table.rows[row].cells[col]
            if cell.fill.type == 1:
                rgb = cell.fill.fore_color.rgb
                return {'has_fill': True, 'rgb': (rgb[0], rgb[1], rgb[2])}
            elif cell.fill.type is not None and cell.fill.type != 0:
                return {'has_fill': True, 'rgb': None}
            else:
                return {'has_fill': False, 'rgb': None}
        return {'has_fill': False, 'rgb': None}
    finally:
        os.unlink(tmp_path)

