def get_xlsx_website_qty__57e581555e19ceb3db2669015c9e00b9(env, config: dict) -> Dict[str, Any]:
    """Extract verification data from Excel file including summary sheet and totals.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dictionary containing:
        - has_summary_sheet: bool, whether a new summary sheet exists
        - summary_data: dict mapping website to quantity from summary sheet
        - has_total_column: bool, whether Total Quantity column exists in original sheet
        - original_totals: dict mapping website to calculated total from original data
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_summary_sheet': False, 'summary_data': {}, 'has_total_column': False, 'original_totals': {}}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        summary_sheet_names = ['summary', 'total', 'totals', 'summary table', 'sheet2', 'sheet 2']
        has_summary_sheet = False
        summary_data = {}
        for sheet_name in wb.sheetnames:
            if sheet_name.lower() in summary_sheet_names or sheet_name.lower().strip() in summary_sheet_names:
                has_summary_sheet = True
                ws_summary = wb[sheet_name]
                for row in ws_summary.iter_rows(min_row=2, max_row=ws_summary.max_row, values_only=True):
                    if not any(row):
                        continue
                    if row[0] and row[1]:
                        website = row[0]
                        quantity = row[1]
                        if isinstance(quantity, (int, float)):
                            summary_data[website] = int(quantity)
                break
        ws_original = wb.worksheets[0]
        has_total_column = False
        original_totals = {}
        header_row = list(ws_original.iter_rows(min_row=1, max_row=1, values_only=True))[0]
        total_qty_col_idx = None
        for (idx, header) in enumerate(header_row):
            if header and 'total' in str(header).lower() and ('quantity' in str(header).lower()):
                has_total_column = True
                total_qty_col_idx = idx
                break
        for row in ws_original.iter_rows(min_row=2, max_row=ws_original.max_row, values_only=True):
            if not any(row):
                continue
            website = row[1] if len(row) > 1 else None
            quantity = row[4] if len(row) > 4 else None
            if website and quantity and isinstance(quantity, (int, float)):
                original_totals[website] = original_totals.get(website, 0) + int(quantity)
        return {'has_summary_sheet': has_summary_sheet, 'summary_data': summary_data, 'has_total_column': has_total_column, 'original_totals': original_totals}
    finally:
        os.unlink(tmp_path)

