def get_xlsx_max_cell_location__9aee970f(env, config: Dict[str, Any]) -> str:
    """Find the cell address containing the maximum value in a range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'range'

    Returns:
        Cell address (e.g., 'F17') containing the maximum value
    """
    file_path = config['path']
    sheet_idx = config.get('sheet', 0)
    cell_range = config['range']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        max_val = None
        max_cell = None
        for row in ws[cell_range]:
            for cell in row:
                if cell.value is not None:
                    try:
                        val = float(cell.value)
                        if max_val is None or val > max_val:
                            max_val = val
                            max_cell = cell.coordinate
                    except (ValueError, TypeError):
                        pass
        wb.close()
        return max_cell
    finally:
        import os
        os.unlink(tmp_path)

def get_calc_pivot_data__07645cd9da820827262a85cd65eb3825(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract pivot table data and Revenue column from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict containing:
        - revenue_column_check: whether Revenue column exists in Sheet1
        - revenue_formulas: sample formulas from Revenue column
        - revenue_values: sample calculated values
        - pivot table structure and data from Sheet2
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_formulas = openpyxl.load_workbook(tmp_path, data_only=False)
        wb_values = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb_values.sheetnames, 'has_sheet1': 'Sheet1' in wb_values.sheetnames or wb_values.sheetnames[0] if len(wb_values.sheetnames) > 0 else False, 'has_sheet2': 'Sheet2' in wb_values.sheetnames, 'revenue_column_exists': False, 'revenue_column_index': None, 'revenue_formulas': [], 'revenue_values': [], 'pivot_data': [], 'pivot_revenues': {}}
        sheet1_name = 'Sheet1' if 'Sheet1' in wb_values.sheetnames else wb_values.sheetnames[0] if len(wb_values.sheetnames) > 0 else None
        if sheet1_name:
            ws_formulas = wb_formulas[sheet1_name]
            ws_values = wb_values[sheet1_name]
            header_row = list(ws_values.iter_rows(min_row=1, max_row=1, values_only=True))[0]
            revenue_col_idx = None
            for (idx, cell_value) in enumerate(header_row):
                if cell_value and 'revenue' in str(cell_value).lower():
                    revenue_col_idx = idx
                    result['revenue_column_exists'] = True
                    result['revenue_column_index'] = idx
                    break
            if revenue_col_idx is not None:
                for row_idx in range(2, min(12, ws_formulas.max_row + 1)):
                    cell = ws_formulas.cell(row=row_idx, column=revenue_col_idx + 1)
                    if cell.value:
                        formula_str = str(cell.value) if isinstance(cell.value, str) else ''
                        result['revenue_formulas'].append({'row': row_idx, 'formula': formula_str, 'is_formula': formula_str.startswith('=')})
                for row_idx in range(2, min(12, ws_values.max_row + 1)):
                    cell_value = ws_values.cell(row=row_idx, column=revenue_col_idx + 1).value
                    if cell_value is not None:
                        try:
                            numeric_value = float(cell_value)
                            result['revenue_values'].append({'row': row_idx, 'value': numeric_value})
                        except (ValueError, TypeError):
                            pass
        if 'Sheet2' in wb_values.sheetnames:
            ws = wb_values['Sheet2']
            data = []
            for row in ws.iter_rows(min_row=1, max_row=ws.max_row, values_only=True):
                if any((cell is not None for cell in row)):
                    data.append([cell for cell in row])
            result['pivot_data'] = data
            result['max_row'] = ws.max_row
            result['max_col'] = ws.max_column
            for row in data:
                row_text = ' '.join([str(cell) for cell in row if cell is not None])
                for website in ['amazon.com', 'ebay.com', 'gel-boomerang.com', 'coloradoboomerangs.com']:
                    if website in row_text:
                        for cell in row:
                            if cell is not None and isinstance(cell, (int, float)):
                                if cell > 0:
                                    if website not in result['pivot_revenues']:
                                        result['pivot_revenues'][website] = cell
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

