def get_pptx_table_cells__13bac458(env, config):
    """Extract specific cell values from a PowerPoint table.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM file path to the PPTX file
            - dest: Destination filename in cache
            - slide_index: Index of the slide (0-based)
            - shape_index: Index of the table shape (0-based, default 1)
            - cells: List of dicts with 'row' and 'col' keys
            
    Returns:
        Dict mapping (row, col) tuples to cell text values
    """
    import os
    vm_path = config.get('path', '/home/user/Desktop/33_1.pptx')
    dest_filename = config.get('dest', '33_1.pptx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    cache_path = os.path.join(env.cache_dir, dest_filename)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    prs = Presentation(cache_path)
    slide_index = config.get('slide_index', 3)
    shape_index = config.get('shape_index', 1)
    cells_to_check = config.get('cells', [])
    if slide_index >= len(prs.slides):
        return {}
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return {}
    shape = slide.shapes[shape_index]
    if not shape.has_table:
        return {}
    table = shape.table
    result = {}
    for cell_spec in cells_to_check:
        row = cell_spec['row']
        col = cell_spec['col']
        if row < len(table.rows) and col < len(table.columns):
            cell = table.rows[row].cells[col]
            result[f'{row},{col}'] = cell.text.strip()
    return result

def get_calc_ratio_values__b2f2b4aac8cb13cbe4c4e471b7057d1e(env, config: dict) -> Optional[Dict[int, float]]:
    """Extract ratio values from a specific sheet in LibreOffice Calc.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'sheet_name'

    Returns:
        Dict mapping year to ratio value, or None if error
    """
    file_path = config.get('path')
    sheet_name = config.get('sheet_name', 'Sheet2')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return None
        ws = wb[sheet_name]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            year = row[0]
            ratio = row[1]
            if year is not None and ratio is not None:
                result[int(year)] = float(ratio)
        return result
    finally:
        os.unlink(tmp_path)

