def get_calc_cell_value__ee70f7015a4d2c160f5846a9698ce12f(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract a specific cell value and formula from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: File path on VM
            - sheet: Sheet index (0-based) or name
            - cell: Cell address (e.g., 'A1', 'C10')

    Returns:
        Dict with keys:
            - value: Cell value (calculated result)
            - formula: Cell formula (if present, else None)
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    cell_addr = config.get('cell', 'A1')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'value': None, 'formula': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
        if isinstance(sheet_idx, int):
            ws_formula = wb_formula.worksheets[sheet_idx]
        else:
            ws_formula = wb_formula[sheet_idx]
        cell = ws_formula[cell_addr]
        formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
        wb_formula.close()
        wb_value = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws_value = wb_value.worksheets[sheet_idx]
        else:
            ws_value = wb_value[sheet_idx]
        cell_value = ws_value[cell_addr].value
        wb_value.close()
        return {'value': cell_value, 'formula': formula}
    finally:
        os.unlink(tmp_path)

def get_xlsx_product_count__fa89493f9cd2099f47d3042a9aad8772(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract product transaction count from Sheet2.

    Supports both horizontal and vertical layouts:
    - Horizontal: Products as column headers in row 1, counts in row 2
    - Vertical: Products in column A, counts in column B (starting from row 2)

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with product names as keys and their transaction counts as values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if 'Sheet2' not in wb.sheetnames:
            return {}
        ws = wb['Sheet2']
        result = {}
        horizontal_headers = []
        for col_idx in range(1, ws.max_column + 1):
            header = ws.cell(1, col_idx).value
            if header:
                horizontal_headers.append((col_idx, str(header)))
        if len(horizontal_headers) >= 2 and ws.max_row >= 2:
            row_2_has_numbers = False
            for (col_idx, _) in horizontal_headers:
                value = ws.cell(2, col_idx).value
                if value is not None and isinstance(value, (int, float)):
                    row_2_has_numbers = True
                    break
            if row_2_has_numbers:
                for (col_idx, header) in horizontal_headers:
                    value = ws.cell(2, col_idx).value
                    if value is not None:
                        try:
                            result[header] = int(value)
                        except (ValueError, TypeError):
                            result[header] = value
                wb.close()
                if len(result) >= 10:
                    return result
        result = {}
        for row_idx in range(2, ws.max_row + 1):
            product_name = ws.cell(row_idx, 1).value
            count_value = ws.cell(row_idx, 2).value
            if product_name is not None and count_value is not None:
                try:
                    result[str(product_name)] = int(count_value)
                except (ValueError, TypeError):
                    try:
                        result[str(product_name)] = int(float(count_value))
                    except:
                        pass
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

