def get_xlsx_row_values__1e1c8fef409238e2677403d410317302(env, config):
    """Extract values from a specific row in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'row', and 'start_col'/'end_col' parameters

    Returns:
        List of cell values from the specified row
    """
    try:
        import openpyxl
    except ImportError:
        return []
    file_path = config.get('path')
    if not file_path:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        row_num = config.get('row')
        start_col = config.get('start_col', 'A')
        end_col = config.get('end_col', 'E')
        if row_num is None:
            return []
        start_idx = ord(start_col.upper()) - ord('A') + 1
        end_idx = ord(end_col.upper()) - ord('A') + 1
        values = []
        for col_idx in range(start_idx, end_idx + 1):
            cell_value = ws.cell(row=row_num, column=col_idx).value
            values.append(cell_value)
        return values
    finally:
        os.unlink(tmp_path)

