def get_xlsx_cell_value__70dc4f1c6278aab4c8eb1bc7361365aa(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract cell value and formula from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (0-indexed), 'cell' (e.g., 'B5')

    Returns:
        Dict with 'formula' (str or None) and 'value' (numeric, string, etc.)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cell_addr = config.get('cell', 'A1')
        cell = ws[cell_addr]
        result = {'formula': cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None, 'value': None}
        if result['formula']:
            wb.close()
            wb = openpyxl.load_workbook(tmp_path, data_only=True)
            ws = wb.worksheets[sheet_idx]
            result['value'] = ws[cell_addr].value
        else:
            result['value'] = cell.value
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

