def get_xlsx_min_mark_with_bold__4b06e5ed8197a71ac39c9ea9322f4951(env, config: dict) -> Dict[str, Any]:
    """Find minimum mark in Marks column and check which cell is bold.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'column' keys

    Returns:
        Dict with minimum value info and bold cell detection
    """
    file_path = config.get('path', '')
    column = config.get('column', 'C')
    start_row = config.get('start_row', 2)
    if not file_path:
        return {'min_value': None, 'min_cell': None, 'bold_cell': None, 'correct_cell_bold': False}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'min_value': None, 'min_cell': None, 'bold_cell': None, 'correct_cell_bold': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        ws = wb.active
        min_value = None
        min_cell = None
        bold_cells = []
        for row in range(start_row, ws.max_row + 1):
            cell_address = f'{column}{row}'
            cell = ws[cell_address]
            value = cell.value
            if cell.font and cell.font.bold:
                bold_cells.append(cell_address)
            if value is not None:
                try:
                    numeric_value = float(value)
                    if min_value is None or numeric_value < min_value:
                        min_value = numeric_value
                        min_cell = cell_address
                except (ValueError, TypeError):
                    pass
        correct_cell_bold = min_cell in bold_cells if min_cell else False
        result = {'min_value': min_value, 'min_cell': min_cell, 'bold_cells': bold_cells, 'correct_cell_bold': correct_cell_bold}
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_month_revenue_table__321ed1a008442c1379822ece597d5a12(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract month revenue table from a new sheet.
    Expects the agent to create a table with months and their total revenue.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'sheet_name'

    Returns:
        Dict with month names as keys and revenue values as floats
    """
    file_path = config.get('path', '/home/user/SummerSales.xlsx')
    sheet_name = config.get('sheet_name', 'Sheet2')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return {}
        ws = wb[sheet_name]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            month = str(row[0]).strip() if row[0] else None
            revenue = row[1] if row[1] is not None else 0.0
            if month:
                try:
                    revenue = float(revenue)
                except (ValueError, TypeError):
                    revenue = 0.0
                result[month] = revenue
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_autofilter_state__7f7184ff(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract AutoFilter state from Excel file, including filter criteria and visible rows.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet' (0-indexed)

    Returns:
        Dict with autofilter state: {
            "enabled": bool,
            "ref": str,
            "filtered_column": str or None,  # Name of the filtered column
            "filter_criteria": dict or None,  # Filter criteria info
            "visible_rows": list,  # List of visible row indices
            "visible_row_count": int  # Exact count of visible rows
        }
    """
    from desktop_env.evaluators.getters import file as file_getters
    local_path = file_getters.get_vm_file(env, config)
    wb = openpyxl.load_workbook(local_path, data_only=True)
    sheet_idx = config.get('sheet', 0)
    ws = wb.worksheets[sheet_idx]
    result = {'enabled': ws.auto_filter is not None, 'ref': str(ws.auto_filter.ref) if ws.auto_filter else None, 'filtered_column': None, 'filter_criteria': None, 'visible_rows': [], 'visible_row_count': 0}
    if ws.auto_filter is not None and ws.auto_filter.filterColumn:
        filter_ref = ws.auto_filter.ref
        if filter_ref:
            from openpyxl.utils import range_boundaries
            (min_col, min_row, max_col, max_row) = range_boundaries(filter_ref)
            header_row = list(ws.iter_rows(min_row=min_row, max_row=min_row, min_col=min_col, max_col=max_col, values_only=True))[0]
            for filter_col in ws.auto_filter.filterColumn:
                col_idx = filter_col.colId
                if col_idx < len(header_row):
                    col_name = header_row[col_idx]
                    if filter_col.customFilters is not None:
                        custom_filters = []
                        for cf in filter_col.customFilters.customFilter:
                            custom_filters.append({'operator': cf.operator, 'value': cf.val})
                        result['filtered_column'] = col_name
                        result['filter_criteria'] = {'column': col_name, 'custom_filters': custom_filters, 'and_logic': filter_col.customFilters._and}
                    elif filter_col.filters is not None:
                        result['filtered_column'] = col_name
                        result['filter_criteria'] = {'column': col_name, 'filters': list(filter_col.filters.filter), 'blank': filter_col.filters.blank}
    for row_idx in range(1, ws.max_row + 1):
        if not ws.row_dimensions[row_idx].hidden:
            result['visible_rows'].append(row_idx)
    result['visible_row_count'] = len(result['visible_rows'])
    wb.close()
    return result

