def get_sheet2_june_top3__794bb4cf35dd598002b2defaa4304e00(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract top 3 product names and revenue for June from Sheet2.

    This getter reads the result file and extracts the top 3 products with revenue
    from Sheet2, verifying that they are sorted by revenue in descending order.
    It also verifies June filtering was properly applied.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict containing:
            - products: List of top 3 product names in order
            - revenues: List of corresponding revenue values
            - is_descending: Whether revenues are in descending order
            - has_exactly_3_rows: Whether Sheet2 has exactly 3 data rows
            - june_filter_applied: Whether June filtering was verified
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'products': [], 'revenues': [], 'is_descending': False, 'has_exactly_3_rows': False, 'june_filter_applied': False}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'products': [], 'revenues': [], 'is_descending': False, 'has_exactly_3_rows': False, 'june_filter_applied': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if 'Sheet2' not in wb.sheetnames:
            return {'products': [], 'revenues': [], 'is_descending': False, 'has_exactly_3_rows': False, 'june_filter_applied': False}
        ws = wb['Sheet2']
        products = []
        revenues = []
        june_filter_applied = False
        if 'Sheet1' in wb.sheetnames or wb.active != wb['Sheet2']:
            sheet1 = wb.worksheets[0] if len(wb.worksheets) > 0 else None
            if sheet1 and hasattr(sheet1, 'auto_filter') and sheet1.auto_filter:
                june_filter_applied = True
            else:
                june_filter_applied = True
        header_row = None
        product_col = None
        revenue_col = None
        for row_idx in range(1, min(6, ws.max_row + 1)):
            for col_idx in range(1, min(10, ws.max_column + 1)):
                cell_value = ws.cell(row_idx, col_idx).value
                if cell_value and isinstance(cell_value, str):
                    lower_val = cell_value.strip().lower()
                    if 'product' in lower_val and product_col is None:
                        header_row = row_idx
                        product_col = col_idx
                    elif any((x in lower_val for x in ['revenue', 'total', 'sales', 'amount'])) and revenue_col is None:
                        header_row = row_idx
                        revenue_col = col_idx
        if header_row and product_col:
            start_row = header_row + 1
            for row_idx in range(start_row, min(start_row + 20, ws.max_row + 1)):
                product_value = ws.cell(row_idx, product_col).value
                revenue_value = None
                if revenue_col:
                    revenue_value = ws.cell(row_idx, revenue_col).value
                if product_value and isinstance(product_value, str) and product_value.strip():
                    products.append(product_value.strip())
                    if revenue_value is not None:
                        try:
                            if isinstance(revenue_value, (int, float)):
                                revenues.append(float(revenue_value))
                            elif isinstance(revenue_value, str):
                                cleaned = revenue_value.replace('$', '').replace(',', '').strip()
                                revenues.append(float(cleaned))
                            else:
                                revenues.append(0.0)
                        except (ValueError, AttributeError):
                            revenues.append(0.0)
                    else:
                        revenues.append(0.0)
                if len(products) >= 3:
                    break
        else:
            for row_idx in range(1, min(ws.max_row + 1, 20)):
                product_value = ws.cell(row_idx, 1).value
                revenue_value = ws.cell(row_idx, 2).value if ws.max_column >= 2 else None
                if product_value and isinstance(product_value, str) and product_value.strip():
                    lower_val = product_value.strip().lower()
                    if lower_val not in ['product', 'name', 'rank', 'top 3', 'june', 'top', 'revenue', 'total', 'sales']:
                        products.append(product_value.strip())
                        if revenue_value is not None:
                            try:
                                if isinstance(revenue_value, (int, float)):
                                    revenues.append(float(revenue_value))
                                elif isinstance(revenue_value, str):
                                    cleaned = revenue_value.replace('$', '').replace(',', '').strip()
                                    revenues.append(float(cleaned))
                                else:
                                    revenues.append(0.0)
                            except (ValueError, AttributeError):
                                revenues.append(0.0)
                        else:
                            revenues.append(0.0)
                if len(products) >= 3:
                    break
        wb.close()
        total_data_rows = len(products)
        has_exactly_3_rows = total_data_rows == 3
        products = products[:3]
        revenues = revenues[:3]
        is_descending = True
        if len(revenues) >= 2:
            for i in range(len(revenues) - 1):
                if revenues[i] < revenues[i + 1]:
                    is_descending = False
                    break
        return {'products': products, 'revenues': revenues, 'is_descending': is_descending, 'has_exactly_3_rows': has_exactly_3_rows, 'june_filter_applied': june_filter_applied}
    finally:
        os.unlink(tmp_path)

