def get_xlsx_empty_row_count__56032cbd(env, config: Dict[str, Any]):
    """Get comprehensive row and content data for verification of row deletion.

    This getter verifies the compaction task by:
    1. Counting empty vs data rows
    2. Checking sheet structure and compactness
    3. Extracting actual cell content to verify data preservation

    The task is to delete rows 2,4,6,8,10 (empty rows) from the original file,
    leaving only data rows compacted together.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'sheet', 'start_row'

    Returns:
        dict: Complete state for verification including:
            - empty_count: Number of empty rows
            - actual_max_row: Total row count
            - all_rows_have_data: True if no empty rows
            - data_starts_at_row_1: True if first row has data
            - is_fully_compact: True if fully compacted
            - sample_cell_values: Sample values to verify data preservation
    """
    file_content = env.controller.get_file(config['path'])
    if not file_content:
        return {'empty_count': 0, 'actual_max_row': 0, 'row_data': [], 'all_rows_have_data': False, 'data_starts_at_row_1': False, 'is_fully_compact': False, 'sample_cell_values': {}}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        start_row = config.get('start_row', 1)
        actual_max_row = ws.max_row
        empty_count = 0
        row_data = []
        first_data_row = None
        last_data_row = None
        sample_cell_values = {}
        for row_idx in range(start_row, actual_max_row + 1):
            row = list(ws.iter_rows(min_row=row_idx, max_row=row_idx, values_only=True))[0]
            is_empty = all((cell is None or cell == '' for cell in row))
            if is_empty:
                empty_count += 1
                row_data.append(False)
            else:
                row_data.append(True)
                if first_data_row is None:
                    first_data_row = row_idx
                last_data_row = row_idx
                for (col_idx, cell_value) in enumerate(row, start=1):
                    if cell_value is not None and cell_value != '':
                        key = f'R{row_idx}C{col_idx}'
                        sample_cell_values[key] = cell_value
        all_rows_have_data = empty_count == 0
        data_starts_at_row_1 = first_data_row == start_row if first_data_row else False
        is_fully_compact = all_rows_have_data and data_starts_at_row_1 and (actual_max_row > 0) and (len(row_data) == actual_max_row)
        return {'empty_count': empty_count, 'actual_max_row': actual_max_row, 'row_data': row_data, 'all_rows_have_data': all_rows_have_data, 'data_starts_at_row_1': data_starts_at_row_1, 'is_fully_compact': is_fully_compact, 'sample_cell_values': sample_cell_values}
    finally:
        os.unlink(tmp_path)

