def get_xlsx_cell_text__04e43e01(env, config):
    """
    Get both the displayed text and formula from a specific cell in an XLSX file.
    This reads both the formula and the calculated value to verify proper formula modification.

    Args:
        env: Environment object
        config: Configuration dict with 'path' (file path) and 'cell' (cell coordinate like 'D1')

    Returns:
        dict: Dictionary with 'text' (displayed value) and 'formula' (formula string)
    """
    xlsx_path = config['path']
    cell_coordinate = config['cell']
    wb_formula = openpyxl.load_workbook(xlsx_path, data_only=False)
    sheet_formula = wb_formula.active
    cell_formula = sheet_formula[cell_coordinate]
    formula = cell_formula.value if cell_formula.value else ''
    wb_value = openpyxl.load_workbook(xlsx_path, data_only=True)
    sheet_value = wb_value.active
    cell_value = sheet_value[cell_coordinate]
    displayed_text = cell_value.value if cell_value.value else ''
    return {'text': str(displayed_text), 'formula': str(formula)}

