def get_xlsx_avg_scores__58433466b03f9665710dd020bb3d6ede(env, config: Dict[str, Any]) -> Dict[str, float]:
    """
    Extract average performance scores from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for Excel file

    Returns:
        Dict mapping employee names to their average scores
    """
    file_path = config.get('path', '/home/user/Desktop/Employee Performance Evaluation Summary.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        last_col = ws.max_column
        header_cell = ws.cell(1, last_col)
        if header_cell.value != 'Average Score':
            return {}
        for row_idx in range(2, ws.max_row + 1):
            employee_name = ws.cell(row_idx, 1).value
            if employee_name is None:
                continue
            avg_value = ws.cell(row_idx, last_col).value
            if avg_value is not None:
                try:
                    result[employee_name] = float(avg_value)
                except (ValueError, TypeError):
                    result[employee_name] = 0.0
            else:
                result[employee_name] = 0.0
        return result
    finally:
        os.unlink(tmp_path)

