def get_calc_pivot_data__f6d5a0db6745bedf062e13e7470e2c1c(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract pivot table data and Total Revenue column from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict containing:
            - sheet1_data: Data from Sheet1 including headers and rows for Total Revenue verification
            - has_total_revenue_column: Whether 'Total Revenue' column exists in Sheet1
            - total_revenue_column_index: Index of Total Revenue column (if exists)
            - sample_rows: Sample rows to verify Total Revenue formula
            - has_sheet2: Whether Sheet2 exists
            - pivot_data: Data from Sheet2 (pivot table)
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb.sheetnames, 'has_sheet2': 'Sheet2' in wb.sheetnames, 'pivot_data': [], 'has_total_revenue_column': False, 'total_revenue_column_index': -1, 'sheet1_headers': [], 'sample_rows': []}
        if 'Sheet1' in wb.sheetnames or wb.active:
            ws1 = wb['Sheet1'] if 'Sheet1' in wb.sheetnames else wb.active
            headers = []
            for cell in ws1[1]:
                headers.append(cell.value)
            result['sheet1_headers'] = headers
            total_revenue_idx = -1
            for (idx, header) in enumerate(headers):
                if header and 'Total Revenue' in str(header):
                    total_revenue_idx = idx
                    result['has_total_revenue_column'] = True
                    result['total_revenue_column_index'] = idx
                    break
            quantity_idx = -1
            retail_price_idx = -1
            discount_idx = -1
            for (idx, header) in enumerate(headers):
                if header:
                    header_str = str(header).lower()
                    if 'quantity' in header_str:
                        quantity_idx = idx
                    elif 'retail price' in header_str:
                        retail_price_idx = idx
                    elif 'discount' in header_str:
                        discount_idx = idx
            result['quantity_column_index'] = quantity_idx
            result['retail_price_column_index'] = retail_price_idx
            result['discount_column_index'] = discount_idx
            sample_rows = []
            for row_idx in range(2, min(7, ws1.max_row + 1)):
                row_data = []
                for cell in ws1[row_idx]:
                    row_data.append(cell.value)
                sample_rows.append(row_data)
            result['sample_rows'] = sample_rows
        if 'Sheet2' in wb.sheetnames:
            ws = wb['Sheet2']
            data = []
            for row in ws.iter_rows(min_row=1, max_row=ws.max_row, values_only=True):
                if any((cell is not None for cell in row)):
                    data.append([cell for cell in row])
            result['pivot_data'] = data
            result['max_row'] = ws.max_row
            result['max_col'] = ws.max_column
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

