def get_xlsx_cell_o3_v7__d4477d7a(env, config: dict):
    """Extract grading data from grades.xlsx including cell O3 and all student scores.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Contains 'o3_value' (name in O3), 'students' (list of student grading data)
    """
    path = config.get('path', '/home/user/exam/grades.xlsx')
    file_content = env.controller.get_file(path)
    if file_content is None:
        return None
    with tempfile.NamedTemporaryFile(mode='wb', suffix='.xlsx', delete=False) as f:
        f.write(file_content)
        temp_path = f.name
    try:
        wb = openpyxl.load_workbook(temp_path, data_only=True)
        ws = wb.active
        o3_value = ws['O3'].value
        students = []
        for row in range(2, 15):
            name_cell = ws.cell(row=row, column=1).value
            if name_cell is None or str(name_cell).strip() == '':
                continue
            student_name = str(name_cell).strip()
            question_scores = []
            for col in range(2, 12):
                score = ws.cell(row=row, column=col).value
                question_scores.append(score)
            total_score = ws.cell(row=row, column=12).value
            if total_score is None:
                total_score = ws.cell(row=row, column=13).value
            students.append({'name': student_name, 'question_scores': question_scores, 'total_score': total_score})
        wb.close()
        return {'o3_value': o3_value, 'students': students}
    finally:
        if os.path.exists(temp_path):
            os.unlink(temp_path)

