def get_xlsx_cell_value__479fedbb(env, config: dict):
    """
    Get spreadsheet data to verify:
    1. Receipt data was imported
    2. Transactions are sorted by amount descending
    3. Office Supplies entry with amount -50.00 exists

    Returns dict with:
    - 'transactions': list of (description, amount) tuples
    - 'office_supplies_found': bool
    - 'office_supplies_amount': float or None
    - 'is_sorted_descending': bool
    """
    import openpyxl
    import io
    vm_path = config.get('path', '/home/user/Desktop/my_bookkeeping.xlsx')
    sheet_idx = config.get('sheet', 0)
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return None
    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)
    ws = wb.worksheets[sheet_idx] if isinstance(sheet_idx, int) else wb[sheet_idx]
    transactions = []
    row_num = 2
    while True:
        desc_cell = ws[f'A{row_num}']
        amount_cell = ws[f'B{row_num}']
        if desc_cell.value is None and amount_cell.value is None:
            break
        desc = desc_cell.value
        amount = amount_cell.value
        try:
            amount_val = float(amount) if amount is not None else None
        except (ValueError, TypeError):
            amount_val = None
        transactions.append((desc, amount_val))
        row_num += 1
        if row_num > 1000:
            break
    wb.close()
    office_supplies_found = False
    office_supplies_amount = None
    for (desc, amount) in transactions:
        if desc and 'office supplies' in str(desc).lower():
            office_supplies_found = True
            office_supplies_amount = amount
            break
    amounts = [amt for (_, amt) in transactions if amt is not None]
    is_sorted_descending = all((amounts[i] >= amounts[i + 1] for i in range(len(amounts) - 1))) if len(amounts) > 1 else True
    transaction_count = len(transactions)
    return {'transactions': transactions, 'transaction_count': transaction_count, 'office_supplies_found': office_supplies_found, 'office_supplies_amount': office_supplies_amount, 'is_sorted_descending': is_sorted_descending}

