def get_xlsx_range_border__a4dde445(env, config):
    """Get the border coverage ratio for a range of cells.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - 'path': Path to xlsx file in VM
            - 'dest': Destination filename
            - 'sheet': Sheet index (int) or name (str)
            - 'range': Cell range string like "A1:E4"

    Returns:
        float: Ratio of cells with borders (0.0 to 1.0)
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    file_path = get_vm_file(env, {'path': config['path'], 'dest': config['dest']})
    if file_path is None:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return 0.0
    try:
        wb = openpyxl.load_workbook(file_path)
        if isinstance(config['sheet'], int):
            ws = wb.worksheets[config['sheet']]
        else:
            ws = wb[config['sheet']]
        cell_range = config['range']
        cells_with_borders = 0
        total_cells = 0
        for row in ws[cell_range]:
            for cell in row:
                total_cells += 1
                if cell.border:
                    border = cell.border
                    if any([border.left and border.left.style, border.right and border.right.style, border.top and border.top.style, border.bottom and border.bottom.style]):
                        cells_with_borders += 1
        if total_cells == 0:
            logger.warning(f'No cells found in range {cell_range}')
            return 0.0
        border_ratio = cells_with_borders / total_cells
        logger.info(f'Border coverage: {cells_with_borders}/{total_cells} = {border_ratio:.2%}')
        return border_ratio
    except Exception as e:
        logger.error(f'Error checking borders: {e}')
        return 0.0

