def get_xlsx_channel_revenue__9a6ef448bb28a5c30ab547d089d0e653(env, config: Dict[str, Any]) -> Dict[str, float]:
    """Extract sales channel revenue totals from Sheet2.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict mapping channel names to revenue totals
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if 'Sheet2' not in wb.sheetnames:
            return {}
        ws = wb['Sheet2']
        channel_revenue = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            channel = str(row[0]).strip()
            revenue = row[1] if row[1] is not None else 0
            try:
                revenue = float(revenue)
            except (ValueError, TypeError):
                revenue = 0.0
            channel_revenue[channel] = revenue
        return channel_revenue
    finally:
        os.unlink(tmp_path)

def get_xlsx_first_data_row__111d61ba2744b826f5515ac1d880fd8e(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Get the first data row (row 2) from an Excel file to verify sorting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict with column values from the first data row, or None if file not accessible
    """
    file_path = config.get('path', '')
