def get_xlsx_cell_value__33744580(env, config):
    """Get the value and formula of a specific cell from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path' (VM file path), 'sheet' (index), and 'cell' (address)

    Returns:
        Dict with 'value' (cell result) and 'has_formula' (bool indicating if cell contains formula)
    """
    file_path = config.get('path', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    temp_path = '/tmp/temp_excel_file_v6.xlsx'
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        wb = openpyxl.load_workbook(temp_path, data_only=False)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cell_addr = config.get('cell', 'A1')
        cell = ws[cell_addr]
        has_formula = False
        if cell.value is not None:
            cell_str = str(cell.value)
            has_formula = cell_str.startswith('=')
        wb.close()
        wb_data = openpyxl.load_workbook(temp_path, data_only=True)
        ws_data = wb_data.worksheets[sheet_idx]
        cell_data = ws_data[cell_addr]
        calculated_value = cell_data.value
        wb_data.close()
        if os.path.exists(temp_path):
            os.remove(temp_path)
        return {'value': calculated_value, 'has_formula': has_formula}
    except Exception as e:
        print(f'Error getting cell value: {e}')
        if os.path.exists(temp_path):
            os.remove(temp_path)
        return None

def get_xlsx_friday_cells__3d829d2d9ec2788176cef7f984aa8bcc(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract cells containing Friday dates and their fill colors.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path)

    Returns:
        Dict mapping cell coordinates to their fill colors for Friday cells
    """
    file_bytes = env.controller.get_file(config['path'])
