def get_xlsx_pass_rate__f8b504052f710b7b32e3afdc9352bffb(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Read cells A12 (label) and A13 (value) to verify user added passing rate.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to Excel file

    Returns:
        Dict with 'label' (str from A12) and 'value' (numeric from A13)
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'label': None, 'value': None}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'label': None, 'value': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        label_cell = ws.cell(row=12, column=1).value
        label = str(label_cell) if label_cell is not None else None
        value_cell = ws.cell(row=13, column=1).value
        value = None
        if value_cell is not None:
            if isinstance(value_cell, (int, float)):
                value = float(value_cell)
            elif isinstance(value_cell, str):
                import re
                match = re.search('(\\d+\\.?\\d*)', value_cell)
                if match:
                    value = float(match.group(1))
        return {'label': label, 'value': value}
    finally:
        os.unlink(tmp_path)

def get_calc_chart_exists__50439adde6397002012f7c336f44c36b(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Check if a chart exists in the specified sheet and verify summary table.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM file path
            - sheet: Sheet name or index

    Returns:
        Dict with:
            - sheet_exists: bool
            - chart_exists: bool
            - chart_count: int
            - has_pie_chart: bool
            - table_exists: bool
            - table_structure_correct: bool
            - table_data_correct: bool
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'sheet_exists': False, 'chart_exists': False, 'chart_count': 0, 'has_pie_chart': False, 'table_exists': False, 'table_structure_correct': False, 'table_data_correct': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet = config.get('sheet', 0)
        sheet_exists = False
        ws = None
        try:
            if isinstance(sheet, int):
                if sheet < len(wb.worksheets):
                    ws = wb.worksheets[sheet]
                    sheet_exists = True
            elif sheet in wb.sheetnames:
                ws = wb[sheet]
                sheet_exists = True
        except:
            pass
        if not sheet_exists or ws is None:
            return {'sheet_exists': False, 'chart_exists': False, 'chart_count': 0, 'has_pie_chart': False, 'table_exists': False, 'table_structure_correct': False, 'table_data_correct': False}
        chart_count = len(ws._charts) if hasattr(ws, '_charts') else 0
        chart_exists = chart_count > 0
        has_pie_chart = False
        if hasattr(ws, '_charts'):
            for chart in ws._charts:
                chart_type = chart.__class__.__name__
                if 'Pie' in chart_type:
                    has_pie_chart = True
                    break
        table_exists = False
        table_structure_correct = False
        table_data_correct = False
        try:
            a1 = ws['A1'].value
            a2 = ws['A2'].value
            a3 = ws['A3'].value
            b1 = ws['B1'].value
            b2 = ws['B2'].value
            b3 = ws['B3'].value
            if a1 is not None and a2 is not None and (a3 is not None):
                table_exists = True
                a1_str = str(a1).strip().lower() if a1 else ''
                a2_str = str(a2).strip().lower() if a2 else ''
                a3_str = str(a3).strip().lower() if a3 else ''
                if ('sex' in a1_str or a1_str in ['sex', 'gender']) and a2_str == 'female' and (a3_str == 'male'):
                    table_structure_correct = True
                    try:
                        b2_val = int(b2) if b2 is not None else None
                        b3_val = int(b3) if b3 is not None else None
                        if b2_val == 17 and b3_val == 23:
                            table_data_correct = True
                    except (ValueError, TypeError):
                        pass
        except:
            pass
        return {'sheet_exists': sheet_exists, 'chart_exists': chart_exists, 'chart_count': chart_count, 'has_pie_chart': has_pie_chart, 'table_exists': table_exists, 'table_structure_correct': table_structure_correct, 'table_data_correct': table_data_correct}
    finally:
        os.unlink(tmp_path)

