def get_xlsx_autofilter_state__b1637b1b0888330d6a80aa2fd33f5ff1(env, config):
    """Get AutoFilter state and visible row data for verification.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', optional 'sheet' (index), and 'sales_column' (e.g., 'C')

    Returns:
        dict: {
            'autofilter_applied': bool,
            'visible_rows': list of dicts with row data,
            'visible_count': int,
            'sales_values': list of sales values from visible rows
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'autofilter_applied': False, 'visible_rows': [], 'visible_count': 0, 'sales_values': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        autofilter_applied = ws.auto_filter is not None and ws.auto_filter.ref is not None
        sales_column = config.get('sales_column', 'C')
        visible_rows = []
        sales_values = []
        sales_col_idx = openpyxl.utils.column_index_from_string(sales_column)
        for row_num in range(2, ws.max_row + 1):
            row_dimension = ws.row_dimensions.get(row_num)
            if row_dimension is None or not row_dimension.hidden:
                row_cells = list(ws[row_num])
                has_data = any((cell.value is not None for cell in row_cells))
                if has_data:
                    row_data = {}
                    for (idx, cell) in enumerate(row_cells, start=1):
                        row_data[f'col_{idx}'] = cell.value
                    visible_rows.append(row_data)
                    sales_cell = ws.cell(row=row_num, column=sales_col_idx)
                    sales_value = sales_cell.value
                    if sales_value is not None:
                        try:
                            sales_value = float(sales_value)
                        except (ValueError, TypeError):
                            pass
                        sales_values.append(sales_value)
        return {'autofilter_applied': autofilter_applied, 'visible_rows': visible_rows, 'visible_count': len(visible_rows), 'sales_values': sales_values}
    finally:
        os.unlink(tmp_path)

