def get_xlsx_highlight_f16b8851(vm_file_path, env):
    """Get all cell highlighting information and mark values from the spreadsheet

    When using type='vm_file', the framework downloads the file and passes
    the local file path as the first parameter.

    Args:
        vm_file_path: Local path to the downloaded xlsx file
        env: Environment object

    Returns:
        dict: Contains highlighting information and mark values for all rows
    """
    import openpyxl
    from openpyxl.styles import PatternFill
    import os
    if not os.path.exists(vm_file_path):
        return {'highlights': {}, 'marks': {}}
    wb = openpyxl.load_workbook(vm_file_path)
    ws = wb.worksheets[0]
    highlights = {}
    marks = {}
    for row in ws.iter_rows():
        row_num = row[0].row
        highlights[row_num] = {}
        for cell in row:
            col = cell.column_letter
            if cell.fill and cell.fill.patternType != 'none':
                highlights[row_num][col] = {'has_fill': True, 'color': cell.fill.fgColor.rgb if hasattr(cell.fill.fgColor, 'rgb') else None}
            else:
                highlights[row_num][col] = {'has_fill': False}
            if col == 'C' and cell.value is not None:
                try:
                    mark_value = float(cell.value)
                    marks[row_num] = mark_value
                except (ValueError, TypeError):
                    pass
    wb.close()
    return {'highlights': highlights, 'marks': marks}

