def get_xlsx_cell_text__a7cae53b(env, config: Dict[str, Any]) -> str:
    """Read cell text/display value from an Excel file.

    This function extracts the displayed text from a specific cell in an Excel file.
    For cells containing formulas, it returns the calculated/displayed value.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file on VM
            - cell: Cell address (e.g., "D1")
            - sheet: (optional) Sheet index (0-based) or sheet name

    Returns:
        str: The text content displayed in the cell
    """
    file_path = config.get('path')
    cell_addr = config.get('cell')
    sheet_idx = config.get('sheet', 0)
    with open(file_path, 'rb') as f:
        file_content = f.read()
    wb = openpyxl.load_workbook(BytesIO(file_content), data_only=True)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    cell = ws[cell_addr]
    cell_value = cell.value
    if cell_value is None:
        result = ''
    else:
        result = str(cell_value)
    wb.close()
    return result

