def get_calc_sheet_duplication__86bfa89a4b4d2f7a30a182edda1be610(env, config: dict) -> Dict[str, Any]:
    """Check for duplicated sheets by comparing content and names.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'count', 'names', and 'duplicates' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'count': 0, 'names': [], 'duplicates': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_names = wb.sheetnames
        count = len(sheet_names)
        duplicates = []
        for i in range(len(sheet_names)):
            for j in range(i + 1, len(sheet_names)):
                ws1 = wb[sheet_names[i]]
                ws2 = wb[sheet_names[j]]
                if ws1.max_row != ws2.max_row or ws1.max_column != ws2.max_column:
                    continue
                identical = True
                for row in range(1, ws1.max_row + 1):
                    for col in range(1, ws1.max_column + 1):
                        val1 = ws1.cell(row, col).value
                        val2 = ws2.cell(row, col).value
                        if val1 != val2:
                            identical = False
                            break
                    if not identical:
                        break
                if identical:
                    duplicates.append({'original': sheet_names[i], 'copy': sheet_names[j]})
        wb.close()
        return {'count': count, 'names': sheet_names, 'duplicates': duplicates}
    finally:
        os.unlink(tmp_path)

