def get_pivot_promo_count__93aac26f(env, config):
    """Extract pivot table count data from Sheet2 for Promotion analysis.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest'

    Returns:
        dict: Promotion names with their counts
    """
    vm_path = config.get('path', '/home/user/EntireSummerSales.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    cache_path = os.path.join(env.cache_dir, config.get('dest', 'EntireSummerSales.xlsx'))
    os.makedirs(os.path.dirname(cache_path), exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    if 'Sheet2' not in wb.sheetnames:
        wb.close()
        return {}
    ws = wb['Sheet2']
    data = {}
    rows = list(ws.iter_rows(values_only=True))
    if len(rows) < 2:
        wb.close()
        return {}
    promotions = ['Fall Kite Event', 'Festival of Flight', 'None']
    header_row = rows[0]
    for (col_idx, cell_value) in enumerate(header_row):
        if cell_value in promotions:
            if len(rows) > 1 and rows[1][col_idx] is not None:
                try:
                    data[cell_value] = int(float(rows[1][col_idx]))
                except (ValueError, TypeError):
                    pass
    if not data:
        for row in rows:
            if row[0] in promotions and len(row) > 1:
                try:
                    data[row[0]] = int(float(row[1]))
                except (ValueError, TypeError):
                    pass
    wb.close()
    return data

