def get_xlsx_sort_order__788b32067564e90fc9f3953e49a93c08(env, config: dict):
    """Check if a column is sorted in specified order.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column', 'start_row', 'end_row'

    Returns:
        dict: {'is_descending': bool, 'is_ascending': bool, 'values': list}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'is_descending': False, 'is_ascending': False, 'values': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(config['sheet'], int):
            ws = wb.worksheets[config['sheet']]
        else:
            ws = wb[config['sheet']]
        column = config['column']
        start_row = config['start_row']
        end_row = config['end_row']
        values = []
        for row in range(start_row, end_row + 1):
            cell_value = ws[f'{column}{row}'].value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                values.append(cell_value)
        is_descending = False
        is_ascending = False
        if values:
            is_descending = all((values[i] >= values[i + 1] for i in range(len(values) - 1)))
            is_ascending = all((values[i] <= values[i + 1] for i in range(len(values) - 1)))
        wb.close()
        return {'is_descending': is_descending, 'is_ascending': is_ascending, 'values': values}
    finally:
        os.unlink(tmp_path)

