def get_xlsx_content_with_arxiv__a8c92c109f6527d3fddb6472a1422a04(env, config: dict) -> Dict[str, Any]:
    """Get content from Excel sheet and validate arXiv papers with structural validation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key (VM file path)

    Returns:
        Dict with row_count, arxiv_count, dates_oct_11_count, and structural validation info
    """
    import re
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'row_count': 0, 'arxiv_count': 0, 'dates_oct_11_count': 0, 'valid_arxiv_url_count': 0, 'valid_title_count': 0, 'rows': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        row_count = 0
        arxiv_count = 0
        dates_oct_11_count = 0
        valid_arxiv_url_count = 0
        valid_title_count = 0
        rows_data = []
        arxiv_url_pattern = re.compile('arxiv\\.org/(abs|pdf)/\\d{4}\\.\\d{4,5}', re.IGNORECASE)
        for row_idx in range(2, ws.max_row + 1):
            col_a = ws.cell(row=row_idx, column=1).value
            col_b = ws.cell(row=row_idx, column=2).value
            col_c = ws.cell(row=row_idx, column=3).value
            title = str(col_a).strip() if col_a is not None else ''
            pdf_link = str(col_b).strip() if col_b is not None else ''
            date_str = str(col_c).strip() if col_c is not None else ''
            if not title and (not pdf_link) and (not date_str):
                continue
            row_count += 1
            row_data = {'title': title, 'pdf_link': pdf_link, 'date': date_str}
            rows_data.append(row_data)
            if arxiv_url_pattern.search(pdf_link):
                valid_arxiv_url_count += 1
                arxiv_count += 1
            elif 'arxiv' in pdf_link.lower():
                arxiv_count += 1
            if title and len(title) > 0:
                valid_title_count += 1
            row_text = f'{title} {pdf_link} {date_str}'.lower()
            if any((date_pattern in row_text for date_pattern in ['2023-10-11', 'oct 11, 2023', 'oct 11 2023', 'october 11, 2023', 'october 11 2023', '10/11/2023', '2023/10/11', '11-oct-2023', '11 oct 2023', '11 october 2023'])):
                dates_oct_11_count += 1
        return {'row_count': row_count, 'arxiv_count': arxiv_count, 'dates_oct_11_count': dates_oct_11_count, 'valid_arxiv_url_count': valid_arxiv_url_count, 'valid_title_count': valid_title_count, 'rows': rows_data}
    finally:
        os.unlink(tmp_path)

