def get_xlsx_row_count__85449039(env, config: dict):
    """Get comprehensive information about CSV and XLSX export files.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for XLSX file

    Returns:
        dict: Information about both CSV and XLSX files including:
            - csv_exists: bool
            - csv_row_count: int
            - csv_has_data: bool
            - xlsx_exists: bool
            - xlsx_row_count: int
            - xlsx_has_valid_structure: bool
            - xlsx_has_contact_data: bool
    """
    xlsx_path = config.get('path', '')
    csv_path = xlsx_path.replace('.xlsx', '.csv')
    result = {'csv_exists': False, 'csv_row_count': 0, 'csv_has_data': False, 'xlsx_exists': False, 'xlsx_row_count': 0, 'xlsx_has_valid_structure': False, 'xlsx_has_contact_data': False}
    try:
        csv_bytes = env.controller.get_file(csv_path)
        if csv_bytes:
            result['csv_exists'] = True
            csv_content = csv_bytes.decode('utf-8', errors='ignore')
            csv_reader = csv.reader(io.StringIO(csv_content))
            rows = list(csv_reader)
            if len(rows) > 1:
                result['csv_row_count'] = len(rows) - 1
                data_rows = rows[1:]
                non_empty_rows = [row for row in data_rows if any((cell.strip() for cell in row))]
                result['csv_has_data'] = len(non_empty_rows) > 0
    except Exception:
        pass
    try:
        xlsx_bytes = env.controller.get_file(xlsx_path)
        if xlsx_bytes:
            result['xlsx_exists'] = True
            wb = openpyxl.load_workbook(io.BytesIO(xlsx_bytes), data_only=True)
            ws = wb.active
            data_row_count = 0
            has_contact_data = False
            header_row = [cell.value for cell in ws[1]] if ws.max_row >= 1 else []
            header_str = ' '.join([str(h).lower() for h in header_row if h])
            thunderbird_indicators = ['name', 'email', 'phone', 'display', 'address']
            result['xlsx_has_valid_structure'] = any((indicator in header_str for indicator in thunderbird_indicators))
            for (row_idx, row) in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
                if any((cell for cell in row)):
                    data_row_count += 1
                    if not has_contact_data:
                        for cell in row:
                            if cell and isinstance(cell, str) and (len(cell.strip()) > 0):
                                if '@' in cell or 2 <= len(cell.strip()) <= 50:
                                    has_contact_data = True
                                    break
            result['xlsx_row_count'] = data_row_count
            result['xlsx_has_contact_data'] = has_contact_data
    except Exception:
        pass
    return result

