def get_xlsx_data_completeness__474c917112587e81f547539c35fd0dc4(env, config: dict) -> Dict[str, int]:
    """Get data completeness statistics for specified columns.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'columns', and optional 'start_row' keys

    Returns:
        Dict[str, int]: Dictionary with column names as keys and non-empty cell count as values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        columns = config.get('columns', ['A', 'B', 'C'])
        start_row = config.get('start_row', 2)
        result = {}
        for col in columns:
            count = 0
            for row_idx in range(start_row, ws.max_row + 1):
                cell = ws[f'{col}{row_idx}']
                if cell.value is not None and str(cell.value).strip():
                    count += 1
            result[col] = count
        return result
    finally:
        os.unlink(tmp_path)

