def get_xlsx_rep_totals__31fece5ebadbc8a9d152ebc50d1167b1(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract sales rep total values and highlighting information from Excel file.

    Checks:
    - Column H contains total sales for each rep (rows 2-11)
    - The top performer (row with max total) is highlighted

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for file location

    Returns:
        Dict with:
        - 'totals': dict mapping row_idx to total value in column H
        - 'top_row': row index with maximum total
        - 'highlighted_rows': list of row indices that have fill color in column H
    """
    file_path = config.get('path', '/home/user/SalesRep.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'totals': {}, 'top_row': None, 'highlighted_rows': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        totals = {}
        highlighted_rows = []
        for row_idx in range(2, 12):
            cell = ws.cell(row=row_idx, column=8)
            totals[str(row_idx)] = cell.value if cell.value is not None else 0
            if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
                rgb = cell.fill.start_color.rgb
                if rgb not in ['FFFFFFFF', '00000000', 'FF000000']:
                    highlighted_rows.append(row_idx)
        top_row = int(max(totals.keys(), key=lambda k: totals[k])) if totals else None
        return {'totals': totals, 'top_row': top_row, 'highlighted_rows': highlighted_rows}
    finally:
        os.unlink(tmp_path)

def get_xlsx_summary_cell__31b8161206cf6d67e6a822439cf2dca7(env, config: Dict[str, Any]) -> Optional[int]:
    """Extract the restaurant count from a summary cell in the Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'cell' keys

    Returns:
        Integer value from the summary cell, or None if not found
    """
    file_path = config.get('path', '')
    cell_address = config.get('cell', 'A8')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        cell_value = ws[cell_address].value
        if cell_value is not None:
            try:
                return int(cell_value)
            except (ValueError, TypeError):
                if isinstance(cell_value, str):
                    import re
                    match = re.search('\\d+', cell_value)
                    if match:
                        return int(match.group())
        return None
    finally:
        os.unlink(tmp_path)

