def get_xlsx_first_age_format__af4c468f(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get the first age value from an Excel file and check its decimal format.

    This function reads the Excel file and gets the first age value from column D
    to verify that it has been formatted with decimal places (e.g., 56.73 years
    instead of 56).

    Args:
        env: Environment object
        config: Configuration dict with 'path' and 'sheet' keys

    Returns:
        dict: Dictionary with 'age_value' (the first age), 'decimal_places' (number of decimal places),
              'is_decimal_format' (bool), and 'all_age_values' (list of all ages)
    """
    try:
        file_path = config.get('path')
        sheet_idx = config.get('sheet', 0)
        if not file_path:
            logger.error('No file path provided in config')
            return {'age_value': None, 'decimal_places': 0, 'is_decimal_format': False}
        wb = openpyxl.load_workbook(file_path, data_only=True)
        if isinstance(sheet_idx, int):
            sheet = wb.worksheets[sheet_idx]
        else:
            sheet = wb[sheet_idx]
        ages = []
        row = 2
        while True:
            age_cell = sheet[f'D{row}'].value
            if age_cell is None:
                break
            ages.append(age_cell)
            row += 1
        wb.close()
        if not ages:
            logger.warning('No age values found in column D')
            return {'age_value': None, 'decimal_places': 0, 'is_decimal_format': False, 'all_age_values': []}
        age_details = []
        for age in ages:
            decimal_places = 0
            is_decimal_format = False
            if isinstance(age, (int, float)):
                age_str = str(age)
                if '.' in age_str:
                    decimal_part = age_str.split('.')[1]
                    decimal_places = len(decimal_part)
                    if decimal_places > 0:
                        is_decimal_format = True
            age_details.append({'value': age, 'decimal_places': decimal_places, 'is_decimal_format': is_decimal_format})
        result = {'age_value': ages[0] if ages else None, 'decimal_places': age_details[0]['decimal_places'] if age_details else 0, 'is_decimal_format': age_details[0]['is_decimal_format'] if age_details else False, 'all_age_values': ages, 'all_age_details': age_details}
        logger.info(f"First age value: {(ages[0] if ages else None)}, decimal places: {(age_details[0]['decimal_places'] if age_details else 0)}")
        logger.info(f'Found {len(ages)} age values total')
        return result
    except Exception as e:
        logger.error(f'Error reading Excel file: {e}')
        return {'age_value': None, 'decimal_places': 0, 'is_decimal_format': False, 'all_age_values': []}

def get_xlsx_url_format__cd916c3d(env, config: Dict[str, Any]) -> Dict[str, int]:
    """Count valid URLs and total non-empty URLs in a column that match a specific pattern.

    Returns a dict with:
    - valid_count: Number of URLs matching the required pattern
    - total_count: Total number of non-empty cells in the column
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'B')
    try:
        wb = openpyxl.load_workbook(file_path, data_only=True)
        if sheet_idx >= len(wb.sheetnames):
            return {'valid_count': 0, 'total_count': 0}
        ws = wb[wb.sheetnames[sheet_idx]]
        valid_count = 0
        total_count = 0
        for row_idx in range(2, ws.max_row + 1):
            cell_value = ws[f'{column}{row_idx}'].value
            if cell_value is not None:
                url_str = str(cell_value).strip()
                if url_str:
                    total_count += 1
                    if url_str.startswith('https://arxiv.org/pdf/') and url_str.endswith('.pdf'):
                        valid_count += 1
        return {'valid_count': valid_count, 'total_count': total_count}
    except Exception:
        return {'valid_count': 0, 'total_count': 0}

