def get_calc_pivot_data__bac7fe0d6051276645651bb32f4904a6(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract data from LibreOffice Calc file including main sheet and pivot table.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict containing:
        - Main sheet data with Total Sales column check
        - Pivot table structure and data from Sheet2
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        wb_values = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb.sheetnames, 'has_sheet2': 'Sheet2' in wb.sheetnames, 'pivot_data': [], 'main_sheet': {}, 'total_sales_column': {}}
        main_sheet_name = wb.sheetnames[0] if wb.sheetnames else None
        if main_sheet_name:
            ws = wb[main_sheet_name]
            ws_values = wb_values[main_sheet_name]
            headers = []
            header_row = list(ws.iter_rows(min_row=1, max_row=1, values_only=True))
            if header_row:
                headers = [str(cell).strip() if cell else '' for cell in header_row[0]]
            total_sales_idx = -1
            for (idx, header) in enumerate(headers):
                if 'total sales' in header.lower():
                    total_sales_idx = idx
                    break
            result['main_sheet'] = {'name': main_sheet_name, 'headers': headers, 'has_total_sales_column': total_sales_idx >= 0, 'total_sales_column_index': total_sales_idx}
            if total_sales_idx >= 0:
                total_sales_values = []
                total_sales_formulas = []
                for row_idx in range(2, min(ws.max_row + 1, 100)):
                    cell = ws.cell(row=row_idx, column=total_sales_idx + 1)
                    cell_value = ws_values.cell(row=row_idx, column=total_sales_idx + 1).value
                    if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
                        total_sales_formulas.append(cell.value)
                    if cell_value is not None and cell_value != 0:
                        try:
                            total_sales_values.append(float(cell_value))
                        except (ValueError, TypeError):
                            pass
                result['total_sales_column'] = {'has_formulas': len(total_sales_formulas) > 0, 'formula_count': len(total_sales_formulas), 'has_nonzero_values': len(total_sales_values) > 0, 'nonzero_value_count': len(total_sales_values), 'sample_values': total_sales_values[:5] if total_sales_values else []}
                quantity_idx = -1
                retail_price_idx = -1
                for (idx, header) in enumerate(headers):
                    if 'quantity' in header.lower():
                        quantity_idx = idx
                    if 'retail price' in header.lower():
                        retail_price_idx = idx
                if quantity_idx >= 0 and retail_price_idx >= 0:
                    correct_calculations = 0
                    total_checks = 0
                    for row_idx in range(2, min(ws.max_row + 1, 20)):
                        quantity = ws_values.cell(row=row_idx, column=quantity_idx + 1).value
                        retail_price = ws_values.cell(row=row_idx, column=retail_price_idx + 1).value
                        total_sales = ws_values.cell(row=row_idx, column=total_sales_idx + 1).value
                        if quantity is not None and retail_price is not None and (total_sales is not None):
                            try:
                                expected = float(quantity) * float(retail_price)
                                actual = float(total_sales)
                                if abs(expected - actual) < 0.01:
                                    correct_calculations += 1
                                total_checks += 1
                            except (ValueError, TypeError):
                                pass
                    result['total_sales_column']['calculation_check'] = {'correct': correct_calculations, 'total': total_checks, 'accuracy': correct_calculations / total_checks if total_checks > 0 else 0}
        if 'Sheet2' in wb.sheetnames:
            ws2 = wb_values['Sheet2']
            data = []
            for row in ws2.iter_rows(min_row=1, max_row=ws2.max_row, values_only=True):
                if any((cell is not None for cell in row)):
                    data.append([cell for cell in row])
            result['pivot_data'] = data
            result['max_row'] = ws2.max_row
            result['max_col'] = ws2.max_column
            if len(data) >= 2:
                has_products = False
                has_aggregated_values = False
                if len(data[0]) >= 2:
                    numeric_count = 0
                    for row in data[1:]:
                        if len(row) >= 2 and row[1] is not None:
                            try:
                                float(row[1])
                                numeric_count += 1
                            except (ValueError, TypeError):
                                pass
                    has_aggregated_values = numeric_count > 0
                    has_products = len(data) > 1
                result['pivot_structure'] = {'has_proper_structure': has_products and has_aggregated_values, 'row_count': len(data), 'col_count': len(data[0]) if data else 0}
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

