def get_pptx_table_cell__a3cedc3e0e28fe4280948f304196dcd6(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract value from a specific table cell.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: Path to the PPTX file on VM
            - slide_index: 0-based slide index
            - table_index: Index of table in slide (0 for first table)
            - row_index: Row index
            - col_index: Column index

    Returns:
        Dict with cell value
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'cell_value': ''}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide_index = config.get('slide_index', 0)
        table_index = config.get('table_index', 0)
        row_index = config.get('row_index', 0)
        col_index = config.get('col_index', 0)
        if slide_index >= len(prs.slides):
            return {'cell_value': ''}
        slide = prs.slides[slide_index]
        tables = [shape for shape in slide.shapes if shape.has_table]
        if table_index >= len(tables):
            return {'cell_value': ''}
        table = tables[table_index].table
        if row_index >= len(table.rows) or col_index >= len(table.columns):
            return {'cell_value': ''}
        cell = table.rows[row_index].cells[col_index]
        cell_value = cell.text.strip()
        return {'cell_value': cell_value}
    finally:
        os.unlink(tmp_path)

def get_xlsx_row_alignment__d0395a1e(env, config):
    """Check if all cells in a row have center alignment.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'file_path', 'sheet', 'row'

    Returns:
        bool: True if all cells are center-aligned, False otherwise
    """
    file_path = config.get('file_path')
    sheet_idx = config.get('sheet', 0)
    row_num = config.get('row', 1)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return False
    import os
    cache_path = os.path.join(env.cache_dir, os.path.basename(file_path))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    for cell in ws[row_num]:
        if cell.value:
            if not cell.alignment or cell.alignment.horizontal != 'center':
                return False
    return True

