def get_calc_cell_value__a8896662f47f9f0431d9d6ec0b20825a(env, config: Dict[str, Any]) -> Any:
    """Extract cell value and formula from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'sheet' (sheet index), 'cell' (cell address)

    Returns:
        Dict with 'value' (formatted display value), 'formula' (cell formula or None), 'source_cell' (referenced cell address)
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cell_addr = config.get('cell', 'A1')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'value': None, 'formula': None, 'source_cell': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
        if isinstance(sheet_idx, int):
            ws_formula = wb_formula.worksheets[sheet_idx]
        else:
            ws_formula = wb_formula[sheet_idx]
        cell_formula_obj = ws_formula[cell_addr]
        cell_formula = cell_formula_obj.value if isinstance(cell_formula_obj.value, str) and cell_formula_obj.value.startswith('=') else None
        source_cell_addr = config.get('source_cell', 'C1')
        source_cell = ws_formula[source_cell_addr]
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell = ws[cell_addr]
        cell_value = cell.value
        source_value = ws[source_cell_addr].value
        formatted_value = None
        if isinstance(cell_value, str):
            formatted_value = cell_value
        elif isinstance(cell_value, (int, float)) and cell.number_format:
            number_format = cell.number_format
            if number_format == 'General' or not number_format:
                formatted_value = cell_value
            else:
                decimal_count = _extract_decimal_places(number_format)
                if decimal_count is not None and decimal_count >= 0:
                    formatted_value = f'{cell_value:.{decimal_count}f}'
                else:
                    formatted_value = cell_value
        else:
            formatted_value = cell_value
        return {'value': formatted_value, 'formula': cell_formula, 'source_cell': source_cell_addr, 'source_value': source_value, 'numeric_value': cell_value if isinstance(cell_value, (int, float)) else None}
    finally:
        os.unlink(tmp_path)

