def get_xlsx_cell_formula__3ceaf93e7e3923c3f1aa1d93f7fb2bd0(env, config):
    """Get formula or value from a specific cell with structured data.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell'

    Returns:
        dict: {'type': 'formula'/'value', 'content': formula_string, 'value': computed_value}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'type': 'empty', 'content': '', 'value': ''}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cell_address = config['cell']
        cell = ws[cell_address]
        if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
            formula_content = cell.value
            wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
            ws_data = wb_data.worksheets[sheet_idx]
            cell_value = ws_data[cell_address].value
            computed_value = str(cell_value) if cell_value is not None else ''
            return {'type': 'formula', 'content': formula_content, 'value': computed_value}
        else:
            cell_value = cell.value
            value_str = str(cell_value) if cell_value is not None else ''
            return {'type': 'value', 'content': value_str, 'value': value_str}
    finally:
        os.unlink(tmp_path)

