def get_xlsx_cell_value__3d0a4b14(env, config):
    """Get a specific cell value and format from an Excel file.

    Retrieves the value from a specified cell in an Excel file along with its
    number format. Uses openpyxl with data_only=True to read calculated formula
    values rather than formula text. This is important for verifying cells that
    should contain calculated results with specific formatting.

    Args:
        env: DesktopEnv instance with controller.get_file method
        config: Dict with required keys:
            - 'path': str, path to Excel file in VM (e.g., '/home/user/file.xlsx')
            - 'sheet': int, 0-indexed sheet number (default: 0)
            - 'cell': str, cell address in A1 notation (e.g., 'A32')

    Returns:
        Dict with:
            - 'value': Cell value (number, string, or None)
            - 'number_format': Cell number format string
            - 'decimal_places': Number of decimal places (if numeric format), or None
    """
    file_content = env.controller.get_file(config['path'])
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[config.get('sheet', 0)]
        cell = ws[config['cell']]
        cell_value = cell.value
        number_format = cell.number_format
        decimal_places = None
        if number_format and isinstance(number_format, str):
            if '.00' in number_format and '.000' not in number_format:
                decimal_places = 2
            elif '.0' in number_format and '.00' not in number_format:
                decimal_places = 1
            import re
            match = re.search('\\.0+', number_format)
            if match:
                decimal_places = len(match.group()) - 1
        wb.close()
        return {'value': cell_value, 'number_format': number_format, 'decimal_places': decimal_places}
    finally:
        os.unlink(tmp_path)

