def get_xlsx_monday_highlights__e30a5624b4752f570e12c94fdf3cd346(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract background colors from Monday and non-Monday date cells in the calendar.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict with:
            - 'monday_cells': Dict mapping Monday cell coordinates to their background colors
            - 'non_monday_cells': Dict mapping non-Monday cell coordinates to their background colors
            - 'monday_count': Number of Monday cells found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'monday_cells': {}, 'non_monday_cells': {}, 'monday_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        monday_cells = {}
        non_monday_cells = {}
        for row_idx in range(3, ws.max_row + 1):
            for col_idx in range(2, ws.max_column + 1):
                cell = ws.cell(row_idx, col_idx)
                value = cell.value
                if isinstance(value, datetime):
                    day_of_week = value.weekday()
                    bg_color = None
                    if cell.fill and cell.fill.start_color:
                        rgb = cell.fill.start_color.rgb
                        if rgb and rgb != '00000000':
                            bg_color = rgb
                    if day_of_week == 0:
                        monday_cells[cell.coordinate] = bg_color
                    else:
                        non_monday_cells[cell.coordinate] = bg_color
        return {'monday_cells': monday_cells, 'non_monday_cells': non_monday_cells, 'monday_count': len(monday_cells)}
    finally:
        os.unlink(tmp_path)

