def get_calc_summary_table__90b218be1c4dab8fc11a057cd0823a2d(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract comprehensive summary table data from a LibreOffice Calc file.

    Reads specified cells from a sheet and returns their values, headers, labels, and formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM file path (e.g., "/home/user/file.xlsx")
            - sheet: Sheet name or index
            - cells: List of cell addresses to extract (e.g., ["B2", "B3", "B4"])

    Returns:
        Dict with:
            - sheet_exists: bool - whether the specified sheet exists
            - sheet_name: str - actual sheet name found
            - headers: dict - header cell values (A1, B1)
            - labels: dict - category labels in column A (A2-A9)
            - values: dict - count values in cells
            - header_bold: bool - whether header row has bold formatting
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'sheet_exists': False, 'sheet_name': None, 'headers': {}, 'labels': {}, 'values': {}, 'header_bold': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        sheet_name = config.get('sheet', 0)
        sheet_exists = False
        actual_sheet_name = None
        ws = None
        if isinstance(sheet_name, str):
            if sheet_name in wb.sheetnames:
                sheet_exists = True
                actual_sheet_name = sheet_name
                ws = wb[sheet_name]
        elif sheet_name < len(wb.worksheets):
            sheet_exists = True
            ws = wb.worksheets[sheet_name]
            actual_sheet_name = ws.title
        if not sheet_exists or ws is None:
            return {'sheet_exists': False, 'sheet_name': actual_sheet_name, 'headers': {}, 'labels': {}, 'values': {}, 'header_bold': False}
        headers = {'A1': ws['A1'].value, 'B1': ws['B1'].value}
        labels = {}
        for i in range(2, 10):
            cell_addr = f'A{i}'
            labels[cell_addr] = ws[cell_addr].value
        values = {}
        cells = config.get('cells', [])
        for cell_addr in cells:
            cell = ws[cell_addr]
            values[cell_addr] = cell.value
        header_bold = False
        a1_font = ws['A1'].font
        b1_font = ws['B1'].font
        if a1_font and b1_font:
            header_bold = a1_font.bold is True and b1_font.bold is True
        return {'sheet_exists': sheet_exists, 'sheet_name': actual_sheet_name, 'headers': headers, 'labels': labels, 'values': values, 'header_bold': header_bold}
    finally:
        os.unlink(tmp_path)

