def get_xlsx_gross_profit_calculations__87606b1393cde1435f28787ed7fdd477(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Extract Gross Profit column values and verify calculations.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'sheet' keys

    Returns:
        Dict with gross_profit values and average, or None if not found
    """
    file_path = config.get('path', '')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        gross_profit_values = []
        net_sales_values = []
        cogs_values = []
        for row in range(3, 12):
            gp_cell = f'J{row}'
            gp_value = ws[gp_cell].value
            ns_cell = f'E{row}'
            ns_value = ws[ns_cell].value
            cogs_cell = f'I{row}'
            cogs_value = ws[cogs_cell].value
            if gp_value is not None:
                gross_profit_values.append(float(gp_value))
            else:
                gross_profit_values.append(None)
            if ns_value is not None:
                net_sales_values.append(float(ns_value))
            else:
                net_sales_values.append(None)
            if cogs_value is not None:
                cogs_values.append(float(cogs_value))
            else:
                cogs_values.append(None)
        j12_value = ws['J12'].value
        j12_float = float(j12_value) if j12_value is not None else None
        return {'gross_profit_values': gross_profit_values, 'net_sales_values': net_sales_values, 'cogs_values': cogs_values, 'average_in_j12': j12_float}
    finally:
        os.unlink(tmp_path)

def get_xlsx_negative_cells_fill__f2066837d948b1e5b873bbbe987d4804(env, config: Dict[str, Any]) -> Dict[str, bool]:
    """Get fill status of cells with negative values in a column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column' (e.g., 'E'), 'start_row', 'end_row'

    Returns:
        Dict mapping cell addresses to their fill status (True if highlighted, False otherwise)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        column = config.get('column', 'E')
        start_row = config.get('start_row', 2)
        end_row = config.get('end_row', ws.max_row)
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        ws_data = wb_data.worksheets[sheet_idx]
        result = {}
        for row_idx in range(start_row, end_row + 1):
            cell_addr = f'{column}{row_idx}'
            cell_value = ws_data[cell_addr].value
            if cell_value is not None and isinstance(cell_value, (int, float)) and (cell_value < 0):
                cell = ws[cell_addr]
                fill = cell.fill
                has_fill = fill and fill.fgColor and (fill.fgColor.rgb is not None)
                result[cell_addr] = has_fill
        return result
    finally:
        os.unlink(tmp_path)

