def get_xlsx_excellent_students__9dbd35c0(env, config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Get list of students with excellent performance (marks >= 90).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'name_col', 'marks_col', 'message_col', 'start_row', 'end_row'

    Returns:
        List of dicts with student info
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    name_col = config.get('name_col', 'D')
    marks_col = config.get('marks_col', 'E')
    message_col = config.get('message_col', 'F')
    start_row = config.get('start_row', 10)
    end_row = config.get('end_row', 23)
    excellence_threshold = config.get('excellence_threshold', 90)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        excellent = []
        for row in range(start_row, end_row + 1):
            name = ws[f'{name_col}{row}'].value
            marks = ws[f'{marks_col}{row}'].value
            message = ws[f'{message_col}{row}'].value
            if name and marks is not None:
                try:
                    marks_val = float(marks)
                    if marks_val >= excellence_threshold:
                        excellent.append({'name': name, 'marks': int(marks_val), 'message': message})
                except:
                    pass
        wb.close()
        return excellent
    finally:
        os.unlink(tmp_path)

