            has_fill = False
            fill_color = None
            for col in range(ord(start_col) - ord('A') + 1, ord(end_col) - ord('A') + 2):
                cell = ws.cell(row, col)
                if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
                    has_fill = True
                    fill_color = cell.fill.start_color.rgb
