def get_xlsx_column_with_max__8bf637877595257165c4a6a22d46c629(env, config: dict):
    """Extract column values, header, highlighting, and verify calculations.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column' (e.g., 'D'), 'start_row', 'end_row'

    Returns:
        dict: {
            'max_value': float,
            'max_row': int,
            'values': list,
            'header': str,
            'max_row_highlighted': bool,
            'calculations_correct': bool
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'max_value': None, 'max_row': None, 'values': [], 'header': None, 'max_row_highlighted': False, 'calculations_correct': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(config['sheet'], int):
            ws = wb.worksheets[config['sheet']]
        else:
            ws = wb[config['sheet']]
        column = config['column']
        start_row = config['start_row']
        end_row = config['end_row']
        header_cell = ws[f'{column}1']
        header = header_cell.value if header_cell.value else ''
        values = []
        for row in range(start_row, end_row + 1):
            cell_value = ws[f'{column}{row}'].value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                values.append((row, cell_value))
        if not values:
            wb.close()
            return {'max_value': None, 'max_row': None, 'values': [], 'header': header, 'max_row_highlighted': False, 'calculations_correct': False}
        (max_row, max_value) = max(values, key=lambda x: x[1])
        max_cell = ws[f'{column}{max_row}']
        max_row_highlighted = False
        if max_cell.fill and max_cell.fill.start_color:
            fill_color = max_cell.fill.start_color.rgb if hasattr(max_cell.fill.start_color, 'rgb') else None
            if fill_color and fill_color not in [None, 'FFFFFFFF', 'FFFFFF', '00000000']:
                max_row_highlighted = True
            elif max_cell.fill.fgColor and hasattr(max_cell.fill.fgColor, 'rgb'):
                fg_color = max_cell.fill.fgColor.rgb
                if fg_color and fg_color not in [None, 'FFFFFFFF', 'FFFFFF', '00000000']:
                    max_row_highlighted = True
        calculations_correct = True
        for row in range(start_row, end_row + 1):
            sales_value = ws[f'B{row}'].value
            cogs_value = ws[f'C{row}'].value
            profit_value = ws[f'{column}{row}'].value
            if isinstance(sales_value, (int, float)) and isinstance(cogs_value, (int, float)):
                expected_profit = sales_value - cogs_value
                if not isinstance(profit_value, (int, float)):
                    calculations_correct = False
                    break
                if abs(profit_value - expected_profit) > 0.01:
                    calculations_correct = False
                    break
        wb.close()
        return {'max_value': max_value, 'max_row': max_row, 'values': [v[1] for v in values], 'header': header, 'max_row_highlighted': max_row_highlighted, 'calculations_correct': calculations_correct}
    finally:
        os.unlink(tmp_path)

