def get_xlsx_month_revenue__43be5c9d919db67e68321af1a7a3a2fe(env, config: Dict[str, Any]) -> Dict[str, float]:
    """Extract month revenue totals from Sheet2.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict mapping month names to revenue totals
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if 'Sheet2' not in wb.sheetnames:
            return {}
        ws = wb['Sheet2']
        month_revenue = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            month = str(row[0]).strip()
            revenue = row[1] if row[1] is not None else 0
            try:
                revenue = float(revenue)
            except (ValueError, TypeError):
                revenue = 0.0
            month_revenue[month] = revenue
        return month_revenue
    finally:
        os.unlink(tmp_path)

