def get_xlsx_expense_tracker__ecafb42348e3ea2fad5499358cc20d1b(env, config):
    """
    Extract expense tracker data from a LibreOffice Calc .xlsx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the .xlsx file on VM

    Returns:
        dict: Dictionary containing file existence, sheet info, and header information
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'exists': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        sheet_name = wb.sheetnames[0] if wb.sheetnames else None
        row_count = ws.max_row
        col_count = ws.max_column
        headers = []
        if row_count > 0:
            for col in range(1, col_count + 1):
                cell_value = ws.cell(row=1, column=col).value
                if cell_value is not None:
                    headers.append(str(cell_value).lower().strip())
                else:
                    headers.append('')
        expense_keywords = ['category', 'categories', 'expense', 'amount', 'cost', 'price', 'date', 'description', 'item', 'type']
        has_expense_related = any((any((keyword in header for keyword in expense_keywords)) for header in headers if header))
        has_category_column = any(('categor' in header for header in headers if header))
        wb.close()
        return {'exists': True, 'sheet_name': sheet_name, 'row_count': row_count, 'col_count': col_count, 'headers': headers, 'has_expense_related': has_expense_related, 'has_category_column': has_category_column, 'has_content': row_count > 0 and col_count > 0}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

