def get_xlsx_cell_fill__221d67c04da52c0453686cc2aeea4f23(env, config: dict):
    """Extract values from a range and check which cell with max value has fill.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM path to Excel file),
                'sheet' (sheet index, default 0), and 'range' (e.g., 'C5:F5')

    Returns:
        Dict with:
        - 'range_values': dict mapping cell addresses to their values
        - 'max_cell': cell address with maximum value
        - 'max_value': the maximum value
        - 'max_cell_has_fill': bool indicating if max cell has fill
        - 'max_cell_fill_color': hex color or None
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cell_range = config.get('range', 'C5:F5')
    if not file_path:
        return {'range_values': {}, 'max_cell': None, 'max_value': None, 'max_cell_has_fill': False, 'max_cell_fill_color': None}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'range_values': {}, 'max_cell': None, 'max_value': None, 'max_cell_has_fill': False, 'max_cell_fill_color': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        range_values = {}
        max_cell = None
        max_value = None
        for row in ws[cell_range]:
            for cell in row:
                value = cell.value
                if value is not None:
                    try:
                        numeric_value = float(value)
                        range_values[cell.coordinate] = numeric_value
                        if max_value is None or numeric_value > max_value:
                            max_value = numeric_value
                            max_cell = cell.coordinate
                    except (ValueError, TypeError):
                        range_values[cell.coordinate] = value
        wb_format = openpyxl.load_workbook(tmp_path, data_only=False)
        if isinstance(sheet_idx, int):
            ws_format = wb_format.worksheets[sheet_idx]
        else:
            ws_format = wb_format[sheet_idx]
        max_cell_has_fill = False
        max_cell_fill_color = None
        if max_cell:
            cell = ws_format[max_cell]
            fill = cell.fill
            if fill and fill.fill_type:
                if fill.fill_type == 'solid':
                    max_cell_has_fill = True
                    if fill.start_color and fill.start_color.rgb:
                        max_cell_fill_color = str(fill.start_color.rgb)
                elif fill.fill_type == 'pattern':
                    max_cell_has_fill = True
                    if fill.fgColor and fill.fgColor.rgb:
                        max_cell_fill_color = str(fill.fgColor.rgb)
        return {'range_values': range_values, 'max_cell': max_cell, 'max_value': max_value, 'max_cell_has_fill': max_cell_has_fill, 'max_cell_fill_color': max_cell_fill_color}
    except Exception as e:
        print(f'Error reading Excel range and fill: {e}')
        return {'range_values': {}, 'max_cell': None, 'max_value': None, 'max_cell_has_fill': False, 'max_cell_fill_color': None}
    finally:
        os.unlink(tmp_path)

