def get_xlsx_acl_papers__72ecdcff(env, config: Dict[str, Any]) -> List[Dict[str, str]]:
    """
    Extract paper entries from ACL awards spreadsheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file
            - sheet: Sheet index (0-based)
            - start_row: First data row (1-based, default: 2)

    Returns:
        List of dicts with keys: title, year, authors, url
    """
    path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    start_row = config.get('start_row', 2)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return []
    cache_path = os.path.join(env.cache_dir, os.path.basename(path))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    ws = wb.worksheets[sheet_idx]
    papers = []
    for row_idx in range(start_row, ws.max_row + 1):
        title_value = ws[f'A{row_idx}'].value
        year_value = ws[f'B{row_idx}'].value
        authors_value = ws[f'C{row_idx}'].value
        url_value = ws[f'D{row_idx}'].value
        if title_value or url_value:
            papers.append({'title': str(title_value).strip() if title_value else '', 'year': str(year_value).strip() if year_value else '', 'authors': str(authors_value).strip() if authors_value else '', 'url': str(url_value).strip() if url_value else ''})
    wb.close()
    return papers

