def get_xlsx_yoy_improvements__448da0ed8ffeaba2b2b1df2e1f2bd873(env, config: Dict[str, Any]) -> Dict[str, int]:
    """Extract year-over-year improvement count for a specific university from Excel file.

    This function reads an Excel file containing university pass rates over multiple years,
    extracts the pass rates for the specified university, and counts how many times
    the pass rate improved compared to the previous year.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - 'path': Path to the Excel file
            - 'university': Name of the university to analyze (e.g., 'HKUST')

    Returns:
        Dictionary with 'improvement_count' key containing the number of year-over-year improvements
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'improvement_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        university = config.get('university', 'HKUST')
        university_col_idx = None
        for col_idx in range(1, ws.max_column + 1):
            cell_value = ws.cell(1, col_idx).value
            if cell_value and str(cell_value).strip() == university:
                university_col_idx = col_idx
                break
        if university_col_idx is None:
            return {'improvement_count': 0}
        year_rates = []
        for row_idx in range(2, ws.max_row + 1):
            year_cell = ws.cell(row_idx, 1).value
            rate_cell = ws.cell(row_idx, university_col_idx).value
            if year_cell is None or rate_cell is None:
                continue
            try:
                if isinstance(rate_cell, str):
                    rate_cell = rate_cell.strip('%')
                rate_value = float(rate_cell)
            except (ValueError, AttributeError):
                continue
            try:
                year = int(year_cell)
            except (ValueError, TypeError):
                continue
            year_rates.append((year, rate_value))
        year_rates.sort(key=lambda x: x[0])
        improvement_count = 0
        for i in range(1, len(year_rates)):
            prev_rate = year_rates[i - 1][1]
            curr_rate = year_rates[i][1]
            if curr_rate > prev_rate:
                improvement_count += 1
        return {'improvement_count': improvement_count}
    finally:
        os.unlink(tmp_path)

