def get_calc_line_chart__0f492b286ccfa81ae15bde7a08cd32e6(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract line chart information from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict containing chart properties including data ranges, series count, and column usage
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_chart': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        import openpyxl
        from openpyxl.chart import LineChart
        wb = openpyxl.load_workbook(tmp_path)
        ws = wb.active
        charts = list(ws._charts)
        if not charts:
            return {'has_chart': False}
        result = {'has_chart': True, 'chart_count': len(charts)}
        for chart in charts:
            if isinstance(chart, LineChart):
                result['has_line_chart'] = True
                result['chart_type'] = 'line'
                series_list = []
                data_ranges = []
                columns_used = set()
                total_data_points = 0
                for series in chart.series:
                    series_info = {}
                    if hasattr(series, 'val') and series.val:
                        val_ref = str(series.val)
                        series_info['data_range'] = val_ref
                        data_ranges.append(val_ref)
                        if '!' in val_ref:
                            range_part = val_ref.split('!')[-1]
                            import re
                            cols = re.findall('\\$([A-Z]+)\\$', range_part)
                            columns_used.update(cols)
                            rows = re.findall('\\$\\d+', range_part)
                            if len(rows) == 2:
                                start_row = int(rows[0].replace('$', ''))
                                end_row = int(rows[1].replace('$', ''))
                                series_info['data_point_count'] = end_row - start_row + 1
                                total_data_points += series_info['data_point_count']
                    if hasattr(series, 'cat') and series.cat:
                        cat_ref = str(series.cat)
                        series_info['category_range'] = cat_ref
                    series_list.append(series_info)
                result['series_count'] = len(series_list)
                result['series_details'] = series_list
                result['data_ranges'] = data_ranges
                result['columns_used'] = list(columns_used)
                result['total_data_points'] = total_data_points
                has_2019_range = any(('B3:' in dr and 'B14' in dr for dr in data_ranges))
                has_2020_range = any(('B20:' in dr and 'B31' in dr for dr in data_ranges))
                result['has_2019_data'] = has_2019_range
                result['has_2020_data'] = has_2020_range
                result['uses_column_b'] = 'B' in columns_used
                return result
        result['has_line_chart'] = False
        return result
    finally:
        os.unlink(tmp_path)

