def get_xlsx_summary_sheet__d86c810e(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Get the summary statistics from a LibreOffice Calc xlsx file.
    This getter expects a Summary sheet to contain statistics for Revenue and Total Expenses.

    Config:
        path (str): absolute path on the VM to fetch
        dest (str): file name of the downloaded file

    Returns:
        Dict with structure:
        {
            "sheet_name": str,  # Name of the sheet (should be "Summary")
            "revenue_total": float,  # Total (sum) of revenue
            "revenue_avg": float,  # Average revenue
            "revenue_max": float,  # Maximum revenue
            "revenue_min": float,  # Minimum revenue
            "expenses_total": float,  # Total (sum) of expenses
            "expenses_avg": float,  # Average expenses
            "expenses_max": float,  # Maximum expenses
            "expenses_min": float  # Minimum expenses
        }
        or None if file cannot be read
    """
    path = config['path']
    dest = config['dest']
    cache_path = os.path.join(env.cache_dir, dest)
    try:
        file_content = env.controller.get_file(path)
        if file_content is None:
            logger.warning(f'Failed to get file from VM: {path}')
            return None
        os.makedirs(env.cache_dir, exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_content)
        logger.info(f'Successfully saved file: {cache_path}')
    except Exception as e:
        logger.error(f'Error getting file from VM: {e}')
        return None
    try:
        workbook = openpyxl.load_workbook(cache_path)
        if 'Summary' not in workbook.sheetnames:
            logger.warning(f'Summary sheet not found in workbook. Available sheets: {workbook.sheetnames}')
            return None
        summary_sheet = workbook['Summary']
        result = {'sheet_name': 'Summary', 'revenue_total': None, 'revenue_avg': None, 'revenue_max': None, 'revenue_min': None, 'expenses_total': None, 'expenses_avg': None, 'expenses_max': None, 'expenses_min': None}
        for row_idx in range(1, summary_sheet.max_row + 1):
            label = summary_sheet.cell(row_idx, 1).value
            if label is None:
                continue
            label_lower = str(label).lower().strip()
            revenue_val = summary_sheet.cell(row_idx, 2).value
            expenses_val = summary_sheet.cell(row_idx, 3).value
            if 'total' in label_lower or 'sum' in label_lower:
                try:
                    result['revenue_total'] = float(revenue_val) if revenue_val is not None else None
                    result['expenses_total'] = float(expenses_val) if expenses_val is not None else None
                except (ValueError, TypeError) as e:
                    logger.warning(f'Error converting total values at row {row_idx}: {e}')
            elif 'average' in label_lower or 'avg' in label_lower:
                try:
                    result['revenue_avg'] = float(revenue_val) if revenue_val is not None else None
                    result['expenses_avg'] = float(expenses_val) if expenses_val is not None else None
                except (ValueError, TypeError) as e:
                    logger.warning(f'Error converting average values at row {row_idx}: {e}')
            elif 'maximum' in label_lower or 'max' in label_lower:
                try:
                    result['revenue_max'] = float(revenue_val) if revenue_val is not None else None
                    result['expenses_max'] = float(expenses_val) if expenses_val is not None else None
                except (ValueError, TypeError) as e:
                    logger.warning(f'Error converting maximum values at row {row_idx}: {e}')
            elif 'minimum' in label_lower or 'min' in label_lower:
                try:
                    result['revenue_min'] = float(revenue_val) if revenue_val is not None else None
                    result['expenses_min'] = float(expenses_val) if expenses_val is not None else None
                except (ValueError, TypeError) as e:
                    logger.warning(f'Error converting minimum values at row {row_idx}: {e}')
        logger.info(f'Extracted summary statistics: {result}')
        return result
    except Exception as e:
        logger.error(f'Error reading xlsx file: {e}')
        return None

