def get_xlsx_populated_rows__46f371eb(env, config):
    """
    Get the count of rows with complete data in columns B, C, D.
    Checks that data from column A was properly split into:
    - Column B: First Names
    - Column C: Last Names
    - Column D: Ranks

    A row is considered "complete" if all three fields (B, C, D) are populated.

    Args:
        env: Environment object
        config: Configuration dict with 'path' and 'sheet' keys

    Returns:
        dict: Dictionary with:
            - total_rows: Total number of non-empty rows
            - complete_rows: Number of rows with all three fields populated
            - incomplete_rows: Number of rows missing one or more fields
    """
    path = config['path']
    sheet_idx = config.get('sheet', 0)
    wb = openpyxl.load_workbook(path)
    if isinstance(sheet_idx, int):
        sheet = wb.worksheets[sheet_idx]
    else:
        sheet = wb[sheet_idx]
    total_rows = 0
    complete_rows = 0
    incomplete_rows = 0
    for row in sheet.iter_rows(min_row=2, min_col=1, max_col=4):
        col_a = row[0].value if row[0].value else ''
        col_b = row[1].value if row[1].value else ''
        col_c = row[2].value if row[2].value else ''
        col_d = row[3].value if row[3].value else ''
        if col_a or col_b or col_c or col_d:
            total_rows += 1
            first_name = str(col_b).strip() if col_b else ''
            last_name = str(col_c).strip() if col_c else ''
            rank = str(col_d).strip() if col_d else ''
            if first_name and last_name and rank:
                complete_rows += 1
            else:
                incomplete_rows += 1
    wb.close()
    return {'total_rows': total_rows, 'complete_rows': complete_rows, 'incomplete_rows': incomplete_rows}

