def get_xlsx_row_count__e9b04dcd(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get paper entries with title, arxiv link, and publication date validation."""
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'A')
    try:
        wb = openpyxl.load_workbook(file_path, data_only=True)
        if sheet_idx >= len(wb.sheetnames):
            return {'valid_rows': 0, 'rows_detail': []}
        ws = wb[wb.sheetnames[sheet_idx]]
        valid_rows = 0
        rows_detail = []
        arxiv_pattern = re.compile('arxiv\\.org', re.IGNORECASE)
        for row_idx in range(2, ws.max_row + 1):
            title = ws[f'A{row_idx}'].value
            arxiv_link = ws[f'B{row_idx}'].value
            pub_date = ws[f'C{row_idx}'].value
            title_valid = title is not None and str(title).strip()
            arxiv_valid = arxiv_link is not None and str(arxiv_link).strip() and arxiv_pattern.search(str(arxiv_link))
            date_valid = pub_date is not None and str(pub_date).strip()
            row_complete = title_valid and arxiv_valid and date_valid
            if row_complete:
                valid_rows += 1
                rows_detail.append({'row': row_idx, 'title': str(title).strip(), 'arxiv_link': str(arxiv_link).strip(), 'pub_date': str(pub_date).strip(), 'valid': True})
            elif title_valid or arxiv_valid or date_valid:
                rows_detail.append({'row': row_idx, 'title': str(title).strip() if title_valid else None, 'arxiv_link': str(arxiv_link).strip() if arxiv_valid else None, 'pub_date': str(pub_date).strip() if date_valid else None, 'valid': False})
        return {'valid_rows': valid_rows, 'rows_detail': rows_detail}
    except Exception:
        return {'valid_rows': 0, 'rows_detail': []}

def get_xlsx_age_calculations__4b06683a5c419c313a50c9a8d01bea43(env, config):
    """Extract age values from cells D2:D29 and sum from D30.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path (e.g., "/home/user/file.xlsx")
            - sheet: Sheet index (0-based) or sheet name

    Returns:
        dict: Dictionary with keys:
            - ages: List of age values from D2:D29
            - sum: Value from D30
            - all_numeric: Boolean indicating if all ages are numeric
    """
    file_path = config.get('path')
    if not file_path:
        return {'ages': [], 'sum': None, 'all_numeric': False}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'ages': [], 'sum': None, 'all_numeric': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_ref = config.get('sheet', 0)
        if isinstance(sheet_ref, int):
            ws = wb.worksheets[sheet_ref]
        else:
            ws = wb[sheet_ref]
        ages = []
        all_numeric = True
        for row in range(2, 30):
            cell_value = ws[f'D{row}'].value
            ages.append(cell_value)
            if not isinstance(cell_value, (int, float)) or cell_value is None:
                all_numeric = False
        sum_value = ws['D30'].value
        return {'ages': ages, 'sum': sum_value, 'all_numeric': all_numeric}
    finally:
        os.unlink(tmp_path)

