def get_xlsx_passfail__7d207d6f(vm_file, expected):
    """Get Pass/Fail values from column D and verify logic against marks in column C

    This getter reads the vm_file (xlsx file bytes), extracts Pass/Fail values,
    and verifies that ALL rows in column D follow the correct logic based on
    marks in column C (Pass if mark>=50, Fail if mark<50, blank if mark='--'/None).

    Args:
        vm_file: Bytes of the Excel file downloaded from VM
        expected: Dict with 'sample_cells' and 'sheet' index

    Returns:
        dict: {
            'sample_cells': dict mapping cell refs to values (e.g., 'D2': 'Fail'),
            'all_rows_valid': bool indicating if ALL rows follow the Pass/Fail logic,
            'errors': list of error messages for invalid rows
        }
    """
    import openpyxl
    import io
    if not vm_file:
        return None
    wb = openpyxl.load_workbook(io.BytesIO(vm_file), data_only=True)
    sheet_idx = expected.get('sheet', 0)
    ws = wb.worksheets[sheet_idx]
    result = {'sample_cells': {}, 'all_rows_valid': True, 'errors': []}
    sample_cells = expected.get('sample_cells', {})
    for (cell, _) in sample_cells.items():
        result['sample_cells'][cell] = ws[cell].value
    for row in range(2, ws.max_row + 1):
        mark_cell = f'C{row}'
        passfail_cell = f'D{row}'
        mark_value = ws[mark_cell].value
        passfail_value = ws[passfail_cell].value
        if mark_value == '--' or mark_value is None or mark_value == '':
            expected_passfail = None
        else:
            try:
                mark_num = float(mark_value)
                expected_passfail = 'Pass' if mark_num >= 50 else 'Fail'
            except (ValueError, TypeError):
                continue
        if expected_passfail is None:
            if passfail_value is not None and passfail_value != '':
                result['all_rows_valid'] = False
                result['errors'].append(f"Row {row}: Expected blank for mark '{mark_value}', got '{passfail_value}'")
        elif passfail_value != expected_passfail:
            result['all_rows_valid'] = False
            result['errors'].append(f"Row {row}: Expected '{expected_passfail}' for mark {mark_value}, got '{passfail_value}'")
    wb.close()
    return result

