def get_xlsx_total_supported__27928c2e28c82f12ca7bf5a9fc6f4fac(env, config: Dict[str, Any]) -> Dict[str, int]:
    """Extract total supported grant numbers for each university from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dictionary mapping university names to total supported grant counts
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        headers = []
        for col_idx in range(2, ws.max_column + 1):
            cell_value = ws.cell(1, col_idx).value
            if cell_value:
                headers.append(str(cell_value))
        for (uni_idx, uni_name) in enumerate(headers):
            col_idx = uni_idx + 2
            total = 0
            for row_idx in range(2, ws.max_row + 1):
                cell_value = ws.cell(row_idx, col_idx).value
                if cell_value is not None and isinstance(cell_value, (int, float)):
                    total += int(cell_value)
            result[uni_name] = total
        return result
    finally:
        os.unlink(tmp_path)

