def get_calc_average_values__700003716f1e7ad11cf256f44b13f71f(env, config: dict) -> Optional[Dict[str, float]]:
    """Extract average values from a specific sheet in LibreOffice Calc.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'sheet_name'

    Returns:
        Dict with average values for each column, or None if error
    """
    file_path = config.get('path')
    sheet_name = config.get('sheet_name', 'Sheet2')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return None
        ws = wb[sheet_name]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            category = row[0]
            avg_value = row[1]
            if category is not None and avg_value is not None:
                result[str(category)] = float(avg_value)
        return result
    finally:
        os.unlink(tmp_path)

def get_calc_highlighted_values__2eb2ccdf8e0d8fb7f34f72dd50211eed(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract cells that have highlighting in a specific column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM file path
            - sheet: Sheet name or index
            - column: Column letter to check
            - target_value: Value to look for (optional)

    Returns:
        Dict with highlighted_values (list of values that are highlighted)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'highlighted_values': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet = config.get('sheet', 0)
        if isinstance(sheet, int):
            ws = wb.worksheets[sheet]
        else:
            ws = wb[sheet]
        column = config.get('column', 'A')
        target_value = config.get('target_value')
        highlighted_values = []
        for i in range(2, ws.max_row + 1):
            cell = ws[f'{column}{i}']
            cell_value = cell.value
            if cell_value is None:
                break
            has_highlight = False
            if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
                rgb = cell.fill.start_color.rgb
                if rgb and rgb not in ['00000000', 'FFFFFFFF']:
                    try:
                        r = int(rgb[2:4], 16) if len(rgb) >= 4 else 0
                        g = int(rgb[4:6], 16) if len(rgb) >= 6 else 0
                        b = int(rgb[6:8], 16) if len(rgb) >= 8 else 0
                        if g > max(r, b) + 30:
                            has_highlight = True
                    except (ValueError, IndexError):
                        has_highlight = False
            if target_value is None or cell_value == target_value:
                if has_highlight:
                    highlighted_values.append(cell_value)
        return {'highlighted_values': highlighted_values, 'highlighted_count': len(highlighted_values)}
    finally:
        os.unlink(tmp_path)

def get_docx_table_cell__6bb18264(env, config: dict):
    """Extract a specific cell value from a table in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM path to the docx file
            - dest: Local destination filename
            - table_index: Which table to extract from (0-based)
            - row: Row index (0-based)
            - col: Column index (0-based)

    Returns:
        Cell text content (stripped)
    """
    try:
        vm_path = config.get('path', '/home/user/Documents/awesome-desktop/awe_desk_env.docx')
        file_bytes = env.controller.get_file(vm_path)
        if not file_bytes:
            logger.error(f'Failed to get file from VM: {vm_path}')
            return None
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        try:
            doc = Document(tmp_path)
            table_index = config.get('table_index', 0)
            if table_index >= len(doc.tables):
                logger.error(f'Table index {table_index} out of range (only {len(doc.tables)} tables)')
                return None
            table = doc.tables[table_index]
            row = config.get('row', 0)
            col = config.get('col', 0)
            if row >= len(table.rows):
                logger.error(f'Row index {row} out of range (only {len(table.rows)} rows)')
                return None
            if col >= len(table.columns):
                logger.error(f'Column index {col} out of range (only {len(table.columns)} columns)')
                return None
            cell_text = table.cell(row, col).text.strip()
            logger.info(f'Extracted cell ({row}, {col}): {cell_text}')
            return cell_text
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error extracting docx table cell: {e}')
        return None

