def get_xlsx_quarterly_totals__45193d9a892bd0a72a54bf4a5255722d(env, config):
    """Extract quarterly sales totals for each sales rep from a new worksheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        dict: Dictionary mapping rep names to their Q1 and Q2 totals
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {}
        for sheet_name in wb.sheetnames:
            if sheet_name == 'Sheet1':
                continue
            ws = wb[sheet_name]
            for row_idx in range(2, ws.max_row + 1):
                rep_name = ws.cell(row_idx, 1).value
                q1_total = ws.cell(row_idx, 2).value
                q2_total = ws.cell(row_idx, 3).value
                if rep_name is not None:
                    result[str(rep_name)] = {'q1': float(q1_total) if q1_total is not None else 0.0, 'q2': float(q2_total) if q2_total is not None else 0.0}
            break
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

