def get_xlsx_cell_colors__963dc31f(env, config: dict) -> Dict[str, Any]:
    """Extract background colors for all cells in the specified sheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict mapping cell coordinates to their RGB background colors (as hex strings)
    """
    vm_path = config.get('path', '/home/user/Calendar_Highlight_Weekend_Days.xlsx')
    dest = config.get('dest', 'Calendar_Highlight_Weekend_Days.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    import os
    cache_dir = env.cache_dir
    local_path = os.path.join(cache_dir, dest)
    os.makedirs(os.path.dirname(local_path), exist_ok=True)
    with open(local_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(local_path)
    ws = wb.active
    cell_colors = {}
    for row in ws.iter_rows():
        for cell in row:
            if cell.fill and cell.fill.start_color:
                color = cell.fill.start_color.rgb
                if color and color != '00000000':
                    if len(color) == 8:
                        hex_color = f'#{color[2:].upper()}'
                    else:
                        hex_color = f'#{color.upper()}'
                    cell_colors[cell.coordinate] = hex_color
    wb.close()
    return cell_colors

def get_thunderbird_xlsx_data__5b362329(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract data from xlsx file created from Thunderbird emails.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for xlsx file path

    Returns:
        Dict with 'headers' (list of column names) and 'data' (list of data rows)
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    vm_path = config.get('path')
    dest_name = config.get('dest', 'result.xlsx')
    local_path = get_vm_file(env, {'path': vm_path, 'dest': dest_name})
    if local_path is None:
        return {'headers': [], 'data': []}
    try:
        wb = openpyxl.load_workbook(local_path, data_only=True)
        ws = wb.active
        headers = []
        header_row = next(ws.iter_rows(min_row=1, max_row=1, values_only=True), None)
        if header_row:
            headers = [str(cell).strip().lower() if cell is not None else '' for cell in header_row]
        data = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row and any((cell is not None for cell in row)):
                data.append([str(cell) if cell is not None else '' for cell in row])
        return {'headers': headers, 'data': data}
    except Exception as e:
        return {'headers': [], 'data': []}

def get_xlsx_row_fill__fcf9cfd6(env, config: Dict[str, Any]) -> List[str]:
    """Get the fill colors of cells in a specific row.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'row' keys

    Returns:
        List of color strings (hex format like 'FFFFFF00') for each cell
    """
    file_path = config.get('path', '')
    row_num = config.get('row', 2)
    wb = openpyxl.load_workbook(file_path, data_only=False)
    ws = wb.active
    colors = []
    for col in range(1, 7):
        cell = ws.cell(row=row_num, column=col)
        if cell.fill and cell.fill.start_color:
            if hasattr(cell.fill.start_color, 'rgb'):
                color = cell.fill.start_color.rgb
                color_str = str(color) if color else None
                colors.append(color_str)
            else:
                colors.append(None)
        else:
            colors.append(None)
    wb.close()
    return colors

def get_xlsx_cell_value__ef67a2613bcb49b5aca0e4ed2ed3d990(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract cell value and formula from Excel file.

    Reads the Excel file and extracts both the computed value and the formula
    from a specified cell to verify calculation was done (not just hardcoded).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'cell' keys

    Returns:
        dict: Contains 'value' (float) and 'formula' (str or None)
    """
    file_path = config.get('path', '')
    cell_address = config.get('cell', 'A1')
    if not file_path:
        return {'value': 0.0, 'formula': None}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'value': 0.0, 'formula': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        ws = wb.active
        cell = ws[cell_address]
        formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        ws_data = wb_data.active
        cell_value = ws_data[cell_address].value
        if cell_value is None:
            cell_value = 0.0
        else:
            try:
                cell_value = float(cell_value)
            except (ValueError, TypeError):
                cell_value = 0.0
        return {'value': cell_value, 'formula': formula}
    except Exception:
        return {'value': 0.0, 'formula': None}
    finally:
        os.unlink(tmp_path)

def get_xlsx_top_products__210d538c8dcbbc6a4de158c1c3ab9bc2(env, config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Extract top products ranking from Sheet2.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of dicts with 'product' and 'revenue' keys, ordered by rank
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if 'Sheet2' not in wb.sheetnames:
            return []
        ws = wb['Sheet2']
        result = []
        if ws.max_row < 2:
            return []
        for row_idx in range(2, min(ws.max_row + 1, 7)):
            product = ws.cell(row_idx, 1).value
            revenue = ws.cell(row_idx, 2).value
            if product and revenue is not None:
                try:
                    result.append({'product': str(product), 'revenue': float(revenue)})
                except (ValueError, TypeError):
                    pass
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

