def get_xlsx_avg_score__a4bf9438542cfb31ac26e6c95d019d22(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract and verify average score written in prominent location in spreadsheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to Excel file

    Returns:
        Dict with keys:
            - 'average_written': float value found in prominent location (A13-B14 area)
            - 'has_label': bool indicating if label like 'Average Score:' was found
            - 'label_found': str with the label text found (if any)
            - 'calculated_average': float calculated from column M data for reference
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'average_written': None, 'has_label': False, 'label_found': '', 'calculated_average': 0.0}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'average_written': None, 'has_label': False, 'label_found': '', 'calculated_average': 0.0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        total_scores = []
        for row in range(2, 12):
            cell_value = ws.cell(row=row, column=13).value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                total_scores.append(float(cell_value))
        calculated_average = 0.0
        if total_scores:
            calculated_average = sum(total_scores) / len(total_scores)
        average_written = None
        has_label = False
        label_found = ''
        label_patterns = ['average score', 'average', 'avg score', 'avg']
        for row in range(13, 15):
            for col in range(1, 3):
                cell_value = ws.cell(row=row, column=col).value
                if cell_value is not None:
                    cell_str = str(cell_value).lower().strip()
                    if any((pattern in cell_str for pattern in label_patterns)):
                        has_label = True
                        label_found = str(cell_value)
                    elif isinstance(cell_value, (int, float)):
                        average_written = float(cell_value)
        if has_label and average_written is None:
            for row in range(13, 15):
                for col in range(1, 3):
                    cell_value = ws.cell(row=row, column=col).value
                    if isinstance(cell_value, (int, float)):
                        average_written = float(cell_value)
                        break
                if average_written is not None:
                    break
        return {'average_written': average_written, 'has_label': has_label, 'label_found': label_found, 'calculated_average': round(calculated_average, 2)}
    finally:
        os.unlink(tmp_path)

