def get_xlsx_completeness__9b7afbb9(env, config: dict):
    """Check if all required columns are filled and validate semantic content.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'required_columns' keys

    Returns:
        dict: Contains 'total_rows', 'complete_rows', 'rows_with_arxiv',
              'rows_with_correct_date', 'rows_with_topic', 'rows_with_all_valid'
    """
    vm_path = config.get('path', '')
    required_columns = config.get('required_columns', [1, 2, 3])
    file_content = env.controller.get_file(vm_path)
    if not file_content:
        return {'total_rows': 0, 'complete_rows': 0, 'rows_with_arxiv': 0, 'rows_with_correct_date': 0, 'rows_with_topic': 0, 'rows_with_all_valid': 0, 'incomplete_count': 0}
    wb = openpyxl.load_workbook(io.BytesIO(file_content), data_only=True)
    ws = wb.active
    total_rows = 0
    complete_rows = 0
    rows_with_arxiv = 0
    rows_with_correct_date = 0
    rows_with_topic = 0
    rows_with_all_valid = 0
    lm_keywords = ['language model', 'llm', 'transformer', 'gpt', 'bert', 'attention', 'neural language', 'pre-trained model', 'pretrained model', 'nlp model', 't5', 'bart', 'roberta', 'electra', 'xlnet', 'natural language', 'text generation', 'language generation', 'seq2seq', 'encoder-decoder']
    for row_idx in range(2, ws.max_row + 1):
        has_content = False
        for col in required_columns:
            if ws.cell(row_idx, col).value:
                has_content = True
                break
        if has_content:
            total_rows += 1
            title = ws.cell(row_idx, 1).value
            link = ws.cell(row_idx, 2).value
            date = ws.cell(row_idx, 3).value
            all_filled = True
            for col in required_columns:
                value = ws.cell(row_idx, col).value
                if not value or not str(value).strip():
                    all_filled = False
                    break
            if all_filled:
                complete_rows += 1
            has_arxiv = False
            if link and 'arxiv.org' in str(link).lower():
                has_arxiv = True
                rows_with_arxiv += 1
            has_correct_date = False
            if date:
                date_str = str(date).strip()
                if 'october 11, 2023' in date_str.lower() or 'oct 11, 2023' in date_str.lower() or '10/11/2023' in date_str or ('2023-10-11' in date_str) or ('11/10/2023' in date_str) or ('11 october 2023' in date_str.lower()) or ('11 oct 2023' in date_str.lower()):
                    has_correct_date = True
                    rows_with_correct_date += 1
                elif isinstance(date, datetime):
                    if date.year == 2023 and date.month == 10 and (date.day == 11):
                        has_correct_date = True
                        rows_with_correct_date += 1
            has_topic = False
            if title:
                title_lower = str(title).lower()
                for keyword in lm_keywords:
                    if keyword in title_lower:
                        has_topic = True
                        rows_with_topic += 1
                        break
            if all_filled and has_arxiv and has_correct_date and has_topic:
                rows_with_all_valid += 1
    wb.close()
    return {'total_rows': total_rows, 'complete_rows': complete_rows, 'rows_with_arxiv': rows_with_arxiv, 'rows_with_correct_date': rows_with_correct_date, 'rows_with_topic': rows_with_topic, 'rows_with_all_valid': rows_with_all_valid, 'incomplete_count': total_rows - complete_rows}

def get_xlsx_row_highlight__c1e72102(env, config):
    """Extract row fill color information from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', and 'row' parameters

    Returns:
        Dict with fill color information for the row
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    row_num = config.get('row', 1)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(mode='wb', suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        has_fill = False
        for col in range(1, min(6, ws.max_column + 1)):
            cell = ws.cell(row_num, col)
            if cell.fill and cell.fill.fill_type and (cell.fill.fill_type != 'none'):
                has_fill = True
                break
        result = {'has_fill': has_fill}
        wb.close()
        os.unlink(tmp_path)
        return result
    except Exception as e:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)
        return {'has_fill': False, 'error': str(e)}

