def get_xlsx_column_text_values__814719db(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract text values from a specific column in Excel file.
    Also verifies that IF formulas are used for calculations (as required by instruction).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet' (0-indexed), 'column', 'start_row', 'end_row'

    Returns:
        Dict with 'values' (list of text values) and 'formula_count' (number of IF formulas found)
    """
    from desktop_env.evaluators.getters import file as file_getters
    local_path = file_getters.get_vm_file(env, config)
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'D')
    if isinstance(column, str):
        col_idx = openpyxl.utils.column_index_from_string(column)
    else:
        col_idx = column
    start_row = config.get('start_row', 2)
    end_row_config = config.get('end_row', None)
    wb_formulas = openpyxl.load_workbook(local_path, data_only=False)
    ws_formulas = wb_formulas.worksheets[sheet_idx]
    end_row = end_row_config if end_row_config else ws_formulas.max_row
    formula_count = 0
    for row in range(start_row, end_row + 1):
        cell = ws_formulas.cell(row, col_idx)
        if cell.value and isinstance(cell.value, str) and cell.value.startswith('=IF('):
            formula_count += 1
    wb_formulas.close()
    wb = openpyxl.load_workbook(local_path, data_only=True)
    ws = wb.worksheets[sheet_idx]
    values = []
    for row in range(start_row, end_row + 1):
        val = ws.cell(row, col_idx).value
        values.append(str(val) if val is not None else '')
    wb.close()
    return {'values': values, 'formula_count': formula_count}

