def get_xlsx_column_sorted__b22cf776(env, config: dict):
    """Check if a column is sorted in specified order.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column', 'start_row', 'end_row', 'order'

    Returns:
        dict with 'is_sorted' (bool) and 'values' (list)
    """
    vm_path = config['path']
    sheet_idx = config.get('sheet', 0)
    column = config['column']
    start_row = config.get('start_row', 1)
    end_row = config.get('end_row', 100)
    order = config.get('order', 'desc')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {'is_sorted': False, 'values': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        values = []
        for row_idx in range(start_row, min(end_row + 1, ws.max_row + 1)):
            cell_value = ws[f'{column}{row_idx}'].value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                values.append(cell_value)
        is_sorted = False
        if len(values) > 0:
            if order == 'desc':
                is_sorted = all((values[i] >= values[i + 1] for i in range(len(values) - 1)))
            else:
                is_sorted = all((values[i] <= values[i + 1] for i in range(len(values) - 1)))
        wb.close()
        return {'is_sorted': is_sorted, 'values': values}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_calc_year_list__9b43d7af1a21133f7a4f4ca836c72917(env, config: dict) -> Optional[List[int]]:
    """Extract a list of years from a specific sheet in LibreOffice Calc.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'sheet_name', and 'year_column'

    Returns:
        List of years found in the specified column, or None if error
    """
    file_path = config.get('path')
    sheet_name = config.get('sheet_name', 'Sheet2')
    year_column = config.get('year_column', 'A')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return None
        ws = wb[sheet_name]
        years = []
        for row_idx in range(2, ws.max_row + 1):
            cell = ws[f'{year_column}{row_idx}']
            if cell.value is not None:
                try:
                    years.append(int(cell.value))
                except (ValueError, TypeError):
                    continue
            else:
                break
        return years
    finally:
        os.unlink(tmp_path)

