def get_pptx_table_cells__66b565ba(env, config):
    """Extract specific cell values from a PowerPoint table.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM file path to the PPTX file
            - dest: Destination filename in cache
            - slide_index: Index of the slide (0-based)
            - shape_index: Index of the table shape (0-based, default 1)
            - cells: List of dicts with 'row' and 'col' keys
            
    Returns:
        Dict mapping (row, col) tuples to cell text values
    """
    import os
    vm_path = config.get('path', '/home/user/Desktop/33_1.pptx')
    dest_filename = config.get('dest', '33_1.pptx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    cache_path = os.path.join(env.cache_dir, dest_filename)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    prs = Presentation(cache_path)
    slide_index = config.get('slide_index', 3)
    shape_index = config.get('shape_index', 1)
    cells_to_check = config.get('cells', [])
    if slide_index >= len(prs.slides):
        return {}
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return {}
    shape = slide.shapes[shape_index]
    if not shape.has_table:
        return {}
    table = shape.table
    result = {}
    for cell_spec in cells_to_check:
        row = cell_spec['row']
        col = cell_spec['col']
        if row < len(table.rows) and col < len(table.columns):
            cell = table.rows[row].cells[col]
            result[f'{row},{col}'] = cell.text.strip()
    return result

