def get_xlsx_highlighted_rep__8f87cddf17f5a4c6ccc5a2b77462f6b1(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract which sales rep row is highlighted.

    This getter checks which row has all cells highlighted/filled (entire row).
    It verifies that ALL populated cells in the row have highlighting, not just column A.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file on VM
            - sheet: Sheet index (default 0)

    Returns:
        Dict containing the highlighted rep name, row number, and full_row_highlighted flag
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'highlighted_rep': None, 'row': None, 'full_row_highlighted': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        for row_num in range(2, 12):
            row_cells = [ws[f'{col}{row_num}'] for col in ['A', 'B', 'C', 'D', 'E', 'F']]
            highlighted_cells = 0
            total_cells = len(row_cells)
            for cell in row_cells:
                if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
                    color = cell.fill.start_color.rgb
                    if color not in ['FFFFFFFF', '00000000', 'FF000000']:
                        highlighted_cells += 1
            if highlighted_cells == total_cells:
                rep_name = ws[f'A{row_num}'].value
                return {'highlighted_rep': rep_name, 'row': row_num, 'full_row_highlighted': True, 'highlighted_cells': highlighted_cells, 'total_cells': total_cells}
        return {'highlighted_rep': None, 'row': None, 'full_row_highlighted': False}
    finally:
        os.unlink(tmp_path)

