def get_xlsx_column_completeness__981ac28850a1c753591ff315e5b18a78(env, config):
    """Check if a specific column has all non-empty values for data rows, and verify arxiv links.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column', 'start_row'

    Returns:
        dict: {'complete': bool, 'filled_count': int, 'total_count': int, 'cell_values': list}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'complete': False, 'filled_count': 0, 'total_count': 0, 'cell_values': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        column = config['column']
        start_row = config.get('start_row', 2)
        end_row = ws.max_row
        filled_count = 0
        total_count = 0
        cell_values = []
        for row_idx in range(start_row, end_row + 1):
            cell = ws[f'{column}{row_idx}']
            title_cell = ws[f'A{row_idx}']
            if title_cell.value:
                total_count += 1
                cell_val = cell.value
                if cell_val and str(cell_val).strip():
                    filled_count += 1
                    cell_values.append(str(cell_val).strip())
                else:
                    cell_values.append(None)
        return {'complete': filled_count == total_count and total_count > 0, 'filled_count': filled_count, 'total_count': total_count, 'cell_values': cell_values}
    finally:
        os.unlink(tmp_path)

