def get_xlsx_last_row__a424c60e(env, config):
    """
    Get the last row of data from the spreadsheet to verify proper splitting.
    Extracts data from the last row (row 22) to verify that:
    - Column A still contains the original combined data
    - Column B contains the first name
    - Column C contains the last name
    - Column D contains the rank

    Args:
        env: Environment object
        config: Configuration dict with 'path', 'sheet', and 'expected_row' keys

    Returns:
        dict: Dictionary with original, first_name, last_name, and rank from the last row
    """
    path = config['path']
    sheet_idx = config.get('sheet', 0)
    expected_row = config.get('expected_row', 22)
    wb = openpyxl.load_workbook(path)
    if isinstance(sheet_idx, int):
        sheet = wb.worksheets[sheet_idx]
    else:
        sheet = wb[sheet_idx]
    row_data = sheet[expected_row]
    col_a = row_data[0].value if row_data[0].value else ''
    col_b = row_data[1].value if row_data[1].value else ''
    col_c = row_data[2].value if row_data[2].value else ''
    col_d = row_data[3].value if row_data[3].value else ''
    wb.close()
    return {'original': str(col_a).strip() if col_a else '', 'first_name': str(col_b).strip() if col_b else '', 'last_name': str(col_c).strip() if col_c else '', 'rank': str(col_d).strip() if col_d else ''}

