def get_xlsx_age_and_highlighting__7528d7b4(env, config: Dict[str, Any]):
    """
    Get both age calculations and highlighting information from the spreadsheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'age_column', 'start_row', 'end_row' keys

    Returns:
        Dict with 'ages' (dict mapping row to age) and 'highlighted_rows' (list of row numbers)
    """
    file_path = config.get('path', '/home/user/Employee_Age_By_Birthday.xlsx')
    sheet_idx = config.get('sheet', 0)
    age_column = config.get('age_column', 4)
    start_row = config.get('start_row', 2)
    end_row = config.get('end_row', 29)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'ages': {}, 'highlighted_rows': []}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        ages = {}
        for row_idx in range(start_row, end_row + 1):
            cell = ws.cell(row_idx, age_column)
            if cell.value is not None:
                try:
                    ages[row_idx] = int(cell.value)
                except (ValueError, TypeError):
                    ages[row_idx] = None
            else:
                ages[row_idx] = None
        highlighted_rows = []
        for row_idx in range(start_row, end_row + 1):
            has_fill = False
            for col in range(2, 5):
                cell = ws.cell(row_idx, col)
                if cell.fill and cell.fill.start_color and (cell.fill.start_color.index != '00000000'):
                    if cell.fill.start_color.index not in ['00000000', 'FFFFFFFF', None]:
                        has_fill = True
                        break
            if has_fill:
                highlighted_rows.append(row_idx)
        wb.close()
        return {'ages': ages, 'highlighted_rows': highlighted_rows}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

