def get_table_cell_text__d82e55f3a036eb870f1ed81fc948abf3(env, config: Dict):
    """Extract text from a specific table cell in a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'slide_index', 'row', 'col'

    Returns:
        str: The cell text, or empty string if not found
    """
    ppt_path = config['path']
    slide_index = config.get('slide_index', 0)
    row = config.get('row', 0)
    col = config.get('col', 0)
    file_bytes = env.controller.get_file(ppt_path)
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return ''
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if shape.shape_type == MSO_SHAPE_TYPE.TABLE:
                table = shape.table
                if row < len(table.rows) and col < len(table.columns):
                    cell = table.cell(row, col)
                    return cell.text.strip()
        return ''
    finally:
        os.unlink(tmp_path)

def get_tb_summary_xlsx__f5f661c56b53d0549f4c6bd9201ba899(env, config):
    """Extract email count summary from Excel report and validate structure.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with:
            - 'summary': Dict mapping sender emails to counts
            - 'headers_valid': bool (True if headers are correct)
            - 'sorted_valid': bool (True if sorted by count descending)
            - 'location_valid': bool (True if file is on Desktop)
            - 'filename_valid': bool (True if filename is 'email_summary.xlsx')
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'summary': {}, 'headers_valid': False, 'sorted_valid': False, 'location_valid': False, 'filename_valid': False}
    location_valid = '/Desktop/' in file_path or file_path.endswith('/Desktop/email_summary.xlsx')
    filename_valid = file_path.endswith('email_summary.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'summary': {}, 'headers_valid': False, 'sorted_valid': False, 'location_valid': location_valid, 'filename_valid': filename_valid}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        header1 = ws.cell(1, 1).value
        header2 = ws.cell(1, 2).value
        headers_valid = header1 == 'sender_email' and header2 == 'email_count'
        summary = {}
        counts_list = []
        for row_idx in range(2, ws.max_row + 1):
            sender_email = ws.cell(row_idx, 1).value
            count = ws.cell(row_idx, 2).value
            if sender_email and count is not None:
                summary[sender_email] = count
                counts_list.append(count)
        sorted_valid = True
        for i in range(len(counts_list) - 1):
            if counts_list[i] < counts_list[i + 1]:
                sorted_valid = False
                break
        return {'summary': summary, 'headers_valid': headers_valid, 'sorted_valid': sorted_valid, 'location_valid': location_valid, 'filename_valid': filename_valid}
    finally:
        os.unlink(tmp_path)

