def get_xlsx_sales_data__50d3be1d1adc4a85b3ae89c38a5771e7(env, config):
    """Extract sales data from Excel file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to Excel file on VM
        
    Returns:
        dict: Dictionary containing cell values and chart information
    """
    file_path = config.get('path', '/home/user/SalesRep.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file from VM'}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        for row in range(1, 20):
            for col in range(1, 10):
                cell = ws.cell(row=row, column=col)
                cell_address = cell.coordinate
                cell_value = cell.value
                result[cell_address] = cell_value
                if cell.fill and cell.fill.fgColor:
                    color = cell.fill.fgColor
                    if hasattr(color, 'rgb') and color.rgb:
                        result[f'{cell_address}_fill'] = color.rgb
        charts = []
        if hasattr(ws, '_charts'):
            for chart in ws._charts:
                chart_info = {}
                chart_type = type(chart).__name__
                chart_info['type'] = chart_type
                if hasattr(chart, 'title') and chart.title:
                    chart_info['title'] = str(chart.title.text.rich.p[0].text) if hasattr(chart.title.text, 'rich') else str(chart.title)
                else:
                    chart_info['title'] = None
                charts.append(chart_info)
        result['_charts'] = charts
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_xlsx_max_value_and_highlight__31a42b34e67265c484ea5c28c2dfa379(env, config: dict):
    """Extract max value info and highlighting from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'start_cell', 'end_cell', 'target_cell' keys

    Returns:
        dict: {
            'max_value': float,
            'max_cell': str,
            'target_cell': str,
            'has_fill': bool,
            'fill_color': str or None
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'max_value': None, 'max_cell': None, 'target_cell': None, 'has_fill': False, 'fill_color': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[config['sheet']]
        start_cell = config['start_cell']
        end_cell = config['end_cell']
        target_cell = config['target_cell']
        cell_range = ws[f'{start_cell}:{end_cell}']
        values = []
        cells = []
        for cell_tuple in cell_range:
            for cell in cell_tuple:
                cell_value = cell.value
                if cell_value is not None:
                    try:
                        numeric_value = float(cell_value)
                        values.append(numeric_value)
                        cells.append(cell.coordinate)
                    except (ValueError, TypeError):
                        pass
        max_value = None
        max_cell = None
        if values:
            max_value = max(values)
            max_index = values.index(max_value)
            max_cell = cells[max_index]
        wb_fmt = openpyxl.load_workbook(tmp_path)
        ws_fmt = wb_fmt.worksheets[config['sheet']]
        cell_obj = ws_fmt[target_cell]
        fill = cell_obj.fill
        has_fill = fill and fill.start_color and fill.start_color.rgb and (fill.start_color.rgb not in ['00000000', None])
        fill_color = fill.start_color.rgb if has_fill else None
        return {'max_value': max_value, 'max_cell': max_cell, 'target_cell': target_cell, 'has_fill': has_fill, 'fill_color': fill_color}
    finally:
        os.unlink(tmp_path)

