def get_xlsx_cell_value__d7318ea6(env, config):
    """Get cell value and formula from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with path, sheet, cell

    Returns:
        dict: {'value': evaluated value, 'formula': formula string or None, 'has_formula': bool}
    """
    import openpyxl
    path = config.get('path', '')
    sheet_name = config.get('sheet', '')
    cell_addr = config.get('cell', 'A1')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return {'value': None, 'formula': None, 'has_formula': False}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    wb = openpyxl.load_workbook(tmp_path, data_only=False)
    ws = wb[sheet_name]
    cell = ws[cell_addr]
    has_formula = cell.data_type == 'f'
    formula = cell.value if has_formula else None
    wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
    ws_data = wb_data[sheet_name]
    value = ws_data[cell_addr].value
    os.unlink(tmp_path)
    return {'value': value, 'formula': formula, 'has_formula': has_formula}

