def get_xlsx_cell_fill__9ffa7205(env, config: dict):
    """Extract cell fill color from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell'

    Returns:
        dict with 'has_fill' (bool) and 'fill_color' (hex string or None)
    """
    vm_path = config['path']
    sheet_idx = config.get('sheet', 0)
    cell_addr = config['cell']
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {'has_fill': False, 'fill_color': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell = ws[cell_addr]
        fill = cell.fill
        has_fill = False
        fill_color = None
        if fill and fill.start_color:
            color_value = fill.start_color.rgb
            if color_value and color_value != '00000000' and (color_value != 'FFFFFFFF'):
                has_fill = True
                if isinstance(color_value, str):
                    if len(color_value) == 8:
                        fill_color = '#' + color_value[2:]
                    else:
                        fill_color = '#' + color_value
                fill_color = fill_color.upper() if fill_color else None
        wb.close()
        return {'has_fill': has_fill, 'fill_color': fill_color}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_xlsx_two_column_data__b5d87bdfd411dfe5d7b4143bc07d6cf5(env, config: Dict[str, Any]) -> List[tuple]:
    """Get data from two adjacent columns in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (0-indexed), 'column1' (e.g., 'D'),
                'column2' (e.g., 'E'), 'start_row' (1-indexed), 'end_row' (1-indexed)

    Returns:
        List of tuples (value1, value2) from the two columns
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    column1 = config.get('column1', 'A')
    column2 = config.get('column2', 'B')
