def get_xlsx_url_domains__96a8e6ef3f2d619a8a83a9a683998043(env, config):
    """Extract domain names, dates, paper titles, and metadata from URLs in the arXiv link column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'url_column' keys

    Returns:
        dict: Dictionary with:
            - 'domains': list of domain names
            - 'dates': list of publication dates (YYYY-MM format)
            - 'row_count': number of rows with URLs
            - 'arxiv_ids': list of arXiv paper IDs
            - 'titles': list of paper titles from column A
    """
    file_path = config.get('path', '')
    url_column = config.get('url_column', 2)
    if not file_path:
        return {'domains': [], 'dates': [], 'row_count': 0, 'arxiv_ids': [], 'titles': []}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'domains': [], 'dates': [], 'row_count': 0, 'arxiv_ids': [], 'titles': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        domains = []
        dates = []
        arxiv_ids = []
        titles = []
        row_count = 0
        for row_idx in range(2, ws.max_row + 1):
            url_cell = ws.cell(row=row_idx, column=url_column)
            if url_cell.value:
                url = str(url_cell.value).strip()
                if url:
                    row_count += 1
                    domain = extract_domain(url)
                    if domain:
                        domains.append(domain)
                    (arxiv_id, date) = extract_arxiv_date(url)
                    if arxiv_id:
                        arxiv_ids.append(arxiv_id)
                    if date:
                        dates.append(date)
                    title_cell = ws.cell(row=row_idx, column=1)
                    if title_cell.value:
                        titles.append(str(title_cell.value).strip())
                    else:
                        titles.append('')
        return {'domains': domains, 'dates': dates, 'row_count': row_count, 'arxiv_ids': arxiv_ids, 'titles': titles}
    finally:
        os.unlink(tmp_path)

