def get_tb_weekly_xlsx__264d715cc53b32b5aee947baaf88b841(env, config):
    """Extract weekly emails data from Excel report.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with:
        - 'emails': List of dicts with email data (sender_name, sender_email, subject, date)
        - 'headers': List of column headers found
        - 'valid_headers': Boolean indicating if headers match expected format
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'emails': [], 'headers': [], 'valid_headers': False}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'emails': [], 'headers': [], 'valid_headers': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        headers = []
        for col_idx in range(1, 5):
            header_value = ws.cell(1, col_idx).value
            if header_value:
                headers.append(str(header_value).strip().lower())
        expected_headers = ['sender_name', 'sender_email', 'subject', 'date']
        expected_headers_alt = ['sender name', 'sender email', 'subject', 'date']
        valid_headers = headers == expected_headers or headers == expected_headers_alt
        emails = []
        for row_idx in range(2, ws.max_row + 1):
            sender_name = ws.cell(row_idx, 1).value
            sender_email = ws.cell(row_idx, 2).value
            subject = ws.cell(row_idx, 3).value
            date_value = ws.cell(row_idx, 4).value
            if not (sender_name or sender_email or subject or date_value):
                continue
            date_str = None
            if date_value:
                if isinstance(date_value, datetime):
                    date_str = date_value.strftime('%Y-%m-%d')
                else:
                    date_str_raw = str(date_value).strip()
                    for fmt in ['%Y-%m-%d', '%m/%d/%Y', '%d/%m/%Y', '%Y/%m/%d']:
                        try:
                            parsed_date = datetime.strptime(date_str_raw, fmt)
                            date_str = parsed_date.strftime('%Y-%m-%d')
                            break
                        except ValueError:
                            continue
            emails.append({'sender_name': sender_name, 'sender_email': sender_email, 'subject': subject, 'date': date_str})
        return {'emails': emails, 'headers': headers, 'valid_headers': valid_headers}
    finally:
        os.unlink(tmp_path)

