def get_calc_cell_format__a3c8817989e00a27454e516ffd39d47e(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get cell formatting information and data from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with:
        - 'formatting': Dict mapping cell addresses to formatting properties
        - 'data': Dict mapping cell addresses to cell values
        - 'month_column': List of (row_num, cell_address, month_name) for column A
        - 'cost_2020_column': List of (row_num, cell_address, cost_value) for 2020 total costs
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        formatting = {}
        data = {}
        for row in ws.iter_rows():
            for cell in row:
                data[cell.coordinate] = cell.value
                if cell.font:
                    formatting[cell.coordinate] = {'bold': cell.font.bold or False, 'italic': cell.font.italic or False, 'underline': cell.font.underline is not None}
        month_column = []
        for row_idx in range(2, ws.max_row + 1):
            cell_address = f'A{row_idx}'
            value = data.get(cell_address)
            if value:
                month_column.append((row_idx, cell_address, value))
        year_2020_column = None
        for cell in ws[1]:
            cell_value = cell.value
            if cell_value and '2020' in str(cell_value):
                year_2020_column = cell.column_letter
                break
        cost_2020_column = []
        if year_2020_column:
            for row_idx in range(2, ws.max_row + 1):
                cell_address = f'{year_2020_column}{row_idx}'
                value = data.get(cell_address)
                if value is not None and isinstance(value, (int, float)):
                    cost_2020_column.append((row_idx, cell_address, value))
        return {'formatting': formatting, 'data': data, 'month_column': month_column, 'cost_2020_column': cost_2020_column}
    finally:
        os.unlink(tmp_path)

