def get_xlsx_max_value_verification__97d0af2c543ca5fbe1c6c79636711dcb(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Verify that the maximum value in column A (rows 2-20) is correctly identified and highlighted.

    This getter:
    1. Finds which cell in A2:A20 contains the maximum value
    2. Checks which cells in A2:A20 have fill colors
    3. Returns info needed to verify the task was completed correctly

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'sheet' (sheet index)

    Returns:
        Dict with:
        - max_cell: The cell coordinate containing the max value (e.g., "A20")
        - max_value: The maximum value found
        - highlighted_cells: List of cells that have fill colors
        - all_values: Dict of cell -> value for debugging
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            return {'max_cell': None, 'max_value': None, 'highlighted_cells': [], 'all_values': {}}
        with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            wb = openpyxl.load_workbook(tmp_path, data_only=True)
            ws = wb.worksheets[config.get('sheet', 0)]
            all_values = {}
            max_value = None
            max_cell = None
            highlighted_cells = []
            for row_num in range(2, 21):
                cell_coord = f'A{row_num}'
                cell = ws[cell_coord]
                cell_value = cell.value
                if cell_value is not None:
                    try:
                        numeric_value = float(cell_value)
                        all_values[cell_coord] = numeric_value
                        if max_value is None or numeric_value > max_value:
                            max_value = numeric_value
                            max_cell = cell_coord
                    except (ValueError, TypeError):
                        all_values[cell_coord] = cell_value
                if cell.fill and cell.fill.start_color:
                    color = cell.fill.start_color.rgb
                    if color and color != '00000000':
                        highlighted_cells.append(cell_coord)
            return {'max_cell': max_cell, 'max_value': max_value, 'highlighted_cells': highlighted_cells, 'all_values': all_values}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        print(f'Error verifying max value: {e}')
        return {'max_cell': None, 'max_value': None, 'highlighted_cells': [], 'all_values': {}}

def get_xlsx_sales_data__68a2bc639d62cfd83c2dd75c92c0cd2c(env, config):
    """Extract sales data from Excel file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to Excel file on VM
        
    Returns:
        dict: Dictionary containing cell values and chart information
    """
    file_path = config.get('path', '/home/user/SalesRep.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file from VM'}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        for row in range(1, 20):
            for col in range(1, 10):
                cell = ws.cell(row=row, column=col)
                cell_address = cell.coordinate
                cell_value = cell.value
                result[cell_address] = cell_value
                if cell.fill and cell.fill.fgColor:
                    color = cell.fill.fgColor
                    if hasattr(color, 'rgb') and color.rgb:
                        result[f'{cell_address}_fill'] = color.rgb
        charts = []
        if hasattr(ws, '_charts'):
            for chart in ws._charts:
                chart_info = {}
                chart_type = type(chart).__name__
                chart_info['type'] = chart_type
                if hasattr(chart, 'title') and chart.title:
                    chart_info['title'] = str(chart.title.text.rich.p[0].text) if hasattr(chart.title.text, 'rich') else str(chart.title)
                else:
                    chart_info['title'] = None
                chart_info['series_count'] = 0
                chart_info['data_points'] = 0
                if hasattr(chart, 'series') and chart.series:
                    chart_info['series_count'] = len(chart.series)
                    if chart.series and len(chart.series) > 0:
                        first_series = chart.series[0]
                        if hasattr(first_series, 'val') and first_series.val:
                            if hasattr(first_series.val, 'numRef') and first_series.val.numRef:
                                num_ref = first_series.val.numRef
                                if hasattr(num_ref, 'numCache') and num_ref.numCache:
                                    if hasattr(num_ref.numCache, 'ptCount'):
                                        chart_info['data_points'] = num_ref.numCache.ptCount.val
                                    elif hasattr(num_ref.numCache, 'pt'):
                                        chart_info['data_points'] = len(num_ref.numCache.pt)
                charts.append(chart_info)
        result['_charts'] = charts
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_xlsx_avg_discount__f4542476f8182c42c9800a1c75ecbf21(env, config: dict) -> Dict[str, float]:
    """Extract average discount by transaction type from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dictionary mapping transaction type to average discount
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        type_discounts = {}
        type_counts = {}
        for row in ws.iter_rows(min_row=2, max_row=ws.max_row, values_only=True):
            if not any(row):
                continue
            trans_type = row[3]
            discount = row[5] if row[5] is not None else 0
            if trans_type:
                type_discounts[trans_type] = type_discounts.get(trans_type, 0) + discount
                type_counts[trans_type] = type_counts.get(trans_type, 0) + 1
        avg_discounts = {}
        for trans_type in type_discounts:
            avg_discounts[trans_type] = type_discounts[trans_type] / type_counts[trans_type]
        return avg_discounts
    finally:
        os.unlink(tmp_path)

