def get_calc_max_cell_with_fill__fbce04ffc95d9094b14f26ad25a29679(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Find the cell with maximum value in a specified column and check if it has fill color.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: File path on VM
            - sheet: Sheet index (0-based) or name
            - column: Column letter (e.g., 'C')
            - start_row: Starting row (1-based, default 2)
            - end_row: Ending row (1-based, optional)

    Returns:
        Dict with information:
            - max_cell: Cell address with maximum value (e.g., 'C8')
            - max_value: The maximum value found
            - has_fill: bool (True if the max cell has any fill color)
            - fill_type: str (e.g., 'solid', 'pattern', None)
            - fg_color: str (foreground color)
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'C')
    start_row = config.get('start_row', 2)
    end_row = config.get('end_row', None)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'max_cell': None, 'max_value': None, 'has_fill': False, 'fill_type': None, 'fg_color': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        if end_row is None:
            end_row = ws.max_row
        max_value = None
        max_cell_addr = None
        for row in range(start_row, end_row + 1):
            cell_addr = f'{column}{row}'
            cell = ws[cell_addr]
            value = cell.value
            if value is not None and isinstance(value, (int, float)):
                if max_value is None or value > max_value:
                    max_value = value
                    max_cell_addr = cell_addr
        if max_cell_addr is None:
            return {'max_cell': None, 'max_value': None, 'has_fill': False, 'fill_type': None, 'fg_color': None}
        max_cell = ws[max_cell_addr]
        fill = max_cell.fill
        has_fill = False
        fill_type = None
        fg_color = None
        if fill and fill.fill_type:
            fill_type = fill.fill_type
            if fill_type == 'solid' and fill.start_color:
                fg_color = fill.start_color.rgb if hasattr(fill.start_color, 'rgb') else str(fill.start_color.index)
                has_fill = True
            elif fill_type == 'pattern' and fill.fgColor:
                fg_color = fill.fgColor.rgb if hasattr(fill.fgColor, 'rgb') else str(fill.fgColor.index)
                has_fill = True
        return {'max_cell': max_cell_addr, 'max_value': max_value, 'has_fill': has_fill, 'fill_type': fill_type, 'fg_color': fg_color}
    finally:
        os.unlink(tmp_path)

