def get_xlsx_first_words__38f10325b992595248bd0715379fd555(env, config: Dict[str, Any]) -> dict:
    """Verify first words were correctly extracted from movie titles.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to Excel file
            - column: Column letter to read from (e.g., 'B') - source movie titles
            - output_column: Column letter to write to (e.g., 'D') - extracted first words
            - start_row: Starting row number (1-indexed), default 2

    Returns:
        dict: Dictionary with verification results:
            - total_count: Total number of entries processed
            - correct_count: Number of correctly extracted first words
            - extracted_words: List of extracted words from output column
            - expected_words: List of expected first words from source column
    """
    file_path = config.get('path', '')
    source_column = config.get('column', 'B')
    output_column = config.get('output_column', 'D')
    start_row = config.get('start_row', 2)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'total_count': 0, 'correct_count': 0, 'extracted_words': [], 'expected_words': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        source_col_idx = openpyxl.utils.column_index_from_string(source_column)
        output_col_idx = openpyxl.utils.column_index_from_string(output_column)
        extracted_words = []
        expected_words = []
        correct_count = 0
        total_count = 0
        for row_num in range(start_row, ws.max_row + 1):
            source_cell = ws.cell(row=row_num, column=source_col_idx)
            source_value = source_cell.value
            output_cell = ws.cell(row=row_num, column=output_col_idx)
            output_value = output_cell.value
            if source_value is None or str(source_value).strip() == '':
                break
            total_count += 1
            source_text = str(source_value).strip()
            expected_first_word = source_text.split()[0] if source_text else ''
            expected_words.append(expected_first_word)
            if output_value is not None:
                extracted_word = str(output_value).strip()
                extracted_words.append(extracted_word)
                if extracted_word == expected_first_word:
                    correct_count += 1
            else:
                extracted_words.append('')
        wb.close()
        return {'total_count': total_count, 'correct_count': correct_count, 'extracted_words': extracted_words, 'expected_words': expected_words}
    finally:
        os.unlink(tmp_path)

def get_tb_oldest3_xlsx__dcd1e9d2ff68b2e8e650947cdbb3db16(env, config):
    """Extract oldest 3 emails data from Excel report.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of dicts with email data from the Excel file
    """
    file_path = config.get('path', '')
    if not file_path:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        expected_headers = ['sender_name', 'sender_email', 'date']
        actual_headers = []
        for col_idx in range(1, 4):
            header_value = ws.cell(1, col_idx).value
            if header_value:
                actual_headers.append(str(header_value).strip().lower())
            else:
                actual_headers.append('')
        if actual_headers != expected_headers:
            return []
        emails = []
        for row_idx in range(2, ws.max_row + 1):
            sender_name = ws.cell(row_idx, 1).value
            sender_email = ws.cell(row_idx, 2).value
            date_value = ws.cell(row_idx, 3).value
            if sender_name and sender_email and date_value:
                if isinstance(date_value, datetime):
                    date_str = date_value.strftime('%Y-%m-%d')
                elif isinstance(date_value, str):
                    try:
                        parsed_date = datetime.strptime(date_value.strip(), '%Y-%m-%d')
                        date_str = parsed_date.strftime('%Y-%m-%d')
                    except:
                        date_str = date_value.strip()
                else:
                    date_str = str(date_value)
                emails.append({'sender_name': sender_name, 'sender_email': sender_email, 'date': date_str})
        return emails
    finally:
        os.unlink(tmp_path)

