def get_xlsx_cell_fill__262c6dca7ace7b95a07b2edfcb9708b6(env, config: dict):
    """Extract row fill/highlight information from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', and 'cell' keys
            'cell' indicates the starting cell of the row to check

    Returns:
        dict: Row fill information with 'cells_with_fill', 'total_cells', and 'all_filled' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'cells_with_fill': 0, 'total_cells': 0, 'all_filled': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_ref = config.get('sheet', 0)
        if isinstance(sheet_ref, int):
            ws = wb.worksheets[sheet_ref]
        else:
            ws = wb[sheet_ref]
        cell = config.get('cell', 'A1')
        row_num = int(''.join(filter(str.isdigit, cell)))
        row_cells = list(ws[row_num])
        cells_to_check = []
        for cell_obj in row_cells:
            if cell_obj.value is not None or cell_obj.column <= ws.max_column:
                cells_to_check.append(cell_obj)
                if cell_obj.value is None and cell_obj.column > 2:
                    break
        if not cells_to_check:
            cells_to_check = [ws.cell(row=row_num, column=col) for col in range(1, 3)]
        cells_with_fill = 0
        total_cells = len(cells_to_check)
        for cell_obj in cells_to_check:
            has_fill = False
            if cell_obj.fill and cell_obj.fill.fgColor:
                fg_color = cell_obj.fill.fgColor
                if hasattr(fg_color, 'rgb') and fg_color.rgb:
                    color = fg_color.rgb
                    if color and color != 'FFFFFFFF' and (color != '00000000'):
                        has_fill = True
                elif hasattr(fg_color, 'indexed') and fg_color.indexed is not None:
                    has_fill = True
            if has_fill:
                cells_with_fill += 1
        all_filled = cells_with_fill == total_cells and total_cells > 0
        return {'cells_with_fill': cells_with_fill, 'total_cells': total_cells, 'all_filled': all_filled}
    finally:
        os.unlink(tmp_path)

