def get_pivot_product_revenue__06fd47db(env, config):
    """Extract pivot table data from Sheet2 for Product revenue analysis.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest'

    Returns:
        dict: Contains 'product_count' showing number of products found
    """
    vm_path = config.get('path', '/home/user/EntireSummerSales.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {'product_count': 0}
    cache_path = os.path.join(env.cache_dir, config.get('dest', 'EntireSummerSales.xlsx'))
    os.makedirs(os.path.dirname(cache_path), exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    if 'Sheet2' not in wb.sheetnames:
        wb.close()
        return {'product_count': 0}
    ws = wb['Sheet2']
    products_found = set()
    known_products = ['Quad', 'Carlota', 'Bellen', 'Sunshine', 'Doublers', 'Sunbell', 'Majectic Beaut', 'Sunset', 'Crested Beaut', 'FlatTop', 'Aspen', 'V-Rang']
    rows = list(ws.iter_rows(values_only=True))
    for row in rows:
        for cell_value in row:
            if cell_value in known_products:
                products_found.add(cell_value)
    wb.close()
    return {'product_count': len(products_found)}

