def get_csv_cell_value__ba8a616fb9c5e739d481f1c3515afe77(env, config):
    """Extract specific cell value from CSV file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'row', 'col' keys

    Returns:
        Cell value (string or None)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(mode='wb', suffix='.csv', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        with open(tmp_path, 'r', encoding='utf-8') as f:
            reader = csv.reader(f)
            rows = list(reader)
        row_idx = config['row']
        col_idx = config['col']
        if row_idx < len(rows) and col_idx < len(rows[row_idx]):
            return rows[row_idx][col_idx]
        return None
    finally:
        os.unlink(tmp_path)

