def get_xlsx_cell_value__57c547e1(env, config):
    """Get the value and formula of a specific cell in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (optional), 'cell'

    Returns:
        dict: {
            'value': The calculated cell value,
            'formula': The formula string if present (or None),
            'data_type': The cell data type ('f' for formula, 'n' for numeric, 's' for string, etc.)
        }
    """
    file_path = config.get('path', '/home/user/Set_Decimal_Separator_Dot.xlsx')
    sheet_idx = config.get('sheet', 0)
    cell_address = config.get('cell', 'A1')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    wb = openpyxl.load_workbook(tmp_path, data_only=False)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    cell = ws[cell_address]
    result = {'value': cell.value, 'formula': None, 'data_type': cell.data_type}
    if cell.data_type == 'f' and isinstance(cell.value, str) and cell.value.startswith('='):
        result['formula'] = cell.value
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws_data = wb_data.worksheets[sheet_idx]
        else:
            ws_data = wb_data[sheet_idx]
        result['value'] = ws_data[cell_address].value
        wb_data.close()
    wb.close()
    os.unlink(tmp_path)
    return result

def get_xlsx_channel_avg_revenue__6b85a440fb1ae1df9614be4e24d8d568(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract average revenue per sales channel from a new sheet.
    Expects the agent to create a table with sales channels and their average revenue.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'sheet_name'

    Returns:
        Dict with sales channel names as keys and average revenue values as floats
    """
    file_path = config.get('path', '/home/user/SummerSales.xlsx')
    sheet_name = config.get('sheet_name', 'Sheet2')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return {}
        ws = wb[sheet_name]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            channel = str(row[0]).strip() if row[0] else None
            avg_revenue = row[1] if row[1] is not None else 0.0
            if channel:
                try:
                    avg_revenue = float(avg_revenue)
                except (ValueError, TypeError):
                    avg_revenue = 0.0
                result[channel] = avg_revenue
        return result
    finally:
        os.unlink(tmp_path)

