def get_xlsx_highlighting__c851ef7c(env, config: dict) -> Dict[str, Any]:
    """Get highlighting info from Excel file.
    
    Args:
        env: DesktopEnv instance
        config: Config with 'path' and 'dest' keys
        
    Returns:
        Dictionary with cell highlighting information
    """
    import os
    vm_path = config.get('path', '')
    file_content = env.controller.get_file(vm_path)
    if not file_content:
        return {'error': 'Failed to get file from VM'}
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp_file:
        tmp_file.write(file_content)
        tmp_path = tmp_file.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        highlighted_cells = []
        for row in ws.iter_rows():
            for cell in row:
                if cell.fill and cell.fill.start_color:
                    color_value = cell.fill.start_color.rgb
                    if color_value and isinstance(color_value, str) and (len(color_value) == 8):
                        color_hex = color_value[2:].lower()
                        if color_hex != 'ffffff':
                            highlighted_cells.append({'cell': cell.coordinate, 'color': color_hex})
        wb.close()
        return {'highlighted_cells': highlighted_cells}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_xlsx_top_months__66f8e24e0f47f3058781a14f597bd216(env, config):
    """Extract top performing months from a new worksheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        dict: Dictionary containing:
            - 'headers': tuple of (header1, header2) from row 1
            - 'data': list of tuples (month_name, total_sales) in the order they appear
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'headers': None, 'data': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'headers': None, 'data': []}
        for sheet_name in wb.sheetnames:
            if sheet_name == 'Sheet1':
                continue
            ws = wb[sheet_name]
            header1 = ws.cell(1, 1).value
            header2 = ws.cell(1, 2).value
            result['headers'] = (str(header1) if header1 else '', str(header2) if header2 else '')
            for row_idx in range(2, ws.max_row + 1):
                month_name = ws.cell(row_idx, 1).value
                total = ws.cell(row_idx, 2).value
                if month_name is not None:
                    result['data'].append((str(month_name), float(total) if total is not None else 0.0))
            break
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

