def get_xlsx_header_bold__171a11ae(env, config: dict):
    """Extract comprehensive contact data from XLSX file and verify formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Contains contact data, header info, and validation flags
            {
                'exists': bool,
                'has_headers': bool,
                'all_headers_bold': bool,
                'headers': list,
                'row_count': int,
                'has_contact_data': bool,
                'has_valid_contact_fields': bool
            }
    """
    path = config.get('path', '')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return {'exists': False, 'has_headers': False, 'all_headers_bold': False, 'headers': [], 'row_count': 0, 'has_contact_data': False, 'has_valid_contact_fields': False}
    try:
        wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=False)
        ws = wb.active
        row_count = ws.max_row - 1 if ws.max_row > 1 else 0
        headers = []
        all_bold = True
        has_headers = False
        for cell in ws[1]:
            if cell.value:
                headers.append(str(cell.value).strip())
                has_headers = True
                if not (cell.font and cell.font.bold):
                    all_bold = False
        if not has_headers:
            all_bold = False
        contact_field_keywords = ['name', 'email', 'mail', 'phone', 'tel', 'address', 'first', 'last', 'display', 'nickname', 'organization', 'work', 'home', 'mobile', 'cell']
        has_valid_fields = False
        if headers:
            headers_lower = [h.lower() for h in headers]
            for keyword in contact_field_keywords:
                if any((keyword in h for h in headers_lower)):
                    has_valid_fields = True
                    break
        has_data = row_count > 0
        return {'exists': True, 'has_headers': has_headers, 'all_headers_bold': all_bold and has_headers, 'headers': headers, 'row_count': row_count, 'has_contact_data': has_data, 'has_valid_contact_fields': has_valid_fields}
    except Exception as e:
        return {'exists': True, 'has_headers': False, 'all_headers_bold': False, 'headers': [], 'row_count': 0, 'has_contact_data': False, 'has_valid_contact_fields': False}

def get_xlsx_table_data__447f5fcf01e57a045588cce9783df3a1(env, config: dict):
    """Extract table data from a range in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM path to Excel file),
                'sheet' (sheet index, default 0), and 'range' (cell range like 'B2:F5')

    Returns:
        List of lists representing the table data
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cell_range = config.get('range')
    if not file_path or not cell_range:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell_range_obj = ws[cell_range]
        result = []
        for row in cell_range_obj:
            row_data = [cell.value for cell in row]
            result.append(row_data)
        return result
    except Exception as e:
        print(f'Error reading Excel table: {e}')
        return []
    finally:
        os.unlink(tmp_path)

