def get_xlsx_sheet_data__c18ab3d43b1c909fcfe0dd91da5bd04c(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract sheet cell values and merge status for verification.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with cell values and merge information
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb.sheetnames, 'data': {}}
        for sheet_name in wb.sheetnames:
            ws = wb[sheet_name]
            sheet_data = {}
            merged_cells = []
            for merged_range in ws.merged_cells.ranges:
                merged_cells.append(str(merged_range))
            for row in ws.iter_rows():
                for cell in row:
                    coord = cell.coordinate
                    is_merged = False
                    for merged_range in ws.merged_cells.ranges:
                        if cell.coordinate in merged_range:
                            is_merged = True
                            break
                    sheet_data[coord] = {'value': cell.value, 'merged': is_merged}
            result['data'][sheet_name] = {'cells': sheet_data, 'merged_ranges': merged_cells}
        return result
    finally:
        os.unlink(tmp_path)

def get_cell_fill_color__9226d69f(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Extract max value cell and highlight info from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'range'

    Returns:
        Dict with:
        - 'max_cell': Cell coordinate of max value (e.g., 'D5')
        - 'max_value': The maximum value found
        - 'max_cell_color': Fill color of max cell or None
        - 'other_cells_colors': Dict of {cell: color} for other cells in range
    """
    path = config.get('path', '/home/user/Students_Class_Subject_Marks.xlsx')
    sheet_idx = config.get('sheet', 0)
    cell_range = config.get('range', 'C5:F5')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cells = ws[cell_range]
        if not isinstance(cells, tuple):
            cells = (cells,)
        if cells and isinstance(cells[0], tuple):
            cells = cells[0]
        max_value = None
        max_cell = None
        cell_values = {}
        for cell_obj in cells:
            val = cell_obj.value
            if val is not None:
                try:
                    val = float(val)
                    cell_values[cell_obj.coordinate] = val
                    if max_value is None or val > max_value:
                        max_value = val
                        max_cell = cell_obj.coordinate
                except (ValueError, TypeError):
                    pass
        if max_cell is None:
            wb.close()
            return None
        max_cell_obj = ws[max_cell]
        max_fill = max_cell_obj.fill
        max_color = None
        if max_fill and hasattr(max_fill, 'start_color') and max_fill.start_color:
            max_color = max_fill.start_color.rgb if hasattr(max_fill.start_color, 'rgb') else None
        other_colors = {}
        for cell_obj in cells:
            if cell_obj.coordinate != max_cell:
                fill = cell_obj.fill
                if fill and hasattr(fill, 'start_color') and fill.start_color:
                    color = fill.start_color.rgb if hasattr(fill.start_color, 'rgb') else None
                    if color and color != '00000000':
                        other_colors[cell_obj.coordinate] = color
        wb.close()
        return {'max_cell': max_cell, 'max_value': max_value, 'max_cell_color': max_color, 'other_cells_colors': other_colors}
    finally:
        os.unlink(tmp_path)

