def get_xlsx_full_names__984ff255(env, config: dict):
    """
    Get full names by combining first and last names from columns B and C
    for specified rows to verify name splitting was done correctly.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM file path to the Excel file
            - sheet: Sheet index (0-based)
            - rows: List of row numbers (1-based) to check

    Returns:
        dict: Dictionary mapping row numbers (as strings) to full names (FirstName + LastName)
              e.g., {"2": "Benedict Cucumberbach", "8": "Parah Salin"}
    """
    vm_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    rows = config.get('rows', [])
    file_content = env.controller.get_file(vm_path)
    if file_content is None:
        return None
    dest = os.path.basename(vm_path)
    cache_path = os.path.join(env.cache_dir, dest)
    os.makedirs(os.path.dirname(cache_path), exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_content)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    full_names = {}
    for row_num in rows:
        first_name = ws[f'B{row_num}'].value
        last_name = ws[f'C{row_num}'].value
        if first_name is not None and last_name is not None:
            full_name = f'{str(first_name).strip()} {str(last_name).strip()}'
            full_names[str(row_num)] = full_name
        else:
            full_names[str(row_num)] = None
    return full_names

