def get_xlsx_formula_params__b7e24a1e4eec88c71eb09aeef09df5f0(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract formula and parse FIXED/TEXT function parameters.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'cell' (cell address)

    Returns:
        Dict with 'formula', 'has_format_func', and 'decimal_places' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'formula': '', 'has_format_func': False, 'decimal_places': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        ws = wb.active
        cell_address = config.get('cell', 'D1')
        cell = ws[cell_address]
        formula = cell.value if cell.value else ''
        result = {'formula': formula, 'has_format_func': False, 'decimal_places': None}
        fixed_match = re.search('FIXED\\([^,]+,\\s*(\\d+)\\s*\\)', formula, re.IGNORECASE)
        if fixed_match:
            result['has_format_func'] = True
            result['decimal_places'] = int(fixed_match.group(1))
            return result
        text_match = re.search('TEXT\\([^,]+,\\s*"[^"]*\\.(\\d+)"', formula, re.IGNORECASE)
        if text_match:
            result['has_format_func'] = True
            result['decimal_places'] = len(text_match.group(1))
        return result
    finally:
        os.unlink(tmp_path)

