def get_xlsx_late_arrival_data__667baa6b(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract employee attendance data to verify late arrival counting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' keys

    Returns:
        Dict containing:
            - 'cell_a1_value': Value in cell A1 (the user's answer)
            - 'late_count': Actual count of employees who arrived after 9:00 AM on 6/21/2023
            - 'late_employees': List of employee names who arrived late
            - 'all_employees': List of all employee records for verification
    """
    path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    target_date_str = config.get('target_date', '6/21/2023')
    late_time_threshold = config.get('late_time', '9:00 AM')
    file_bytes = env.controller.get_file(path)
    if file_bytes is None:
        return {'cell_a1_value': None, 'late_count': 0, 'late_employees': [], 'all_employees': [], 'error': 'File not found'}
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell_a1_value = ws['A1'].value
        target_date = parse_date(target_date_str)
        threshold_time = parse_time(late_time_threshold)
        late_employees = []
        all_employees = []
        for row_idx in range(2, ws.max_row + 1):
            name_cell = ws[f'B{row_idx}']
            date_cell = ws[f'C{row_idx}']
            time_cell = ws[f'D{row_idx}']
            name = name_cell.value
            date_val = date_cell.value
            time_val = time_cell.value
            if not name or not date_val or (not time_val):
                continue
            emp_date = parse_date_value(date_val)
            emp_time = parse_time_value(time_val)
            employee_record = {'name': str(name), 'date': str(date_val), 'time': str(time_val), 'parsed_date': emp_date, 'parsed_time': emp_time}
            all_employees.append(employee_record)
            if emp_date and emp_time and target_date:
                if dates_match(emp_date, target_date):
                    if emp_time > threshold_time:
                        late_employees.append(str(name))
        wb.close()
        return {'cell_a1_value': cell_a1_value, 'late_count': len(late_employees), 'late_employees': late_employees, 'all_employees': all_employees, 'error': None}
    finally:
        import os
        os.unlink(tmp_path)

