def get_xlsx_column_sorted_desc__42727de9(env, config):
    """Extract column data in descending order from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: Path to the Excel file on VM
            - sheet: Sheet index (0-based)
            - column: Column letter (e.g., 'D')
            - start_row: Starting row (1-based, default 2 to skip header)

    Returns:
        list: Column values sorted in descending order
    """
    path = config.get('path', '/home/user/Arrang_Value_min_to_max.xlsx')
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'D')
    start_row = config.get('start_row', 2)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return []
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        values = []
        for row in range(start_row, ws.max_row + 1):
            cell_value = ws[f'{column}{row}'].value
            if cell_value is not None:
                values.append(cell_value)
        sorted_values = sorted(values, reverse=True)
        return sorted_values
    finally:
        import os
        os.unlink(tmp_path)

