def get_pptx_table_cells__03ea8597(env, config):
    """Extract specific cell values from a PowerPoint table.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM file path to the PPTX file
            - dest: Destination filename in cache
            - slide_index: Index of the slide (0-based)
            - shape_index: Index of the table shape (0-based, default 1)
            - cells: List of dicts with 'row' and 'col' keys
            
    Returns:
        Dict mapping (row, col) tuples to cell text values
    """
    import os
    vm_path = config.get('path', '/home/user/Desktop/33_1.pptx')
    dest_filename = config.get('dest', '33_1.pptx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    cache_path = os.path.join(env.cache_dir, dest_filename)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    prs = Presentation(cache_path)
    slide_index = config.get('slide_index', 3)
    shape_index = config.get('shape_index', 1)
    cells_to_check = config.get('cells', [])
    if slide_index >= len(prs.slides):
        return {}
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return {}
    shape = slide.shapes[shape_index]
    if not shape.has_table:
        return {}
    table = shape.table
    result = {}
    for cell_spec in cells_to_check:
        row = cell_spec['row']
        col = cell_spec['col']
        if row < len(table.rows) and col < len(table.columns):
            cell = table.rows[row].cells[col]
            result[f'{row},{col}'] = cell.text.strip()
    return result

def get_docx_table_cell__dc3688e6(env, config: dict):
    """Extract a specific cell value from a table in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM path to the docx file
            - dest: Local destination filename
            - table_index: Which table to extract from (0-based)
            - row: Row index (0-based)
            - col: Column index (0-based)

    Returns:
        Cell text content (stripped)
    """
    try:
        vm_path = config.get('path', '/home/user/Documents/awesome-desktop/awe_desk_env.docx')
        file_bytes = env.controller.get_file(vm_path)
        if not file_bytes:
            logger.error(f'Failed to get file from VM: {vm_path}')
            return None
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        try:
            doc = Document(tmp_path)
            table_index = config.get('table_index', 0)
            if table_index >= len(doc.tables):
                logger.error(f'Table index {table_index} out of range (only {len(doc.tables)} tables)')
                return None
            table = doc.tables[table_index]
            row = config.get('row', 0)
            col = config.get('col', 0)
            if row >= len(table.rows):
                logger.error(f'Row index {row} out of range (only {len(table.rows)} rows)')
                return None
            if col >= len(table.columns):
                logger.error(f'Column index {col} out of range (only {len(table.columns)} columns)')
                return None
            cell_text = table.cell(row, col).text.strip()
            logger.info(f'Extracted cell ({row}, {col}): {cell_text}')
            return cell_text
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error extracting docx table cell: {e}')
        return None

