def get_xlsx_min_value__d4f5dd7f493a2bdcc0b057e599305b86(env, config: dict):
    """Verify formulas were copied and check minimum value in B31.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'sheet'

    Returns:
        dict: {
            'b_formulas_copied': bool,  # True if formulas exist in B3:B30
            'd_formulas_copied': bool,  # True if formulas exist in D3:D30
            'b31_value': float or None, # Value in cell B31
            'computed_min': float or None  # Actual min from B2:B30
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_formulas = openpyxl.load_workbook(tmp_path, data_only=False)
        ws_formulas = wb_formulas.worksheets[config.get('sheet', 0)]
        wb_values = openpyxl.load_workbook(tmp_path, data_only=True)
        ws_values = wb_values.worksheets[config.get('sheet', 0)]
        b_formulas_count = 0
        for row in range(3, 31):
            cell = ws_formulas[f'B{row}']
            if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
                b_formulas_count += 1
        b_formulas_copied = b_formulas_count >= 20
        d_formulas_count = 0
        for row in range(3, 31):
            cell = ws_formulas[f'D{row}']
            if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
                d_formulas_count += 1
        d_formulas_copied = d_formulas_count >= 20
        b31_cell = ws_values['B31']
        b31_value = b31_cell.value if isinstance(b31_cell.value, (int, float)) else None
        min_val = None
        for row in range(2, 31):
            cell_value = ws_values[f'B{row}'].value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                if min_val is None or cell_value < min_val:
                    min_val = cell_value
        return {'b_formulas_copied': b_formulas_copied, 'd_formulas_copied': d_formulas_copied, 'b31_value': round(b31_value, 6) if b31_value is not None else None, 'computed_min': round(min_val, 6) if min_val is not None else None}
    finally:
        os.unlink(tmp_path)

