def get_xlsx_number_format__26697e57(env, config):
    """Get number format for cells in a range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (int), 'range' (str like "A2:A20")

    Returns:
        Dictionary with format check results
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    file_path = get_vm_file(env, {'path': config['path'], 'dest': os.path.basename(config['path'])})
    if file_path is None:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return {'has_format': False, 'decimal_places': 0}
    wb = openpyxl.load_workbook(file_path)
    if isinstance(config['sheet'], int):
        ws = wb.worksheets[config['sheet']]
    else:
        ws = wb[config['sheet']]
    cell_range = config['range']
    format_count = 0
    total_cells = 0
    decimal_places_set = set()
    for row in ws[cell_range]:
        for cell in row:
            if cell.value is not None and isinstance(cell.value, (int, float)):
                total_cells += 1
                number_format = cell.number_format
                if number_format and ('0.00' in number_format or '.00' in number_format):
                    format_count += 1
                    if '0.00' in number_format:
                        decimal_places_set.add(2)
    if total_cells == 0:
        return {'has_format': False, 'decimal_places': 0}
    format_ratio = format_count / total_cells
    has_format = format_ratio >= 0.8
    return {'has_format': has_format, 'decimal_places': 2 if has_format else 0, 'format_ratio': format_ratio}

