def get_xlsx_sales_data__cbbc75d6407b4dcf95a44eaf4265fde3(env, config):
    """Extract sales data from Excel file.
    
    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to Excel file on VM
        
    Returns:
        dict: Dictionary containing cell values and chart information
    """
    file_path = config.get('path', '/home/user/SalesRep.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'Failed to retrieve file from VM'}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        for row in range(1, 20):
            for col in range(1, 10):
                cell = ws.cell(row=row, column=col)
                cell_address = cell.coordinate
                cell_value = cell.value
                result[cell_address] = cell_value
                if cell.fill and cell.fill.fgColor:
                    color = cell.fill.fgColor
                    if hasattr(color, 'rgb') and color.rgb:
                        result[f'{cell_address}_fill'] = color.rgb
        charts = []
        if hasattr(ws, '_charts'):
            for chart in ws._charts:
                chart_info = {}
                chart_type = type(chart).__name__
                chart_info['type'] = chart_type
                if hasattr(chart, 'title') and chart.title:
                    chart_info['title'] = str(chart.title.text.rich.p[0].text) if hasattr(chart.title.text, 'rich') else str(chart.title)
                else:
                    chart_info['title'] = None
                series_data = []
                if hasattr(chart, 'series'):
                    for series in chart.series:
                        series_info = {}
                        if hasattr(series, 'val') and series.val:
                            if hasattr(series.val, 'numRef') and series.val.numRef:
                                if hasattr(series.val.numRef, 'f') and series.val.numRef.f:
                                    series_info['value_range'] = series.val.numRef.f
                        if hasattr(series, 'cat') and series.cat:
                            if hasattr(series.cat, 'strRef') and series.cat.strRef:
                                if hasattr(series.cat.strRef, 'f') and series.cat.strRef.f:
                                    series_info['category_range'] = series.cat.strRef.f
                        series_data.append(series_info)
                chart_info['series'] = series_data
                chart_info['series_count'] = len(series_data)
                charts.append(chart_info)
        result['_charts'] = charts
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_xlsx_table__a88daa14(env, config: Dict[str, Any]) -> Union[List[List[Any]], Dict[str, Any]]:
    """Extract table data from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of lists (rows) or dict depending on structure
    """
    file_path = config.get('path', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(mode='wb', delete=False, suffix='.xlsx') as f:
        f.write(file_bytes)
        temp_path = f.name
    try:
        wb = openpyxl.load_workbook(temp_path, data_only=True)
        ws = wb.active
        data = []
        for row in ws.iter_rows(values_only=True):
            if any((cell is not None for cell in row)):
                data.append(list(row))
        wb.close()
        return data
    finally:
        if os.path.exists(temp_path):
            os.unlink(temp_path)

def get_xlsx_column_values__7ca3049c5f436c8f2c0488428339cb7a(env, config: dict):
    """Extract values from a specific column in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column', 'start_row', 'end_row' keys

    Returns:
        List of values from the specified column
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'A')
    start_row = config.get('start_row', 1)
    end_row = config.get('end_row', 100)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        values = []
        for row_idx in range(start_row, end_row + 1):
            cell_addr = f'{column}{row_idx}'
            cell_value = ws[cell_addr].value
            if cell_value is not None:
                values.append(cell_value)
            else:
                break
        return values
    finally:
        os.unlink(tmp_path)

