def get_xlsx_cell_value__e2b4167d2b2517abf6b6b8d679dce6d7(env, config: dict):
    """Extract both the cell value and formula from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'sheet' (sheet index), 'cell' (cell address)

    Returns:
        dict: {'value': cell_value, 'formula': cell_formula}
              - value: The computed value (from data_only=True workbook)
              - formula: The formula string or None if no formula
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'value': None, 'formula': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        ws_data = wb_data.worksheets[sheet_idx]
        cell_addr = config['cell']
        cell_value = ws_data[cell_addr].value
        wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
        ws_formula = wb_formula.worksheets[sheet_idx]
        cell_obj = ws_formula[cell_addr]
        cell_formula = cell_obj.value if isinstance(cell_obj.value, str) and cell_obj.value.startswith('=') else None
        return {'value': cell_value, 'formula': cell_formula}
    finally:
        os.unlink(tmp_path)

def get_xlsx_and_source_restaurants__75d20d5b(env, config: Dict[str, Any]) -> Dict[str, List[str]]:
    """Get restaurant names from both XLSX and source file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'xlsx_path' and 'source_path' keys

    Returns:
        Dict with 'xlsx_names' and 'source_names' lists
    """
    xlsx_path = config.get('xlsx_path', '/home/user/Desktop/MUST_VISIT.xlsx')
    source_path = config.get('source_path', '/home/user/Desktop/restaurants.txt')
    result = {'xlsx_names': [], 'source_names': []}
    xlsx_bytes = env.controller.get_file(xlsx_path)
    if xlsx_bytes:
        wb = openpyxl.load_workbook(io.BytesIO(xlsx_bytes), data_only=True)
        ws = wb.active
        for row in range(2, 20):
            cell_value = ws.cell(row=row, column=1).value
            if cell_value and str(cell_value).strip():
                result['xlsx_names'].append(str(cell_value).strip())
            elif len(result['xlsx_names']) > 0:
                break
    source_bytes = env.controller.get_file(source_path)
    if source_bytes:
        source_text = source_bytes.decode('utf-8', errors='ignore')
        for line in source_text.strip().split('\n'):
            line = line.strip()
            if line:
                import re
                cleaned = re.sub('^\\d+\\.\\s*', '', line)
                if cleaned:
                    result['source_names'].append(cleaned)
    return result

def get_xlsx_sheet_exists__a5791a19(env, config: dict) -> Optional[bool]:
    """
    Check if a sheet with specific name exists in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to the Excel file on VM
            - sheet_name: Name of sheet to check for

    Returns:
        True if sheet exists, False otherwise, None on error
    """
    file_path = config.get('path')
    sheet_name = config.get('sheet_name')
    if not all([file_path, sheet_name]):
        return None
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return None
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            wb = openpyxl.load_workbook(tmp_path, data_only=True)
            exists = sheet_name in wb.sheetnames
            wb.close()
            return exists
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
    except Exception as e:
        print(f'Error checking sheet existence: {e}')
        return None

def get_calc_sheet_structure__99d7a8226c0ebf89ec96b9a153f3644e(env, config):
    """Extract sheet structure (cell values and merge status) from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Sheet structure with cell values and merge information
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb.sheetnames, 'sheet_data': {}}
        for sheet_name in wb.sheetnames:
            ws = wb[sheet_name]
            sheet_info = {'cells': {}, 'merged_cells': []}
            for merged_range in ws.merged_cells.ranges:
                sheet_info['merged_cells'].append(str(merged_range))
            for row in ws.iter_rows(min_row=1, max_row=min(10, ws.max_row), min_col=1, max_col=min(10, ws.max_column)):
                for cell in row:
                    if cell.value is not None or isinstance(cell, openpyxl.cell.cell.MergedCell):
                        sheet_info['cells'][cell.coordinate] = {'value': cell.value, 'is_merged': isinstance(cell, openpyxl.cell.cell.MergedCell)}
            result['sheet_data'][sheet_name] = sheet_info
        return result
    finally:
        os.unlink(tmp_path)

