    wb = openpyxl.load_workbook(file_path, data_only=False)
    sheet_idx = config.get('sheet', 0)
    ws = wb.worksheets[sheet_idx] if isinstance(sheet_idx, int) else wb[sheet_idx]
    cell = ws[config['cell']]
    result = {'value': cell.value, 'data_type': cell.data_type, 'is_formula': cell.data_type == 'f'}
    if result['is_formula']:
        wb_data = openpyxl.load_workbook(file_path, data_only=True)
        ws_data = wb_data.worksheets[sheet_idx] if isinstance(sheet_idx, int) else wb_data[sheet_idx]
        result['calculated_value'] = ws_data[config['cell']].value
        wb_data.close()
    else:
        result['calculated_value'] = cell.value
    wb.close()
    return result

