def get_xlsx_row_count__6c4a1081(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Get AutoFilter information and visible row count from an xlsx file.
    This function reads the xlsx XML structure to verify AutoFilter is applied and counts visible rows.

    Args:
        env: Environment object
        config: Configuration dict with keys:
            - path: absolute path on the VM to fetch
            - dest: file name of the downloaded file
            - sheet: sheet index (0-based)

    Returns:
        dict: Dictionary containing:
            - visible_row_count: Number of visible (non-hidden) rows
            - autofilter_enabled: Boolean indicating if AutoFilter is enabled
            - autofilter_ref: The cell range reference for AutoFilter (e.g., "A1:E35")
            - type_column_filtered: Boolean indicating if the Type column has filtering
            - visible_row_types: List of Type values in visible rows
            - hidden_row_types: List of Type values in hidden rows
    """
    path = config['path']
    dest = config['dest']
    sheet_idx = config.get('sheet', 0)
    file_path = env.controller.get_file(path)
    if file_path is None:
        return {'visible_row_count': 0, 'autofilter_enabled': False, 'autofilter_ref': None, 'type_column_filtered': False, 'visible_row_types': [], 'hidden_row_types': []}
    cache_path = os.path.join(env.cache_dir, dest)
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_path)
    try:
        zfile = zipfile.ZipFile(cache_path, 'r')
        body_tree = etree.fromstring(zfile.read('xl/workbook.xml'))
        body_rel = etree.fromstring(zfile.read('xl/_rels/workbook.xml.rels'))
        ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main', 'rel': 'http://schemas.openxmlformats.org/package/2006/relationships', 'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
        sheet_rids = body_tree.xpath('.//s:sheet/@r:id', namespaces=ns)
        rids = body_rel.xpath('.//rel:Relationship/@Id', namespaces=ns)
        targets = body_rel.xpath('.//rel:Relationship/@Target', namespaces=ns)
        body_rel_dict = {rid: target for (rid, target) in zip(rids, targets)}
        sheet_rid = sheet_rids[sheet_idx]
        sheet_id = body_rel_dict[sheet_rid].split('/')[-1].split('.')[0]
        sheet_xml_path = f'xl/worksheets/{sheet_id}.xml'
        sheet_tree = etree.fromstring(zfile.read(sheet_xml_path))
        autofilter_elements = sheet_tree.xpath('.//s:autoFilter', namespaces=ns)
        autofilter_enabled = len(autofilter_elements) > 0
        autofilter_ref = None
        type_column_filtered = False
        if autofilter_enabled:
            autofilter_ref = autofilter_elements[0].get('ref')
            filter_columns = autofilter_elements[0].xpath('.//s:filterColumn', namespaces=ns)
            if filter_columns:
                for fc in filter_columns:
                    col_id = fc.get('colId')
                    if col_id == '1':
                        type_column_filtered = True
                        break
        shared_strings = []
        try:
            shared_strings_xml = zfile.read('xl/sharedStrings.xml')
            shared_strings_tree = etree.fromstring(shared_strings_xml)
            shared_strings = [''.join((t.text for t in si.xpath('.//s:t', namespaces=ns) if t.text)) for si in shared_strings_tree.xpath('.//s:si', namespaces=ns)]
        except:
            pass
        hidden_rows_attrs = sheet_tree.xpath(".//s:row[@hidden='1']/@r", namespaces=ns) + sheet_tree.xpath(".//s:row[@hidden='true']/@r", namespaces=ns)
        hidden_rows = set((int(idx) for idx in hidden_rows_attrs))
        all_rows_attrs = sheet_tree.xpath('.//s:row/@r', namespaces=ns)
        all_rows = set((int(idx) for idx in all_rows_attrs))
        visible_row_count = len(all_rows - hidden_rows)
        visible_row_types = []
        hidden_row_types = []
        rows = sheet_tree.xpath('.//s:row', namespaces=ns)
        for row in rows:
            row_num = int(row.get('r'))
            if row_num == 1:
                continue
            cells = row.xpath('.//s:c[@r]', namespaces=ns)
            type_value = None
            for cell in cells:
                cell_ref = cell.get('r')
                if cell_ref and cell_ref[0] == 'B':
                    cell_type = cell.get('t')
                    value_elem = cell.xpath('.//s:v', namespaces=ns)
                    if value_elem:
                        value = value_elem[0].text
                        if cell_type == 's':
                            type_value = shared_strings[int(value)] if value else None
                        else:
                            type_value = value
                    break
            if type_value:
                if row_num in hidden_rows:
                    hidden_row_types.append(type_value)
                else:
                    visible_row_types.append(type_value)
        zfile.close()
        return {'visible_row_count': visible_row_count, 'autofilter_enabled': autofilter_enabled, 'autofilter_ref': autofilter_ref, 'type_column_filtered': type_column_filtered, 'visible_row_types': visible_row_types, 'hidden_row_types': hidden_row_types}
    except Exception as e:
        print(f'Error reading xlsx file: {e}')
        import traceback
        traceback.print_exc()
        return {'visible_row_count': 0, 'autofilter_enabled': False, 'autofilter_ref': None, 'type_column_filtered': False, 'visible_row_types': [], 'hidden_row_types': []}

def get_xlsx_row_colors__8d8ae0e8(env, config: dict):
    """Get background colors for specified rows.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'rows', 'column'

    Returns:
        Dict mapping row numbers to hex colors
    """
    path = config.get('path', '/home/user/Employee_Roles_and_Ranks.xlsx')
    sheet_idx = config.get('sheet', 0)
    rows = config.get('rows', [])
    column = config.get('column', 'B')
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return {}
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    wb = openpyxl.load_workbook(tmp_path)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    row_colors = {}
    for row_num in rows:
        cell = ws[f'{column}{row_num}']
        if cell.fill and cell.fill.fgColor:
            color = cell.fill.fgColor.rgb
            if color and color != '00000000':
                row_colors[row_num] = color
            else:
                row_colors[row_num] = None
        else:
            row_colors[row_num] = None
    import os
    os.unlink(tmp_path)
    return row_colors

def get_pptx_table_cell__8d5123f9(env, config):
    """Get a specific cell value from a PowerPoint table.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'slide_index', 'row', 'col'

    Returns:
        str: The cell text content
    """
    path = config['path']
    slide_index = config['slide_index']
    row = config['row']
    col = config['col']
    local_path = get_vm_file(env, {'path': path, 'dest': os.path.basename(path)})
    prs = Presentation(local_path)
    slide = prs.slides[slide_index]
    for shape in slide.shapes:
        if shape.has_table:
            table = shape.table
            return table.rows[row].cells[col].text
    return None

