def get_xlsx_filled_row_count__20778792(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Count how many data rows are filled in the XLSX file with comprehensive checks.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'columns_to_check' keys

    Returns:
        Dict with row count and completeness information for all required columns
    """
    file_path = config.get('path', '/home/user/Desktop/MUST_VISIT.xlsx')
    columns_to_check = config.get('columns_to_check', [1, 2, 3, 4, 5])
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'count': 0, 'all_columns_filled': False, 'column_counts': {}}
    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)
    ws = wb.active
    filled_count = 0
    column_filled_counts = {col: 0 for col in columns_to_check}
    all_columns_filled_rows = 0
    for row in range(2, 50):
        has_any_data = False
        has_all_data = True
        for col in columns_to_check:
            cell_value = ws.cell(row=row, column=col).value
            has_content = cell_value is not None and str(cell_value).strip()
            if has_content:
                has_any_data = True
                column_filled_counts[col] += 1
            else:
                has_all_data = False
        if has_any_data:
            filled_count += 1
            if has_all_data:
                all_columns_filled_rows += 1
        elif filled_count > 0:
            break
    all_columns_complete = len(set(column_filled_counts.values())) == 1 and filled_count > 0 and (all_columns_filled_rows == filled_count)
    return {'count': filled_count, 'all_columns_filled': all_columns_complete, 'column_counts': column_filled_counts, 'complete_rows': all_columns_filled_rows}

def get_xlsx_percentage_format__97e9aaa6da443970ba8d4d3b6503e86a(env, config):
    """Extract cell values from column B to verify percentage formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary mapping cell addresses to their formatted string values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        ws = wb.active
        result = {}
        for row in range(2, 9):
            cell_addr = f'B{row}'
            cell = ws[cell_addr]
            cell_value = cell.value
            if cell_value is None:
                result[cell_addr] = None
                continue
            number_format = cell.number_format
            if number_format and '%' in number_format:
                percentage_value = float(cell_value) * 100
                result[cell_addr] = f'{percentage_value:.1f}%'
            else:
                result[cell_addr] = str(cell_value)
        return result
    finally:
        os.unlink(tmp_path)

