def get_xlsx_cell_value__0c221862(env, config: dict):
    """Extract a cell value from an Excel file and verify intermediate steps.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell' keys

    Returns:
        dict: Contains 'cell_value', 'csv_exists', 'has_contact_data', 'row_count', 'col_count'
    """
    vm_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    cell_addr = config.get('cell', 'A1')
    result = {'cell_value': None, 'csv_exists': False, 'has_contact_data': False, 'row_count': 0, 'col_count': 0}
    csv_path = '/home/user/Desktop/contacts.csv'
    try:
        csv_bytes = env.controller.get_file(csv_path)
        if csv_bytes:
            result['csv_exists'] = True
    except:
        pass
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return result
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        result['cell_value'] = ws[cell_addr].value
        max_row = 0
        max_col = 0
        for row in ws.iter_rows():
            for cell in row:
                if cell.value is not None:
                    max_row = max(max_row, cell.row)
                    max_col = max(max_col, cell.column)
        result['row_count'] = max_row
        result['col_count'] = max_col
        if max_row >= 2 and max_col >= 2:
            result['has_contact_data'] = True
        wb.close()
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

