def get_calc_chart_info__93d7dd635bdefcf47a6bf957130e6a39(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract chart information from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict containing chart properties (type, data range, categories, etc.)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        import openpyxl
        from openpyxl.chart import PieChart, BarChart, LineChart
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        charts = list(ws._charts)
        if not charts:
            return {'has_chart': False, 'chart_count': 0}
        result = {'has_chart': True, 'chart_count': len(charts)}
        if charts:
            chart = charts[0]
            if isinstance(chart, PieChart):
                result['chart_type'] = 'pie'
            elif isinstance(chart, BarChart):
                result['chart_type'] = 'bar'
            elif isinstance(chart, LineChart):
                result['chart_type'] = 'line'
            else:
                result['chart_type'] = type(chart).__name__
            if hasattr(chart, 'series') and chart.series:
                series = chart.series[0]
                if hasattr(series, 'val') and series.val:
                    data_ref = str(series.val)
                    result['data_range'] = data_ref
                    if '$' in data_ref:
                        parts = data_ref.split('$')
                        rows = [p for p in parts if p.isdigit()]
                        if rows:
                            result['data_row'] = int(rows[0])
                        if ':' in data_ref:
                            range_parts = data_ref.split(':')
                            if len(range_parts) == 2:
                                start_col = range_parts[0].split('$')[1] if '$' in range_parts[0] else None
                                end_col = range_parts[1].split('$')[1] if '$' in range_parts[1] else None
                                if start_col and end_col:
                                    start_col_num = sum(((ord(c) - ord('A') + 1) * 26 ** i for (i, c) in enumerate(reversed(start_col.upper()))))
                                    end_col_num = sum(((ord(c) - ord('A') + 1) * 26 ** i for (i, c) in enumerate(reversed(end_col.upper()))))
                                    result['data_point_count'] = end_col_num - start_col_num + 1
                if hasattr(series, 'cat') and series.cat:
                    cat_ref = str(series.cat)
                    result['category_range'] = cat_ref
                    try:
                        if '$' in cat_ref and ':' in cat_ref:
                            parts = cat_ref.split(':')
                            if len(parts) == 2:
                                start_parts = parts[0].split('$')
                                if len(start_parts) >= 3:
                                    cat_row = int(start_parts[2])
                                    start_col = start_parts[1]
                                    end_parts = parts[1].split('$')
                                    if len(end_parts) >= 2:
                                        end_col = end_parts[1]
                                        categories = []
                                        start_col_idx = sum(((ord(c) - ord('A') + 1) * 26 ** i for (i, c) in enumerate(reversed(start_col.upper()))))
                                        end_col_idx = sum(((ord(c) - ord('A') + 1) * 26 ** i for (i, c) in enumerate(reversed(end_col.upper()))))
                                        for col_idx in range(start_col_idx, end_col_idx + 1):
                                            cell_value = ws.cell(row=cat_row, column=col_idx).value
                                            if cell_value:
                                                categories.append(str(cell_value))
                                        if categories:
                                            result['categories'] = categories
                                            result['category_count'] = len(categories)
                    except:
                        pass
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_row_fill_colors__25778d8b(env, config):
    """Get fill colors for specified rows.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'rows', 'column'

    Returns:
        Dict mapping row numbers to fill color hex codes
    """
    vm_path = config.get('path', '/home/user/Desktop/Professor_Contact.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    import os
    local_path = os.path.join(env.cache_dir, 'temp_prof_contact_v4.xlsx')
    with open(local_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(local_path)
    sheet_idx = config.get('sheet', 0)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    rows = config.get('rows', [])
    column = config.get('column', 'B')
    from openpyxl.utils import column_index_from_string
    col_idx = column_index_from_string(column)
    fill_colors = {}
    for row_num in rows:
        cell = ws.cell(row=row_num, column=col_idx)
        fill = cell.fill
        if fill and fill.start_color:
            color_value = fill.start_color.rgb
            if color_value:
                if isinstance(color_value, str) and len(color_value) == 8:
                    color_hex = color_value[2:]
                else:
                    color_hex = color_value
                fill_colors[row_num] = color_hex
            else:
                fill_colors[row_num] = None
        else:
            fill_colors[row_num] = None
    return fill_colors

