def get_calc_filtered_rows__74db1b1a9a1ea9ac0aabaabe6de0e702(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract visible/filtered rows from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key (VM file path)

    Returns:
        Dict with row visibility information and row content
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'visible_rows': [], 'error': 'File not found'}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        visible_rows = []
        hidden_rows = []
        rows_with_ellipsis = []
        for row_idx in range(1, ws.max_row + 1):
            row_dim = ws.row_dimensions.get(row_idx)
            is_hidden = row_dim.hidden if row_dim else False
            row_contains_ellipsis = False
            for cell in ws[row_idx]:
                cell_value = str(cell.value) if cell.value is not None else ''
                if '...' in cell_value:
                    row_contains_ellipsis = True
                    break
            if row_contains_ellipsis:
                rows_with_ellipsis.append(row_idx)
            if is_hidden:
                hidden_rows.append(row_idx)
            else:
                visible_rows.append(row_idx)
        return {'visible_rows': visible_rows, 'hidden_rows': hidden_rows, 'rows_with_ellipsis': rows_with_ellipsis, 'total_rows': ws.max_row, 'hidden_count': len(hidden_rows)}
    finally:
        os.unlink(tmp_path)

