def get_xlsx_range_sorted__013f7d6f(env, config):
    """Get values from a range including header.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'start_cell', 'end_cell' keys

    Returns:
        List of values from the range (including header)
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    start_cell = config.get('start_cell')
    end_cell = config.get('end_cell')
    if not file_path or not start_cell or (not end_cell):
        return None
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return None
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        from openpyxl.utils import column_index_from_string, coordinate_from_string
        (start_col, start_row) = coordinate_from_string(start_cell)
        (end_col, end_row) = coordinate_from_string(end_cell)
        values = []
        for row in range(start_row, end_row + 1):
            value = ws[f'{start_col}{row}'].value
            if value is not None:
                values.append(str(value).strip())
            else:
                values.append('')
        import os
        os.unlink(tmp_path)
        return values
    except Exception as e:
        print(f'Error reading range: {e}')
        return None

def get_xlsx_summary_row__3bc0c835f7414ca10e6620befd37e195(env, config):
    """Extract values from summary row at the bottom of the spreadsheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Summary values including total and average
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        summary = {}
        for row in range(ws.max_row - 5, ws.max_row + 1):
            if row < 1:
                continue
            label = ws.cell(row, 2).value
            if label and isinstance(label, str):
                label_lower = label.lower()
                if 'total' in label_lower:
                    summary['total_label_row'] = row
                    summary['total'] = ws.cell(row, 3).value
                elif 'average' in label_lower or 'avg' in label_lower:
                    summary['average_label_row'] = row
                    summary['average'] = ws.cell(row, 3).value
        return summary
    finally:
        os.unlink(tmp_path)

