def get_xlsx_sheet_data__108bb387a4ac0605c7dd651f615fcae0(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract sheet cell values and merge status for verification.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with cell values and merge information
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb.sheetnames, 'data': {}}
        for sheet_name in wb.sheetnames:
            ws = wb[sheet_name]
            sheet_data = {}
            merged_cells = []
            for merged_range in ws.merged_cells.ranges:
                merged_cells.append(str(merged_range))
            for row in ws.iter_rows():
                for cell in row:
                    coord = cell.coordinate
                    is_merged = False
                    for merged_range in ws.merged_cells.ranges:
                        if cell.coordinate in merged_range:
                            is_merged = True
                            break
                    sheet_data[coord] = {'value': cell.value, 'merged': is_merged}
            result['data'][sheet_name] = {'cells': sheet_data, 'merged_ranges': merged_cells}
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_row_fill__1bd6d27f(env, config):
    """Check if a specific row has fill color.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'row', 'col_start', 'col_end'

    Returns:
        Dict with fill information for the row
    """
    path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    row = config.get('row')
    col_start = config.get('col_start', 1)
    col_end = config.get('col_end', 7)
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return None
    temp_path = f'/tmp/temp_xlsx_{os.getpid()}.xlsx'
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        wb = openpyxl.load_workbook(temp_path)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        filled_count = 0
        total_cells = col_end - col_start + 1
        for col in range(col_start, col_end + 1):
            cell = ws.cell(row, col)
            fill = cell.fill
            if fill.fill_type is not None and fill.fill_type != 'none':
                filled_count += 1
        result = {'row': row, 'filled_count': filled_count, 'total_cells': total_cells, 'has_fill': filled_count > 0}
        wb.close()
        return result
    finally:
        if os.path.exists(temp_path):
            os.remove(temp_path)

