def get_xlsx_conditional_highlights__2204acce(env, config):
    """Get cells with highlighting in a specific column.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'sheet' (0-indexed), 'column' (letter), 'start_row', 'end_row'

    Returns:
        Dict with row numbers as keys and fill info as values
    """
    file_content = env.controller.get_file(config['path'])
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        ws = wb.worksheets[config.get('sheet', 0)]
        column = config['column']
        start_row = config.get('start_row', 2)
        end_row = config.get('end_row', ws.max_row)
        highlighted_cells = {}
        for row in range(start_row, end_row + 1):
            cell_addr = f'{column}{row}'
            cell = ws[cell_addr]
            if cell.fill and cell.fill.start_color:
                if cell.fill.start_color.rgb and cell.fill.start_color.rgb not in ['00000000', '00FFFFFF', None]:
                    highlighted_cells[row] = {'has_fill': True, 'fill_color': cell.fill.start_color.rgb}
        wb.close()
        return highlighted_cells
    finally:
        os.unlink(tmp_path)

