def get_default_spreadsheet_app__08e66955(env, config: dict):
    """Gets the default application for spreadsheet files on Linux."""
    os_type = env.vm_platform
    if os_type == 'Linux':
        app = get_vm_command_line(env, {'command': ['xdg-mime', 'query', 'default', 'application/vnd.oasis.opendocument.spreadsheet']})
        if app:
            return app
        else:
            return 'unknown'
    elif os_type == 'Darwin':
        raise Exception('Unsupported operating system', os_type)
    elif os_type == 'Windows':
        raise Exception('Unsupported operating system', os_type)
    else:
        raise Exception('Unsupported operating system', os_type)

def get_xlsx_single_student_scores__64eeb07b(env, config: dict) -> Dict[str, Any]:
    """
    Extract grading data from grades.xlsx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for xlsx file path

    Returns:
        Dictionary containing student grades data
    """
    file_path = config.get('path', '/home/user/exam/grades.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'error': 'File not found'}
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        students_data = {}
        for row_idx in range(2, 12):
            student_idx = row_idx - 2
            row = list(ws[row_idx])
            student_id = row[0].value
            student_name = row[1].value
            q_scores = [row[i].value for i in range(2, 12)]
            total_grade = row[12].value
            students_data[student_idx] = {'row': row_idx, 'student_id': student_id, 'student_name': student_name, 'q_scores': q_scores, 'total_grade': total_grade}
        return {'students': students_data}
    finally:
        import os
        os.unlink(tmp_path)

