def get_xlsx_cell_value__4804f90e(env, config):
    """Get value and formula from a specific cell, plus verify other cells unchanged.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell'

    Returns:
        dict: Contains 'value', 'formula', and 'other_cells_unchanged' status
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cell_address = config.get('cell')
    file_content = env.controller.get_file(file_path)
    if not file_content:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
        if isinstance(sheet_idx, int):
            ws_data = wb_data.worksheets[sheet_idx]
            ws_formula = wb_formula.worksheets[sheet_idx]
        else:
            ws_data = wb_data[sheet_idx]
            ws_formula = wb_formula[sheet_idx]
        cell_value = ws_data[cell_address].value
        cell_formula = ws_formula[cell_address].value
        other_cells_ok = True
        expected_sales_count = 0
        for row in range(1, 31):
            cell_ref = f'E{row}'
            cell = ws_data[cell_ref]
            if cell.value is not None and isinstance(cell.value, (int, float)):
                expected_sales_count += 1
        if expected_sales_count < 20:
            other_cells_ok = False
        wb_data.close()
        wb_formula.close()
        return {'value': cell_value, 'formula': cell_formula, 'has_formula': isinstance(cell_formula, str) and cell_formula.startswith('='), 'other_cells_ok': other_cells_ok}
    finally:
        os.unlink(tmp_path)

def get_xlsx_cell_value__befae995(env, config):
    """Extract cell value and formula from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', and 'cell' keys

    Returns:
        dict: Dictionary containing 'value' and 'formula' keys
              - 'value': The calculated cell value (numeric or string)
              - 'formula': The formula string (e.g., '=AVERAGE(B2:E2)') or None if not a formula
    """
    file_path = config.get('path')
    sheet_index = config.get('sheet', 0)
    cell_address = config.get('cell', 'A1')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'value': None, 'formula': None}
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
        if isinstance(sheet_index, int):
            ws_formula = wb_formula.worksheets[sheet_index]
        else:
            ws_formula = wb_formula[sheet_index]
        cell = ws_formula[cell_address]
        formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
        wb_formula.close()
        wb_value = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_index, int):
            ws_value = wb_value.worksheets[sheet_index]
        else:
            ws_value = wb_value[sheet_index]
        cell_value = ws_value[cell_address].value
        wb_value.close()
        return {'value': cell_value, 'formula': formula}
    finally:
        os.unlink(tmp_path)

