def get_pptx_table_cell_alignment__e3cd8235b3fe58a4fca81979d09478a3(env, config):
    """Get text alignment from a specific table cell in a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (file path), 'slide_idx' (0-based),
                'shape_idx' (0-based), 'row' (0-based), 'col' (0-based)

    Returns:
        str: Alignment type ('LEFT', 'CENTER', 'RIGHT', 'JUSTIFY', etc.)
    """
    file_path = config['path']
    slide_idx = config['slide_idx']
    shape_idx = config['shape_idx']
    row = config['row']
    col = config['col']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return 'UNKNOWN'
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide = prs.slides[slide_idx]
        shape = slide.shapes[shape_idx]
        if shape.has_table:
            table = shape.table
            cell = table.rows[row].cells[col]
            text_frame = cell.text_frame
            for paragraph in text_frame.paragraphs:
                alignment = paragraph.alignment
                if alignment is None:
                    return 'LEFT'
                elif alignment == PP_ALIGN.CENTER:
                    return 'CENTER'
                elif alignment == PP_ALIGN.RIGHT:
                    return 'RIGHT'
                elif alignment == PP_ALIGN.JUSTIFY:
                    return 'JUSTIFY'
                elif alignment == PP_ALIGN.LEFT:
                    return 'LEFT'
                else:
                    return str(alignment)
        return 'UNKNOWN'
    finally:
        os.unlink(tmp_path)

