def get_xlsx_percentage_column__90edf8b6c8cfd6889713febaf1c2f1f8(env, config):
    """Extract percentage values from a specific column in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'column', 'start_row', 'end_row'

    Returns:
        dict: Maps row numbers to percentage values (e.g., {2: 11.06, 3: 9.37, ...})
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        column = config.get('column', 'H')
        start_row = config.get('start_row', 2)
        end_row = config.get('end_row', 11)
        result = {}
        for row in range(start_row, end_row + 1):
            cell_value = ws[f'{column}{row}'].value
            if cell_value is not None:
                if isinstance(cell_value, (int, float)):
                    if cell_value < 1:
                        result[row] = round(cell_value * 100, 2)
                    else:
                        result[row] = round(cell_value, 2)
        return result
    finally:
        os.unlink(tmp_path)

