def get_pptx_table_cell_text__9ad22e8c99803eec9437a675c4f427e0(env, config):
    """Extract text from a specific table cell in a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (file path), 'slide_idx' (0-based),
                'shape_idx' (0-based), 'row' (0-based), 'col' (0-based)

    Returns:
        str: The text content of the specified cell
    """
    file_path = config['path']
    slide_idx = config['slide_idx']
    shape_idx = config['shape_idx']
    row = config['row']
    col = config['col']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return ''
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide = prs.slides[slide_idx]
        shape = slide.shapes[shape_idx]
        if shape.has_table:
            table = shape.table
            cell = table.rows[row].cells[col]
            return cell.text.strip()
        return ''
    finally:
        os.unlink(tmp_path)

