def get_xlsx_row_highlight__e6ba63224a529f77bdef4ab92376c6c4(env, config):
    """Get highlighted row information from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        list: List of row indices that have cell highlighting
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        ws = wb.active
        highlighted_rows = []
        for row_idx in range(2, 12):
            has_fill = False
            for col_idx in range(1, 8):
                cell = ws.cell(row_idx, col_idx)
                if cell.fill and cell.fill.start_color and (cell.fill.start_color.index != '00000000'):
                    if cell.fill.start_color.index not in ['FFFFFFFF', 'FF000000', None]:
                        has_fill = True
                        break
            if has_fill:
                highlighted_rows.append(row_idx)
        return highlighted_rows
    finally:
        os.unlink(tmp_path)

def get_xlsx_cell_value__bc890cf5(env, config):
    """
    Get values from both D1 (header) and D2 (count) cells in the Excel file.

    This function reads both cells required by the task:
    - D1: Should contain the header "Sept 2010 Loans"
    - D2: Should contain the count of loans issued in September 2010

    Args:
        env: Environment object
        config: Configuration dict with:
            - 'path': str, path to the Excel file
            - 'sheet': int or str, sheet index or name (default: 0)
            - 'cell': str, cell coordinate (e.g., 'D2') - used as base reference

    Returns:
        dict: Dictionary with 'header' (D1 value) and 'count' (D2 value) keys
    """
    file_path = config.get('path')
    sheet_index = config.get('sheet', 0)
    with open(file_path, 'rb') as f:
        file_content = f.read()
    wb = openpyxl.load_workbook(BytesIO(file_content))
    if isinstance(sheet_index, int):
        sheet = wb.worksheets[sheet_index]
    else:
        sheet = wb[sheet_index]
    header_cell = sheet['D1']
    header_value = header_cell.value
    count_cell = sheet['D2']
    count_value = count_cell.value
    return {'header': header_value, 'count': count_value}

