def get_xlsx_cell_formula_and_value__183d0cc2efecbcc0ebc418468a9cbbfc(env, config: dict) -> dict:
    """Extract both cell formula and calculated value from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path (e.g., '/home/user/file.xlsx')
            - sheet: Sheet index (default: 0)
            - cell: Cell coordinate (e.g., 'E3')

    Returns:
        Dict with 'formula' and 'value' keys, or None if cell is empty
    """
    try:
        file_bytes = env.controller.get_file(config['path'])
        if not file_bytes:
            return None
        with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
            sheet_idx = config.get('sheet', 0)
            if isinstance(sheet_idx, int):
                ws_formula = wb_formula.worksheets[sheet_idx]
            else:
                ws_formula = wb_formula[sheet_idx]
            cell_coord = config['cell']
            cell = ws_formula[cell_coord]
            formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
            wb_value = openpyxl.load_workbook(tmp_path, data_only=True)
            if isinstance(sheet_idx, int):
                ws_value = wb_value.worksheets[sheet_idx]
            else:
                ws_value = wb_value[sheet_idx]
            cell_value = ws_value[cell_coord].value
            return {'formula': formula, 'value': cell_value}
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        print(f'Error reading cell formula and value: {e}')
        return None

