def get_xlsx_column_fill_status__14390480(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Check if cells in a column range are filled and extract their values along with lookup table.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'column', 'start_row', 'end_row'

    Returns:
        Dict with 'all_filled' (bool), 'filled_count' (int), 'values' (list), 'lookup_table' (dict)
    """
    vm_path = config.get('path', '')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return {'all_filled': False, 'filled_count': 0, 'values': [], 'lookup_table': {}}
    wb = openpyxl.load_workbook(BytesIO(file_bytes), data_only=True)
    ws = wb.active
    column = config.get('column', 'F')
    start_row = config.get('start_row', 2)
    end_row = config.get('end_row', 12)
    total_cells = end_row - start_row + 1
    filled_count = 0
    values = []
    for row in range(start_row, end_row + 1):
        cell_value = ws[f'{column}{row}'].value
        if cell_value is not None and cell_value != '':
            filled_count += 1
            values.append(str(cell_value).strip())
        else:
            values.append(None)
    lookup_table = {}
    for col_idx in range(8, 15):
        header = ws.cell(1, col_idx).value
        if header and 'office' in str(header).lower():
            office_col = col_idx
            officer_col = col_idx + 1
            for row in range(2, 20):
                office = ws.cell(row, office_col).value
                officer = ws.cell(row, officer_col).value
                if office and officer:
                    lookup_table[str(office).strip()] = str(officer).strip()
            break
    head_offices = []
    for row in range(start_row, end_row + 1):
        head_office = ws.cell(row, 5).value
        if head_office:
            head_offices.append(str(head_office).strip())
        else:
            head_offices.append(None)
    return {'all_filled': filled_count == total_cells, 'filled_count': filled_count, 'total_cells': total_cells, 'values': values, 'head_offices': head_offices, 'lookup_table': lookup_table}

def get_xlsx_complete_rows_count__b83d67e9(env, config: Dict[str, Any]) -> int:
    """Count rows that have all required columns filled.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'required_columns' keys

    Returns:
        Number of rows with all required columns filled
    """
    file_path = config.get('path', '/home/user/Desktop/MUST_VISIT.xlsx')
    required_columns = config.get('required_columns', [1, 2, 3, 4])
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return 0
    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)
    ws = wb.active
    complete_count = 0
    for row in range(2, 20):
        all_filled = True
        for col in required_columns:
            cell_value = ws.cell(row=row, column=col).value
            if not cell_value or not str(cell_value).strip():
                all_filled = False
                break
        if all_filled:
            complete_count += 1
    return complete_count

