def get_xlsx_total_grades_sum__1b384d15a01e0f0bb5447f5c8d07808e(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Extract comprehensive grading data from the grades spreadsheet.

    This getter extracts:
    1. Individual student scores (total grade for each student)
    2. Individual question marks (1/0 values for each question)
    3. Total sum of all grades

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict containing:
        - student_scores: List of total scores for each student
        - question_marks: List of lists containing 1/0 marks for each student's questions
        - total_sum: Sum of all student scores
        Returns None if file not found
    """
    file_path = config.get('path')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        student_scores = []
        question_marks = []
        total_sum = 0
        for row in range(2, 12):
            total_grade = ws.cell(row=row, column=13).value
            if total_grade is not None and isinstance(total_grade, (int, float)):
                student_scores.append(int(total_grade))
                total_sum += int(total_grade)
            else:
                student_scores.append(None)
            marks = []
            for col in range(3, 13):
                mark = ws.cell(row=row, column=col).value
                if mark is not None:
                    if isinstance(mark, (int, float)):
                        marks.append(int(mark))
                    else:
                        marks.append(None)
                else:
                    marks.append(None)
            question_marks.append(marks)
        wb.close()
        return {'student_scores': student_scores, 'question_marks': question_marks, 'total_sum': total_sum}
    finally:
        os.unlink(tmp_path)

