def get_xlsx_row_count__124ca0da(env, config: Dict[str, Any]) -> int:
    """Get the number of non-empty rows in a specific column of an XLSX file."""
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'A')
    try:
        wb = openpyxl.load_workbook(file_path, data_only=True)
        if sheet_idx >= len(wb.sheetnames):
            return 0
        ws = wb[wb.sheetnames[sheet_idx]]
        count = 0
        for row_idx in range(2, ws.max_row + 1):
            cell_value = ws[f'{column}{row_idx}'].value
            if cell_value is not None and str(cell_value).strip():
                count += 1
        return count
    except Exception:
        return 0

