def get_xlsx_cell_value__fc0f9c2c6ff0c22170e2698a066c508a(env, config: dict):
    """Extract a cell value and formula from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM path to Excel file),
                'sheet' (sheet index, default 0), and 'cell' (cell address like 'B6')

    Returns:
        dict: {'value': cell_value, 'formula': formula_string, 'data_type': type}
              Returns None if file cannot be read
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cell_addr = config.get('cell')
    if not file_path or not cell_addr:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell = ws[cell_addr]
        formula = cell.value if cell.data_type == 'f' else None
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws_data = wb_data.worksheets[sheet_idx]
        else:
            ws_data = wb_data[sheet_idx]
        cell_data = ws_data[cell_addr]
        calculated_value = cell_data.value
        return {'value': calculated_value, 'formula': formula, 'data_type': cell.data_type}
    except Exception as e:
        print(f'Error reading Excel cell: {e}')
        return None
    finally:
        os.unlink(tmp_path)

def get_xlsx_column_range__2c840a52(env, config):
    """Get values from a specific column range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column', 'start_row', 'end_row'

    Returns:
        List of cell values in the specified range
    """
    vm_path = config.get('path', '/home/user/Desktop/Professor_Contact.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return []
    import os
    local_path = os.path.join(env.cache_dir, 'temp_prof_contact_v2.xlsx')
    with open(local_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(local_path, data_only=True)
    sheet_idx = config.get('sheet', 0)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    column = config.get('column', 'G')
    start_row = config.get('start_row', 1)
    end_row = config.get('end_row', ws.max_row)
    from openpyxl.utils import column_index_from_string
    col_idx = column_index_from_string(column)
    values = []
    for row in range(start_row, end_row + 1):
        cell_value = ws.cell(row=row, column=col_idx).value
        values.append(cell_value)
    return values

