def get_pptx_table_cell__609a65b9(env, config):
    """Get text from a specific table cell in a PowerPoint slide."""
    pptx_path = config.get('pptx_path')
    slide_index = int(config.get('slide_index', 0))
    shape_index = int(config.get('shape_index', 0))
    row = int(config.get('row', 0))
    col = int(config.get('col', 0))
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if slide_index >= len(prs.slides):
        return ''
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return ''
    shape = slide.shapes[shape_index]
    if shape.shape_type != 19:
        return ''
    table = shape.table
    if row >= len(table.rows) or col >= len(table.columns):
        return ''
    return table.cell(row, col).text.strip()

def get_xlsx_cell_fill__5a496d19(env, config):
    """Get the fill color of a specific cell in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell'

    Returns:
        dict with 'has_fill' and 'color' keys
    """
    file_path = config['path']
    sheet_idx = config.get('sheet', 0)
    cell_addr = config['cell']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'has_fill': False, 'color': None}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell = ws[cell_addr]
        fill = cell.fill
        has_fill = False
        color = None
        if fill and fill.start_color:
            if fill.start_color.rgb and fill.start_color.rgb not in ['00000000', 'FFFFFFFF', None]:
                has_fill = True
                color = fill.start_color.rgb
        wb.close()
        return {'has_fill': has_fill, 'color': color}
    finally:
        os.unlink(tmp_path)

def get_xlsx_specific_cells__b370fea70cf295c591577ca89f2f7c89(env, config: dict):
    """Extract values from specific cells in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cells' (list of cell refs like ['B3', 'C8'])

    Returns:
        dict: Mapping of cell coordinates to values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[config['sheet']]
        result = {}
        cells = config['cells']
        for cell_ref in cells:
            cell_value = ws[cell_ref].value
            result[cell_ref] = cell_value
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_author_names__bdc4201fedfbbb54ee0625123608b59b(env, config: Dict[str, Any]) -> List[str]:
    """Extract author names from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        List of author names as strings
    """
    file_path = config.get('path', '')
    if not file_path:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        names = []
        for (row_idx, row) in enumerate(ws.iter_rows(min_row=1, values_only=True), start=1):
            if row_idx == 1:
                if row and isinstance(row[0], str) and ('name' in str(row[0]).lower()):
                    continue
            if row and row[0] is not None:
                name = str(row[0]).strip()
                if name:
                    names.append(name)
        return names
    finally:
        os.unlink(tmp_path)

