def get_xlsx_multi_column_data__4da6f9d04fdaf419bddbc69359d26021(env, config: dict) -> List[Dict[str, Any]]:
    """Get data from multiple columns in an Excel sheet as a list of row dictionaries.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'columns' (dict mapping column letter to key name), and optional 'start_row' keys

    Returns:
        List[Dict[str, Any]]: List of dictionaries containing data from each row
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        columns = config.get('columns', {'A': 'title', 'B': 'url', 'C': 'date'})
        start_row = config.get('start_row', 2)
        rows_data = []
        for row_idx in range(start_row, ws.max_row + 1):
            row_dict = {}
            has_data = False
            for (col_letter, col_key) in columns.items():
                cell = ws[f'{col_letter}{row_idx}']
                value = cell.value
                if value is not None and str(value).strip():
                    row_dict[col_key] = value
                    has_data = True
                else:
                    row_dict[col_key] = None
            if has_data:
                rows_data.append(row_dict)
        return rows_data
    finally:
        os.unlink(tmp_path)

