def get_xlsx_multiple_cells_fill__013f7d6f(env, config):
    """Get fill info for multiple cells.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', and 'cells' keys

    Returns:
        Dict mapping cell addresses to fill info
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cells = config.get('cells', [])
    if not file_path or not cells:
        return None
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return None
        import tempfile
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        wb = openpyxl.load_workbook(tmp_path)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        result = {}
        for cell_addr in cells:
            cell = ws[cell_addr]
            fill = cell.fill
            has_fill = fill and fill.start_color and fill.start_color.rgb and (fill.start_color.rgb != '00000000')
            result[cell_addr] = {'has_fill': has_fill, 'color': fill.start_color.rgb if has_fill else None}
        import os
        os.unlink(tmp_path)
        return result
    except Exception as e:
        print(f'Error reading cell fills: {e}')
        return None

def get_xlsx_row_fill_color__64c5f3ec5c2ddf4604f78b4505d5cd68(env, config: Dict[str, Any]):
    """Extract fill color information for cells in a specific row.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (0-indexed), and 'row' (1-indexed)

    Returns:
        Dict mapping column letters to fill colors (or None if no fill)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        row_num = config['row']
        fill_colors = {}
        for cell in ws[row_num]:
            col_letter = cell.column_letter
            fill = cell.fill
            if fill and fill.start_color and fill.start_color.rgb:
                rgb = fill.start_color.rgb
                if isinstance(rgb, str) and len(rgb) == 8:
                    rgb = rgb[2:]
                fill_colors[col_letter] = rgb
            else:
                fill_colors[col_letter] = None
        return fill_colors
    finally:
        os.unlink(tmp_path)

