def get_calc_pivot_data__aec249c5da95a40917cfa74665da9b60(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract data from both Sheet1 (Discount Amount column) and Sheet2 (pivot table).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict containing:
            - sheet1_data: Header row and sample data rows from Sheet1
            - has_discount_column: Whether 'Discount Amount' column exists
            - discount_column_index: Index of Discount Amount column (if exists)
            - sample_discount_values: Sample calculated discount values for verification
            - has_sheet2: Whether Sheet2 exists
            - pivot_data: All data from Sheet2 (pivot table)
            - pivot_headers: Headers from pivot table (first row)
            - pivot_values: Data values from pivot table
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb.sheetnames, 'has_sheet2': 'Sheet2' in wb.sheetnames}
        sheet1_name = wb.sheetnames[0] if wb.sheetnames else None
        if sheet1_name:
            ws1 = wb[sheet1_name]
            header_row = []
            if ws1.max_row >= 1:
                header_row = [cell for cell in next(ws1.iter_rows(min_row=1, max_row=1, values_only=True))]
            result['sheet1_headers'] = header_row
            discount_col_idx = None
            for (idx, header) in enumerate(header_row):
                if header and 'discount amount' in str(header).lower():
                    discount_col_idx = idx
                    break
            result['has_discount_column'] = discount_col_idx is not None
            result['discount_column_index'] = discount_col_idx
            sample_rows = []
            for (row_idx, row) in enumerate(ws1.iter_rows(min_row=2, max_row=min(10, ws1.max_row), values_only=True), start=2):
                row_data = list(row)
                if any((cell is not None for cell in row_data)):
                    sample_rows.append({'row_num': row_idx, 'data': row_data})
            result['sheet1_sample_rows'] = sample_rows
            all_rows = []
            for row in ws1.iter_rows(min_row=2, max_row=ws1.max_row, values_only=True):
                row_data = list(row)
                if any((cell is not None for cell in row_data)):
                    all_rows.append(row_data)
            result['sheet1_all_data'] = all_rows
        if 'Sheet2' in wb.sheetnames:
            ws2 = wb['Sheet2']
            pivot_data = []
            for row in ws2.iter_rows(min_row=1, max_row=ws2.max_row, values_only=True):
                if any((cell is not None for cell in row)):
                    pivot_data.append(list(row))
            result['pivot_data'] = pivot_data
            result['pivot_max_row'] = ws2.max_row
            result['pivot_max_col'] = ws2.max_column
            if pivot_data:
                result['pivot_headers'] = pivot_data[0] if len(pivot_data) > 0 else []
                result['pivot_values'] = pivot_data[1:] if len(pivot_data) > 1 else []
        else:
            result['pivot_data'] = []
            result['pivot_headers'] = []
            result['pivot_values'] = []
        return result
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

