def get_xlsx_quarterly_totals__d05ab48ac420c4cb506bbc5272ef2448(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract quarterly total values from new columns added by the agent for all sales reps.

    This getter reads an Excel file and extracts Q1 and Q2 totals that should be
    calculated and added by the agent for each sales rep row.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file on VM
            - sheet: Sheet index (default 0)
            - q1_column: Column letter for Q1 totals (e.g., "H")
            - q2_column: Column letter for Q2 totals (e.g., "I")

    Returns:
        Dict containing:
            - headers: dict with 'q1_header' and 'q2_header' (values from row 1)
            - reps: list of dicts, each containing {'row': int, 'q1': value, 'q2': value}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'headers': {'q1_header': None, 'q2_header': None}, 'reps': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        q1_column = config.get('q1_column', 'H')
        q2_column = config.get('q2_column', 'I')
        q1_header = ws[f'{q1_column}1'].value
        q2_header = ws[f'{q2_column}1'].value
        reps = []
        for row_idx in range(2, ws.max_row + 1):
            first_cell_value = ws[f'A{row_idx}'].value
            if first_cell_value is None or str(first_cell_value).strip() == '':
                break
            q1_cell = f'{q1_column}{row_idx}'
            q2_cell = f'{q2_column}{row_idx}'
            q1_value = ws[q1_cell].value
            q2_value = ws[q2_cell].value
            if q1_value is not None:
                try:
                    q1_value = int(q1_value) if isinstance(q1_value, (int, float)) and q1_value == int(q1_value) else float(q1_value)
                except (ValueError, TypeError):
                    pass
            if q2_value is not None:
                try:
                    q2_value = int(q2_value) if isinstance(q2_value, (int, float)) and q2_value == int(q2_value) else float(q2_value)
                except (ValueError, TypeError):
                    pass
            reps.append({'row': row_idx, 'q1': q1_value, 'q2': q2_value})
        return {'headers': {'q1_header': q1_header, 'q2_header': q2_header}, 'reps': reps}
    finally:
        os.unlink(tmp_path)

