def get_xlsx_cell_value__735eae74(env, config):
    """Get the value of a specific cell in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', and 'cell' parameters

    Returns:
        The cell value (can be number, string, None, etc.)
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cell_addr = config.get('cell')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell_value = ws[cell_addr].value
        wb.close()
        return cell_value
    finally:
        import os
        os.unlink(tmp_path)

def get_xlsx_range_has_borders__f1bf5b23(env, config):
    """Check if all cells in a range have borders.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'file_path', 'sheet', 'range'

    Returns:
        bool: True if all cells have borders, False otherwise
    """
    file_path = config.get('file_path')
    sheet_idx = config.get('sheet', 0)
    cell_range = config.get('range', 'A1:D2')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return False
    import os
    cache_path = os.path.join(env.cache_dir, os.path.basename(file_path))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    for row in ws[cell_range]:
        for cell in row:
            if not cell.border:
                return False
            has_border = cell.border.left and cell.border.left.style or (cell.border.right and cell.border.right.style) or (cell.border.top and cell.border.top.style) or (cell.border.bottom and cell.border.bottom.style)
            if not has_border:
                return False
    return True

