def get_xlsx_cell_text__b7b6715e(env, config: Dict[str, Any]) -> str:
    """Read cell text content from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file on VM
            - cell: Cell address (e.g., "D1")

    Returns:
        str: The text content of the cell (empty string if cell is empty or file not found)
    """
    file_path = config.get('path')
    cell_addr = config.get('cell')
    if not file_path or not cell_addr:
        return ''
    try:
        wb = openpyxl.load_workbook(file_path)
        ws = wb.active
        cell = ws[cell_addr]
        cell_value = cell.value
        wb.close()
        if cell_value is None:
            return ''
        return str(cell_value)
    except Exception as e:
        print(f'Error reading cell {cell_addr} from {file_path}: {e}')
        return ''

