def get_xlsx_filenames_list__1051f25b(env, config: Dict[str, Any]) -> List[str]:
    """
    Extract list of filenames from column A of an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        List of filenames from column A (excluding header)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    import os
    cache_path = os.path.join(env.cache_dir, config.get('dest', 'temp.xlsx'))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    ws = wb.active
    filenames = []
    for row in range(2, ws.max_row + 1):
        cell_value = ws.cell(row=row, column=1).value
        if cell_value:
            filenames.append(str(cell_value))
    return filenames

