def get_xlsx_hundreds_format__8e497b5a0beafdffc802099c3c20ed86(env, config):
    """Extract formatted cell display values from column B to verify hundreds (H) formatting.

    This getter extracts the displayed formatted values as they appear to the user,
    by reading the custom number format and applying it to the raw numeric values.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary mapping cell addresses to their formatted string values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        ws = wb.active
        result = {}
        for row in range(2, 9):
            cell_addr = f'B{row}'
            cell = ws[cell_addr]
            cell_value = cell.value
            number_format = cell.number_format
            if cell_value is not None:
                if number_format and ('H' in number_format or 'h' in number_format):
                    try:
                        num_value = float(cell_value) / 100
                        formatted = f'{num_value:.1f} H'
                        result[cell_addr] = formatted
                    except (ValueError, TypeError):
                        result[cell_addr] = str(cell_value)
                else:
                    result[cell_addr] = str(cell_value)
            else:
                result[cell_addr] = None
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_excellent_employees__04cdc444e11217abeb87589df5b31611(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract all employee data including all columns from the result Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for Excel file

    Returns:
        Dict with structure: {
            'employees': {employee_name: {column_name: value, ...}},
            'columns': [list of column names],
            'file_exists': bool
        }
    """
    file_path = config.get('path', '/home/user/Desktop/top_performers.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'employees': {}, 'columns': [], 'file_exists': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        headers = []
        for cell in ws[1]:
            if cell.value is not None:
                headers.append(cell.value)
            else:
                break
        employees = {}
        for row_idx in range(2, ws.max_row + 1):
            row = ws[row_idx]
            employee_name = row[0].value
            if employee_name is None:
                continue
            employee_data = {}
            for (col_idx, header) in enumerate(headers):
                cell_value = row[col_idx].value
                employee_data[header] = cell_value
            employees[employee_name] = employee_data
        return {'employees': employees, 'columns': headers, 'file_exists': True}
    finally:
        os.unlink(tmp_path)

def get_xlsx_total_assets__c050354ae7cacb1abe433e5885602a49(env, config: Dict[str, Any]) -> Dict[int, float]:
    """Extract total assets for each year from Sheet2.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict mapping year to total assets value
    """
    file_path = config.get('path', '/home/user/SmallBalanceSheet.xlsx')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if len(wb.sheetnames) < 2:
            return {}
        ws = wb.worksheets[1]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row and len(row) >= 2:
                year = row[0]
                total_assets = row[1]
                if year is not None and total_assets is not None:
                    try:
                        result[int(year)] = float(total_assets)
                    except (ValueError, TypeError):
                        continue
        return result
    finally:
        os.unlink(tmp_path)

