def get_xlsx_grf_table__d24a6b5d9bcf09db9cd5a9cf07143d27(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract GRF table data from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with table data (years extracted from the table)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'years': [], 'row_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        years = []
        for row_idx in range(2, ws.max_row + 1):
            year_cell = ws.cell(row_idx, 1).value
            if year_cell is not None:
                try:
                    year_val = int(year_cell)
                    if year_val >= 2000:
                        year_val = year_val - 2000
                    years.append(year_val)
                except (ValueError, TypeError):
                    year_str = str(year_cell).strip()
                    import re
                    match = re.search('(\\d{2,4})', year_str)
                    if match:
                        year_val = int(match.group(1))
                        if year_val >= 2000:
                            year_val = year_val - 2000
                        years.append(year_val)
        return {'years': years, 'row_count': len(years)}
    finally:
        os.unlink(tmp_path)

