def get_xlsx_cell_fill_color__8e3a2fa78634d2bf6a0642aea30140d7(env, config: dict) -> Dict[str, Any]:
    """Extract fill color information for a specific cell.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'cell' keys

    Returns:
        Dict with 'has_fill' and 'color' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_fill': False, 'color': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        ws = wb.active
        cell = config.get('cell', 'A1')
        cell_obj = ws[cell]
        fill = cell_obj.fill
        has_fill = fill is not None and fill.start_color is not None and (fill.start_color.rgb is not None)
        color = None
        if has_fill:
            rgb = fill.start_color.rgb
            if rgb and len(rgb) >= 6:
                if len(rgb) == 8:
                    color = rgb[2:]
                else:
                    color = rgb
        return {'has_fill': has_fill, 'color': color}
    finally:
        os.unlink(tmp_path)

def get_xlsx_data__26a0e22c(env, config: Dict[str, Any]) -> Union[List, Dict]:
    """Extract data from Excel file."""
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    import os
    cache_path = os.path.join(env.cache_dir, config.get('dest', 'temp.xlsx'))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    ws = wb.active
