def get_xlsx_basic_inventory__57af7e9cd5698f93d5a1d771357a91a5(env, config):
    """
    Extract basic inventory data from a LibreOffice Calc .xlsx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the .xlsx file on VM

    Returns:
        dict: Dictionary containing sheet name and first row data
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'exists': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        sheet_name = wb.sheetnames[0] if wb.sheetnames else None
        first_row = []
        if ws.max_row >= 1:
            for col in range(1, 4):
                cell_value = ws.cell(row=1, column=col).value
                first_row.append(cell_value)
        wb.close()
        return {'exists': True, 'sheet_name': sheet_name, 'first_row': first_row, 'has_data': any((cell is not None for cell in first_row))}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

