def get_pptx_table_cell__05bf41d7(env, config):
    """Get text from a specific table cell in a PowerPoint slide."""
    pptx_path = config.get('pptx_path')
    slide_index = int(config.get('slide_index', 0))
    shape_index = int(config.get('shape_index', 0))
    row = int(config.get('row', 0))
    col = int(config.get('col', 0))
    local_path = get_vm_file(env, {'path': pptx_path, 'dest': os.path.basename(pptx_path)})
    prs = Presentation(local_path)
    if slide_index >= len(prs.slides):
        return ''
    slide = prs.slides[slide_index]
    if shape_index >= len(slide.shapes):
        return ''
    shape = slide.shapes[shape_index]
    if shape.shape_type != 19:
        return ''
    table = shape.table
    if row >= len(table.rows) or col >= len(table.columns):
        return ''
    return table.cell(row, col).text.strip()

def get_xlsx_author_lists__48531793(env, config: Dict[str, Any]) -> List[Dict[str, str]]:
    """
    Extract paper information from Excel file including title, year, authors, and PDF link.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file
            - sheet: Sheet index (0-based)
            - column: Column letter containing authors (e.g., 'C')
            - start_row: First data row (1-based, default: 2)

    Returns:
        List of dicts with keys: 'title', 'year', 'authors', 'pdf_link'
    """
    path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    start_row = config.get('start_row', 2)
    import os
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return []
    cache_path = os.path.join(env.cache_dir, os.path.basename(path))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    ws = wb.worksheets[sheet_idx]
    papers = []
    for row_idx in range(start_row, ws.max_row + 1):
        title_val = ws[f'A{row_idx}'].value
        year_val = ws[f'B{row_idx}'].value
        authors_val = ws[f'C{row_idx}'].value
        link_val = ws[f'D{row_idx}'].value
        if all((v is None or str(v).strip() == '' for v in [title_val, year_val, authors_val, link_val])):
            continue
        papers.append({'title': str(title_val).strip() if title_val is not None else '', 'year': str(year_val).strip() if year_val is not None else '', 'authors': str(authors_val).strip() if authors_val is not None else '', 'pdf_link': str(link_val).strip() if link_val is not None else ''})
    wb.close()
    return papers

