def get_xlsx_highest_score__7fa3947afebe1c5a8c68bb99c7f09579(env, config: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """
    Extract comprehensive grading data including individual question scores,
    total scores, and highest score for all students.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict with student grading data and highest score, or None if file not found
        Format: {
            'students': [
                {
                    'name': 'Student Name',
                    'question_scores': [0/1, 0/1, ...],  # 10 questions
                    'total_score': int,
                    'total_calculated': int  # sum of question_scores
                },
                ...
            ],
            'highest_score': int,
            'all_students_graded': bool
        }
    """
    file_path = config.get('path')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        students = []
        max_grade = None
        all_graded = True
        for row in range(2, 12):
            name_cell = ws.cell(row=row, column=1).value
            student_name = str(name_cell) if name_cell else f'Student_{row - 1}'
            question_scores = []
            for col in range(3, 13):
                cell_value = ws.cell(row=row, column=col).value
                if cell_value is not None and isinstance(cell_value, (int, float)):
                    question_scores.append(int(cell_value))
                else:
                    question_scores.append(None)
                    all_graded = False
            total_cell = ws.cell(row=row, column=13).value
            total_score = int(total_cell) if total_cell is not None and isinstance(total_cell, (int, float)) else None
            if total_score is None:
                all_graded = False
            total_calculated = sum((score for score in question_scores if score is not None))
            students.append({'name': student_name, 'question_scores': question_scores, 'total_score': total_score, 'total_calculated': total_calculated})
            if total_score is not None:
                if max_grade is None or total_score > max_grade:
                    max_grade = total_score
        wb.close()
        return {'students': students, 'highest_score': max_grade, 'all_students_graded': all_graded}
    finally:
        os.unlink(tmp_path)

