def get_calc_chart_info__1ee73704d4e6cf596e2796aeb3e217f2(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract chart information from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key (VM file path)

    Returns:
        Dict with chart information from the specified sheet
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        import openpyxl
        from openpyxl.chart import LineChart, BarChart, PieChart, AreaChart, ScatterChart
        wb = openpyxl.load_workbook(tmp_path)
        chart_info = []
        for (sheet_idx, sheet_name) in enumerate(wb.sheetnames):
            ws = wb[sheet_name]
            if hasattr(ws, '_charts') and ws._charts:
                for (chart_idx, chart) in enumerate(ws._charts):
                    chart_type = type(chart).__name__
                    chart_title = chart.title if hasattr(chart, 'title') and chart.title else ''
                    data_series = []
                    if hasattr(chart, 'series') and chart.series:
                        for series in chart.series:
                            series_info = {}
                            if hasattr(series, 'xVal') and series.xVal:
                                if hasattr(series.xVal, 'numRef') and series.xVal.numRef:
                                    series_info['x_range'] = series.xVal.numRef.f if hasattr(series.xVal.numRef, 'f') else None
                            if hasattr(series, 'yVal') and series.yVal:
                                if hasattr(series.yVal, 'numRef') and series.yVal.numRef:
                                    series_info['y_range'] = series.yVal.numRef.f if hasattr(series.yVal.numRef, 'f') else None
                            if 'x_range' in series_info or 'y_range' in series_info:
                                x_col = None
                                y_col = None
                                if 'x_range' in series_info and series_info['x_range']:
                                    x_range = series_info['x_range']
                                    if '$' in x_range:
                                        parts = x_range.split('$')
                                        if len(parts) >= 2:
                                            x_col = parts[1][0]
                                if 'y_range' in series_info and series_info['y_range']:
                                    y_range = series_info['y_range']
                                    if '$' in y_range:
                                        parts = y_range.split('$')
                                        if len(parts) >= 2:
                                            y_col = parts[1][0]
                                series_info['x_column'] = x_col
                                series_info['y_column'] = y_col
                                if 'x_range' in series_info and series_info['x_range']:
                                    x_range = series_info['x_range']
                                    if ':' in x_range:
                                        parts = x_range.split(':')
                                        if len(parts) == 2:
                                            try:
                                                start_row = int(parts[0].split('$')[-1])
                                                end_row = int(parts[1].split('$')[-1])
                                                series_info['data_point_count'] = end_row - start_row + 1
                                            except (ValueError, IndexError):
                                                pass
                            if series_info:
                                data_series.append(series_info)
                    chart_info.append({'sheet_index': sheet_idx, 'sheet_name': sheet_name, 'chart_index': chart_idx, 'chart_type': chart_type, 'chart_title': chart_title, 'data_series': data_series})
        return {'charts': chart_info, 'total_charts': len(chart_info)}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

def get_xlsx_number_format__2a5c76db(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract number formatting from cells in a column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet', 'column', 'start_row', 'end_row'

    Returns:
        Dict with formatting info: {"formats": [...], "all_percentage": bool, "all_no_decimals": bool}
    """
    from desktop_env.evaluators.getters import file as file_getters
    local_path = file_getters.get_vm_file(env, config)
    wb = openpyxl.load_workbook(local_path)
    sheet_idx = config.get('sheet', 0)
    ws = wb.worksheets[sheet_idx]
    column = config.get('column', 'C')
    if isinstance(column, str):
        col_idx = openpyxl.utils.column_index_from_string(column)
    else:
        col_idx = column
    start_row = config.get('start_row', 2)
    end_row = config.get('end_row', ws.max_row)
    formats = []
    for row in range(start_row, end_row + 1):
        cell = ws.cell(row, col_idx)
        fmt = cell.number_format
        formats.append(fmt)
    wb.close()
    all_percentage = all(('%' in str(fmt) for fmt in formats)) if formats else False
    all_no_decimals = True
    for fmt in formats:
        fmt_str = str(fmt)
        if '%' in fmt_str:
            if '.' in fmt_str:
                all_no_decimals = False
                break
        else:
            all_no_decimals = False
            break
    return {'formats': formats, 'all_percentage': all_percentage, 'all_no_decimals': all_no_decimals}

def get_xlsx_percentage_format__71d7a7e674f4d2619d09b1f1e82d6b2b(env, config):
    """Extract period rate values and check percentage formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the xlsx file

    Returns:
        dict: Contains values and formatting info
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        period_rate_col = None
        annual_rate_col = None
        period_per_year_col = None
        for col in range(1, ws.max_column + 1):
            header_cell = ws.cell(1, col)
            header_value = str(header_cell.value).strip().lower() if header_cell.value else ''
            if 'period rate' in header_value and '%' in header_value:
                period_rate_col = col
            elif 'annual rate' in header_value:
                annual_rate_col = col
            elif 'period' in header_value and ('per year' in header_value or 'year' in header_value):
                period_per_year_col = col
        if period_rate_col is None:
            return {'has_column_header': False, 'period_rate_data': [], 'has_percentage_format': False, 'percentage_format_count': 0, 'decimal_2_count': 0, 'total_checked': 0, 'calculation_correct_count': 0}
        period_rate_data = []
        has_percentage_format = False
        calculation_correct_count = 0
        max_row_to_check = min(26, ws.max_row + 1)
        for row in range(2, max_row_to_check):
            cell = ws.cell(row, period_rate_col)
            cell_value = cell.value
            if cell_value is None:
                continue
            if isinstance(cell_value, (int, float)):
                number_format = cell.number_format if cell.number_format else ''
                is_percentage = '%' in number_format
                if is_percentage:
                    has_percentage_format = True
                decimal_places = None
                if '0.00' in number_format:
                    decimal_places = 2
                elif '0.0' in number_format:
                    decimal_places = 1
                elif number_format and '%' in number_format:
                    if '.00' in number_format or '0.00%' in number_format:
                        decimal_places = 2
                calculation_correct = False
                if annual_rate_col and period_per_year_col:
                    annual_rate_cell = ws.cell(row, annual_rate_col)
                    period_per_year_cell = ws.cell(row, period_per_year_col)
                    annual_rate = annual_rate_cell.value
                    period_per_year = period_per_year_cell.value
                    if annual_rate is not None and period_per_year is not None:
                        if isinstance(annual_rate, (int, float)) and isinstance(period_per_year, (int, float)) and (period_per_year != 0):
                            expected_period_rate = annual_rate / period_per_year
                            if abs(cell_value - expected_period_rate) < 0.0001:
                                calculation_correct = True
                                calculation_correct_count += 1
                period_rate_data.append({'row': row, 'value': cell_value, 'format': number_format, 'is_percentage': is_percentage, 'decimal_places': decimal_places, 'calculation_correct': calculation_correct})
        percentage_count = sum((1 for d in period_rate_data if d['is_percentage']))
        decimal_2_count = sum((1 for d in period_rate_data if d['decimal_places'] == 2))
        result = {'has_column_header': True, 'period_rate_data': period_rate_data, 'has_percentage_format': has_percentage_format, 'percentage_format_count': percentage_count, 'decimal_2_count': decimal_2_count, 'total_checked': len(period_rate_data), 'calculation_correct_count': calculation_correct_count}
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

