def get_xlsx_cell_format__6ee6d458e409442b96beecf7c09168ca(env, config):
    """
    Extract formatting information from a specific cell in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM path to Excel file
            - sheet: Sheet index (0-based) or name
            - cell: Cell reference (e.g., "C13")

    Returns:
        dict: Formatting information including:
            - has_fill: bool - whether cell has background fill
            - fill_color: str - hex color code (e.g., "FFFFFF00" for yellow)
            - is_bold: bool - whether text is bold
            - cell_value: value in the cell
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet_ref = config.get('sheet', 0)
        if isinstance(sheet_ref, int):
            ws = wb.worksheets[sheet_ref]
        else:
            ws = wb[sheet_ref]
        cell_ref = config['cell']
        cell = ws[cell_ref]
        result = {'cell_value': cell.value, 'has_fill': False, 'fill_color': None, 'is_bold': False}
        if cell.fill and cell.fill.patternType:
            result['has_fill'] = True
            if cell.fill.fgColor and hasattr(cell.fill.fgColor, 'rgb'):
                result['fill_color'] = str(cell.fill.fgColor.rgb)
        if cell.font and cell.font.bold:
            result['is_bold'] = True
        return result
    finally:
        os.unlink(tmp_path)

def get_calc_sorted_and_highlighted__5067a7c4cecc12f77912546bd530380f(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract sorted data and cell formatting information.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM file path
            - sheet: Sheet name or index
            - sort_column: Column letter that data should be sorted by
            - check_cells: List of cell addresses to check for highlighting

    Returns:
        Dict with sorted_values (list of values in sort column),
        highlighted_cells (list of cells that have yellow fill color),
        row_data (dict mapping row numbers to their data for integrity check),
        reference_relationships (list of tuples preserving original name->civil_status mappings),
        and expected_highlighted_cells (list of all cells in row 2 that should be highlighted)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'sorted_values': [], 'highlighted_cells': [], 'row_data': {}, 'reference_relationships': [], 'expected_highlighted_cells': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        sheet = config.get('sheet', 0)
        if isinstance(sheet, int):
            ws = wb.worksheets[sheet]
        else:
            ws = wb[sheet]
        sort_column = config.get('sort_column', 'A')
        sorted_values = []
        row_data = {}
        reference_relationships = []
        for i in range(2, ws.max_row + 1):
            cell_value = ws[f'{sort_column}{i}'].value
            if cell_value is None:
                break
            sorted_values.append(cell_value)
            row_dict = {}
            for col_idx in range(1, ws.max_column + 1):
                col_letter = openpyxl.utils.get_column_letter(col_idx)
                row_dict[col_letter] = ws[f'{col_letter}{i}'].value
            row_data[i] = row_dict
            name = ws[f'A{i}'].value
            civil_status = ws[f'C{i}'].value
            if name is not None and civil_status is not None:
                reference_relationships.append((name, civil_status))
        highlighted_cells = []
        expected_highlighted_cells = []
        for col_idx in range(1, ws.max_column + 1):
            col_letter = openpyxl.utils.get_column_letter(col_idx)
            cell_addr = f'{col_letter}2'
            expected_highlighted_cells.append(cell_addr)
            cell = ws[cell_addr]
            if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
                rgb = cell.fill.start_color.rgb
                if rgb and isinstance(rgb, str) and (len(rgb) >= 6):
                    if len(rgb) == 8:
                        (r, g, b) = (rgb[2:4], rgb[4:6], rgb[6:8])
                    else:
                        (r, g, b) = (rgb[0:2], rgb[2:4], rgb[4:6])
                    try:
                        r_val = int(r, 16)
                        g_val = int(g, 16)
                        b_val = int(b, 16)
                        if r_val > 200 and g_val > 200 and (b_val < 100):
                            highlighted_cells.append(cell_addr)
                    except ValueError:
                        pass
        return {'sorted_values': sorted_values, 'highlighted_cells': highlighted_cells, 'row_data': row_data, 'reference_relationships': reference_relationships, 'expected_highlighted_cells': expected_highlighted_cells}
    finally:
        os.unlink(tmp_path)

