def get_xlsx_formula_copy_data__e2c5c870a1170f084c5b2756efd90641(env, config: dict):
    """Extract data to verify formula copying in columns B and D, and average in D31.

    Verifies that:
    1. Column B has values in rows 2-30 (formulas were copied)
    2. Column D has values in rows 2-30 (formulas were copied)
    3. Cell D31 contains the average value

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'sheet'

    Returns:
        dict: Data structure with column B count, column D count, and D31 value
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[config.get('sheet', 0)]
        col_b_count = 0
        for row in range(2, 31):
            cell_value = ws[f'B{row}'].value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                col_b_count += 1
        col_d_count = 0
        for row in range(2, 31):
            cell_value = ws[f'D{row}'].value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                col_d_count += 1
        d31_value = ws['D31'].value
        if d31_value is not None and isinstance(d31_value, (int, float)):
            d31_value = round(d31_value, 6)
        return {'col_b_count': col_b_count, 'col_d_count': col_d_count, 'd31_value': d31_value}
    finally:
        os.unlink(tmp_path)

