def get_xlsx_filtered_rows__c02b6668bea13a44baccd2ac80b3b6b8(env, config):
    """Get rows filtered by specific column value.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Contains row_count, total_rows, is_filtered_only, and sample values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'row_count': 0, 'total_rows': 0, 'is_filtered_only': False, 'values': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        total_rows = ws.max_row - 1 if ws.max_row > 1 else 0
        filtered_values = []
        percentage_count = 0
        for row_idx in range(2, ws.max_row + 1):
            units_val = ws.cell(row_idx, 5).value
            if units_val and 'Percentage' in str(units_val):
                value = ws.cell(row_idx, 9).value
                filtered_values.append(value)
                percentage_count += 1
        is_filtered_only = total_rows == percentage_count and total_rows > 0
        return {'row_count': percentage_count, 'total_rows': total_rows, 'is_filtered_only': is_filtered_only, 'values': filtered_values}
    finally:
        os.unlink(tmp_path)

