def get_xlsx_cell_highlight__eb1f6e8c444ef8d7baa14bb8003ed297(env, config: dict):
    """Extract highlighted cell information and verify it contains the max value in Sales column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'sheet' (sheet index), 'column' (column letter)

    Returns:
        dict: {
            'highlighted_cell': str or None,  # Cell address (e.g., 'E6')
            'highlighted_value': float or None,  # Value in highlighted cell
            'max_value': float,  # Maximum value in the column
            'max_cell': str,  # Cell address containing max value
            'is_correct': bool  # Whether highlighted cell contains the max value
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'highlighted_cell': None, 'highlighted_value': None, 'max_value': None, 'max_cell': None, 'is_correct': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        column = config.get('column', 'E')
        max_value = None
        max_cell = None
        highlighted_cell = None
        highlighted_value = None
        for row in range(2, ws.max_row + 1):
            cell_addr = f'{column}{row}'
            cell = ws[cell_addr]
            cell_value = cell.value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                if max_value is None or cell_value > max_value:
                    max_value = cell_value
                    max_cell = cell_addr
            fill = cell.fill
            has_fill = fill and fill.patternType and (fill.patternType != 'none')
            if has_fill:
                highlighted_cell = cell_addr
                highlighted_value = cell_value
        is_correct = highlighted_cell == max_cell if highlighted_cell and max_cell else False
        return {'highlighted_cell': highlighted_cell, 'highlighted_value': highlighted_value, 'max_value': max_value, 'max_cell': max_cell, 'is_correct': is_correct}
    finally:
        os.unlink(tmp_path)

