def get_xlsx_column_values__b82f9c9e(env, config: Dict[str, Any]) -> List[Any]:
    """
    Extract values from a specific column in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet' (0-indexed), 'column' (letter or 1-indexed)

    Returns:
        List of values from the specified column (excluding header)
    """
    from desktop_env.evaluators.getters import file as file_getters
    local_path = file_getters.get_vm_file(env, config)
    wb = openpyxl.load_workbook(local_path, data_only=True)
    sheet_idx = config.get('sheet', 0)
    ws = wb.worksheets[sheet_idx]
    column = config.get('column', 'C')
    if isinstance(column, str):
        col_idx = openpyxl.utils.column_index_from_string(column)
    else:
        col_idx = column
    values = []
    for row in range(2, ws.max_row + 1):
        val = ws.cell(row, col_idx).value
        values.append(val)
    wb.close()
    return values

