def get_xlsx_column_text__7d1fc073(env, config):
    """
    Get all text from a specific column in an xlsx file.

    Args:
        env: Environment object
        config: Configuration dict with:
            - 'path': Path to the xlsx file
            - 'sheet': Sheet index (0-based) or sheet name
            - 'column': Column letter (e.g., 'A', 'B', 'C')
            - 'start_row': Starting row number (1-based)
            - 'end_row': Ending row number (1-based)

    Returns:
        list: List of cell values (as strings) from the specified column range
    """
    file_path = config['path']
    sheet_identifier = config.get('sheet', 0)
    column_letter = config['column']
    start_row = config.get('start_row', 1)
    end_row = config.get('end_row', None)
    try:
        with open(file_path, 'rb') as f:
            file_content = f.read()
    except FileNotFoundError:
        file_content = env.controller.get_file(file_path)
        if file_content is None:
            return []
    wb = openpyxl.load_workbook(BytesIO(file_content))
    if isinstance(sheet_identifier, int):
        sheet = wb.worksheets[sheet_identifier]
    else:
        sheet = wb[sheet_identifier]
    column_values = []
    if end_row is None:
        end_row = sheet.max_row
    for row_num in range(start_row, end_row + 1):
        cell_ref = f'{column_letter}{row_num}'
        cell_value = sheet[cell_ref].value
        if cell_value is not None:
            column_values.append(str(cell_value))
        else:
            column_values.append('')
    return column_values

def get_calc_cell_highlight__063f934d6874db92ff621ffd159c73b2(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get cell highlighting information and 2019 cost data from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the xlsx file

    Returns:
        Dict containing:
        - 'highlighted_cells': Dict mapping cell addresses to their fill colors
        - 'data_2019': Dict mapping row numbers to their 2019 total costs
        - 'month_cells': Dict mapping row numbers to month cell addresses in column A
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'highlighted_cells': {}, 'data_2019': {}, 'month_cells': {}}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'highlighted_cells': {}, 'data_2019': {}, 'month_cells': {}}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        highlighted_cells = {}
        for row in ws.iter_rows():
            for cell in row:
                if cell.fill and cell.fill.start_color:
                    color = cell.fill.start_color
                    if hasattr(color, 'rgb') and color.rgb:
                        rgb = color.rgb
                        if len(rgb) == 8:
                            rgb = rgb[2:]
                        highlighted_cells[cell.coordinate] = f'#{rgb}'
                    elif hasattr(color, 'index') and color.index:
                        highlighted_cells[cell.coordinate] = f'indexed_{color.index}'
        data_2019 = {}
        month_cells = {}
        for row_idx in range(2, ws.max_row + 1):
            month_cell = f'A{row_idx}'
            month_cells[row_idx] = month_cell
            total_2019 = 0
            valid_data = False
            for col_idx in range(2, 8):
                cell_value = ws.cell(row=row_idx, column=col_idx).value
                if cell_value is not None:
                    try:
                        total_2019 += float(cell_value)
                        valid_data = True
                    except (ValueError, TypeError):
                        pass
            if valid_data:
                data_2019[row_idx] = total_2019
        return {'highlighted_cells': highlighted_cells, 'data_2019': data_2019, 'month_cells': month_cells}
    finally:
        os.unlink(tmp_path)

def get_xlsx_cell_o2_v8__d4477d7a(env, config: dict):
    """Extract student scores and pass count from grades.xlsx.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary containing:
            - 'pass_count': Value in cell O2 (count of students who passed)
            - 'student_scores': Dict mapping student names to their total scores
            - 'has_formula': Boolean indicating if O2 contains a formula
    """
    path = config.get('path', '/home/user/exam/grades.xlsx')
    file_content = env.controller.get_file(path)
    if file_content is None:
        return None
    with tempfile.NamedTemporaryFile(mode='wb', suffix='.xlsx', delete=False) as f:
        f.write(file_content)
        temp_path = f.name
    try:
        wb = openpyxl.load_workbook(temp_path, data_only=False)
        ws = wb.active
        o2_cell = ws['O2']
        has_formula = o2_cell.value is not None and isinstance(o2_cell.value, str) and o2_cell.value.startswith('=')
        wb.close()
        wb = openpyxl.load_workbook(temp_path, data_only=True)
        ws = wb.active
        pass_count = ws['O2'].value
        student_scores = {}
        for row_idx in range(2, min(20, ws.max_row + 1)):
            name_cell = ws.cell(row=row_idx, column=1).value
            if name_cell and isinstance(name_cell, str) and (len(name_cell) > 0):
                for col_idx in [13, 14]:
                    score_cell = ws.cell(row=row_idx, column=col_idx).value
                    if score_cell is not None:
                        try:
                            score = float(score_cell) if isinstance(score_cell, (int, float)) else float(score_cell)
                            student_scores[name_cell] = score
                            break
                        except (ValueError, TypeError):
                            continue
        wb.close()
        return {'pass_count': pass_count, 'student_scores': student_scores, 'has_formula': has_formula}
    finally:
        if os.path.exists(temp_path):
            os.unlink(temp_path)

def get_xlsx_sheet_data__7001880f97ce5d91e9e11e6dd84fdc47(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract sheet cell values and merge status for verification.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with cell values and merge information
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {'sheets': wb.sheetnames, 'data': {}}
        for sheet_name in wb.sheetnames:
            ws = wb[sheet_name]
            sheet_data = {}
            merged_cells = []
            for merged_range in ws.merged_cells.ranges:
                merged_cells.append(str(merged_range))
            for row in ws.iter_rows():
                for cell in row:
                    coord = cell.coordinate
                    is_merged = False
                    for merged_range in ws.merged_cells.ranges:
                        if cell.coordinate in merged_range:
                            is_merged = True
                            break
                    sheet_data[coord] = {'value': cell.value, 'merged': is_merged}
            result['data'][sheet_name] = {'cells': sheet_data, 'merged_ranges': merged_cells}
        return result
    finally:
        os.unlink(tmp_path)

