def get_xlsx_total_apps__2b96b5be347a66d29c5c37f41fc898fa(env, config: Dict[str, Any]) -> Dict[str, int]:
    """Extract total application numbers for each university from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dictionary mapping university names to total application counts
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        headers = []
        for col_idx in range(2, ws.max_column + 1):
            cell_value = ws.cell(1, col_idx).value
            if cell_value:
                headers.append(str(cell_value))
        for (uni_idx, uni_name) in enumerate(headers):
            col_idx = uni_idx + 2
            total = 0
            for row_idx in range(2, ws.max_row + 1):
                cell_value = ws.cell(row_idx, col_idx).value
                if cell_value is not None and isinstance(cell_value, (int, float)):
                    total += int(cell_value)
            result[uni_name] = total
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_highlighted_employee_names__128ad09f(env, config: Dict[str, Any]):
    """Get list of employee names that have yellow highlighting in their row.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'sheet', 'name_column' (e.g., 'B'), 'start_row', 'end_row'

    Returns:
        List[str]: Names of employees whose rows have yellow fill color (R>200, G>200, B<100)
    """
    file_content = env.controller.get_file(config['path'])
    if not file_content:
        return []
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        highlighted_names = []
        name_col = config['name_column']
        start_row = config['start_row']
        end_row = config['end_row']
        for row_idx in range(start_row, end_row + 1):
            cell = ws[f'{name_col}{row_idx}']
            name = cell.value
            if name and cell.fill and cell.fill.start_color:
                color = cell.fill.start_color
                if hasattr(color, 'rgb') and color.rgb:
                    rgb = str(color.rgb)
                    if len(rgb) >= 6:
                        try:
                            if len(rgb) == 8:
                                r = int(rgb[2:4], 16)
                                g = int(rgb[4:6], 16)
                                b = int(rgb[6:8], 16)
                            else:
                                r = int(rgb[0:2], 16)
                                g = int(rgb[2:4], 16)
                                b = int(rgb[4:6], 16)
                            if r > 200 and g > 200 and (b < 100):
                                highlighted_names.append(name)
                        except (ValueError, IndexError):
                            pass
        return highlighted_names
    finally:
        os.unlink(tmp_path)

