def get_xlsx_grade_counts__cce1216327b416f535dd8f41b26505d5(env, config: dict):
    """Extract grade remarks, labels, and count values from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'count_cells', 'label_cells', and 'student_data' keys

    Returns:
        dict: Dictionary with:
            - 'counts': mapping grade categories to their counts from H column
            - 'labels': mapping grade categories to their labels from G column
            - 'student_remarks': mapping student names to their grade remarks from Message column
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'counts': {}, 'labels': {}, 'student_remarks': {}}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {'counts': {}, 'labels': {}, 'student_remarks': {}}
        count_cells = config.get('count_cells', {})
        for (grade, cell_addr) in count_cells.items():
            cell_value = ws[cell_addr].value
            try:
                result['counts'][grade] = int(cell_value) if cell_value is not None else 0
            except (ValueError, TypeError):
                result['counts'][grade] = 0
        label_cells = config.get('label_cells', {})
        for (grade, cell_addr) in label_cells.items():
            cell_value = ws[cell_addr].value
            result['labels'][grade] = str(cell_value).strip() if cell_value is not None else ''
        student_data = config.get('student_data', {})
        for (student_name, data) in student_data.items():
            message_cell = data.get('message_cell')
            if message_cell:
                cell_value = ws[message_cell].value
                result['student_remarks'][student_name] = str(cell_value).strip() if cell_value is not None else ''
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_sorted_bold_top3__8ad95d8f699bceacb56d23803960d9c1(env, config):
    """Extract sorting status and bold formatting of top 3 rows.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the xlsx file

    Returns:
        dict: Contains period rates, sorting check, bold status, and calculation verification
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        headers = {}
        for col in range(1, ws.max_column + 1):
            header_value = ws.cell(1, col).value
            if header_value:
                headers[str(header_value).strip()] = col
        period_rate_col = headers.get('Period Rate (%)')
        if not period_rate_col:
            return {'period_rates': [], 'is_sorted_desc': False, 'bold_rows': [], 'top3_values': [], 'column_exists': False, 'calculation_verified': False}
        annual_rate_col = headers.get('Annual Rate (%)')
        period_per_year_col = headers.get('Period per year')
        period_rates = []
        calculation_errors = 0
        total_verified = 0
        for row in range(2, ws.max_row + 1):
            cell_value = ws.cell(row, period_rate_col).value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                period_rates.append({'row': row, 'value': cell_value})
                if annual_rate_col and period_per_year_col:
                    annual_rate = ws.cell(row, annual_rate_col).value
                    period_per_year = ws.cell(row, period_per_year_col).value
                    if annual_rate is not None and isinstance(annual_rate, (int, float)) and (period_per_year is not None) and isinstance(period_per_year, (int, float)) and (period_per_year != 0):
                        expected_period_rate = annual_rate / period_per_year
                        total_verified += 1
                        if abs(cell_value - expected_period_rate) > 0.01:
                            calculation_errors += 1
        calculation_verified = True
        if total_verified > 0:
            calculation_verified = calculation_errors / total_verified < 0.2
        is_sorted_desc = True
        for i in range(len(period_rates) - 1):
            if period_rates[i]['value'] < period_rates[i + 1]['value']:
                is_sorted_desc = False
                break
        bold_rows = []
        for row in [2, 3, 4]:
            if row > ws.max_row:
                break
            is_bold = False
            for col in range(1, ws.max_column + 1):
                cell = ws.cell(row, col)
                if cell.font and cell.font.bold:
                    is_bold = True
                    break
            if is_bold:
                bold_rows.append(row)
        result = {'period_rates': period_rates[:5], 'is_sorted_desc': is_sorted_desc, 'bold_rows': bold_rows, 'top3_values': [pr['value'] for pr in period_rates[:3]] if len(period_rates) >= 3 else [], 'column_exists': True, 'calculation_verified': calculation_verified}
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

