def get_xlsx_grades_sheet__8e5ec6a12d03453e954276e7a0ba0dfb(env, config):
    """
    Extract grades sheet data from a LibreOffice Calc .xlsx file.
    Verifies the content is actually a grades spreadsheet with student names and test scores.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the .xlsx file on VM

    Returns:
        dict: Dictionary containing file existence, validation, and content analysis
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'exists': False, 'valid': False, 'has_text_column': False, 'has_numeric_column': False, 'row_count': 0, 'col_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        row_count = ws.max_row
        col_count = ws.max_column
        has_text_column = False
        has_numeric_column = False
        if row_count > 0 and col_count > 0:
            for col_idx in range(1, col_count + 1):
                text_count = 0
                numeric_count = 0
                start_row = 1
                for row_idx in range(start_row, min(start_row + row_count, row_count + 1)):
                    cell_value = ws.cell(row=row_idx, column=col_idx).value
                    if cell_value is not None:
                        if isinstance(cell_value, (int, float)):
                            numeric_count += 1
                        elif isinstance(cell_value, str) and cell_value.strip():
                            text_count += 1
                if text_count > 0:
                    has_text_column = True
                if numeric_count > 0:
                    has_numeric_column = True
        wb.close()
        valid_structure = row_count >= 2 and col_count >= 2 and has_text_column and has_numeric_column
        return {'exists': True, 'valid': valid_structure, 'has_text_column': has_text_column, 'has_numeric_column': has_numeric_column, 'row_count': row_count, 'col_count': col_count}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

