def get_xlsx_row_bold__09e2b78d(env, config):
    """Check if a specific row has bold formatting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (int), 'row' (int)

    Returns:
        bool: True if all non-empty cells in the row are bold, False otherwise
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    file_path = get_vm_file(env, {'path': config['path'], 'dest': os.path.basename(config['path'])})
    if file_path is None:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return False
    wb = openpyxl.load_workbook(file_path)
    if isinstance(config['sheet'], int):
        ws = wb.worksheets[config['sheet']]
    else:
        ws = wb[config['sheet']]
    row_num = config['row']
    bold_count = 0
    cell_count = 0
    for col_idx in range(1, ws.max_column + 1):
        cell = ws.cell(row_num, col_idx)
        if cell.value is not None:
            cell_count += 1
            if cell.font and cell.font.bold:
                bold_count += 1
    if cell_count == 0:
        return False
    return bold_count == cell_count

