def get_xlsx_email_domains__ad16246d(env, config: Dict[str, Any]):
    """Extract email addresses and check their domains.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'cells' parameters

    Returns:
        Dict with email domain information
    """
    file_path = config.get('path')
    cells = config.get('cells', [])
    sheet_idx = config.get('sheet', 0)
    file_content = env.controller.get_file(file_path)
    if not file_content:
        return {'emails': {}}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_content)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        result = {'emails': {}}
        for cell_addr in cells:
            cell_value = ws[cell_addr].value
            if cell_value and isinstance(cell_value, str) and ('@' in cell_value):
                email = cell_value.strip()
                domain = email.split('@')[1] if '@' in email else None
                result['emails'][cell_addr] = {'email': email, 'domain': domain}
            else:
                result['emails'][cell_addr] = {'email': None, 'domain': None}
        return result
    finally:
        os.unlink(tmp_path)

