def get_xlsx_max_value_row__6793c066(env, config: dict) -> Optional[int]:
    """Get row number of maximum value in a column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'column', 'start_row'

    Returns:
        Row number of maximum value or None
    """
    file_path = config.get('path', '/home/user/Documents/Finance/tally_book.xlsx')
    column = config.get('column', 'C')
    start_row = config.get('start_row', 2)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        max_value = None
        max_row = None
        for row in range(start_row, ws.max_row + 1):
            cell_value = ws[f'{column}{row}'].value
            if cell_value is not None:
                try:
                    val = float(cell_value)
                    if max_value is None or val > max_value:
                        max_value = val
                        max_row = row
                except (ValueError, TypeError):
                    pass
        return max_row
    finally:
        os.unlink(tmp_path)

def get_xlsx_last_day_cells__eed4531f88ccf1a8b92113a718036f9a(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract cells containing last day of each month and their fill colors.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path)

    Returns:
        Dict mapping cell coordinates to their fill colors for last-day-of-month cells
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        for row in ws.iter_rows(values_only=False):
            for cell in row:
                if cell.value and isinstance(cell.value, datetime):
                    last_day = calendar.monthrange(cell.value.year, cell.value.month)[1]
                    if cell.value.day == last_day:
                        fill_color = None
                        if cell.fill and cell.fill.patternType and cell.fill.fgColor:
                            if hasattr(cell.fill.fgColor, 'rgb'):
                                fill_color = cell.fill.fgColor.rgb
                            elif hasattr(cell.fill.fgColor, 'theme'):
                                fill_color = f'theme_{cell.fill.fgColor.theme}'
                            else:
                                fill_color = str(cell.fill.fgColor)
                        result[cell.coordinate] = fill_color
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_cell_text__f34c53b18d1e220995e8c85ed1c984b2(env, config):
    """Extract formula and calculated value from a specific cell in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path' (str), 'sheet' (int), and 'cell' (str)

    Returns:
        dict: Dictionary with 'formula' (str or None) and 'value' (str) keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'formula': None, 'value': ''}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cell_addr = config['cell']
        cell = ws[cell_addr]
        formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        ws_data = wb_data.worksheets[sheet_idx]
        cell_value = ws_data[cell_addr].value
        value_str = str(cell_value) if cell_value is not None else ''
        return {'formula': formula, 'value': value_str}
    finally:
        os.unlink(tmp_path)

def get_xlsx_column_e_emails__a70abe3f93785a326d15fd72eafb5f73(env, config: dict):
    """Extract values from columns B, C, D, and E (First Name, Last Name, Rank, Email) in the Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with keys 'first_names', 'last_names', 'ranks', 'emails', each containing
        row numbers as keys and cell values as values
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'first_names': {}, 'last_names': {}, 'ranks': {}, 'emails': {}}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        first_names = {}
        last_names = {}
        ranks = {}
        emails = {}
        for row_idx in range(2, ws.max_row + 1):
            first_name_cell = ws.cell(row=row_idx, column=2).value
            if first_name_cell is not None:
                first_names[row_idx] = str(first_name_cell).strip()
            last_name_cell = ws.cell(row=row_idx, column=3).value
            if last_name_cell is not None:
                last_names[row_idx] = str(last_name_cell).strip()
            rank_cell = ws.cell(row=row_idx, column=4).value
            if rank_cell is not None:
                ranks[row_idx] = str(rank_cell).strip()
            email_cell = ws.cell(row=row_idx, column=5).value
            if email_cell is not None:
                emails[row_idx] = str(email_cell).strip().lower()
        return {'first_names': first_names, 'last_names': last_names, 'ranks': ranks, 'emails': emails}
    finally:
        os.unlink(tmp_path)

