def get_xlsx_all_columns__d91fdfc7724784e170e59e6f60fd16e2(env, config):
    """Extract data from all columns A-E to verify all task requirements.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Dictionary with column data:
            - 'column_a': List of original employee data
            - 'column_b': List of first names
            - 'column_c': List of last names
            - 'column_d': List of ranks
            - 'column_e_header': Header value in E1
            - 'column_e_emails': List of email addresses
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {'column_a': [], 'column_b': [], 'column_c': [], 'column_d': [], 'column_e_header': '', 'column_e_emails': []}
        e1_value = ws.cell(row=1, column=5).value
        result['column_e_header'] = str(e1_value).strip() if e1_value else ''
        for row_idx in range(2, ws.max_row + 1):
            a_val = ws.cell(row=row_idx, column=1).value
            if a_val:
                result['column_a'].append(str(a_val).strip())
            b_val = ws.cell(row=row_idx, column=2).value
            if b_val:
                result['column_b'].append(str(b_val).strip())
            c_val = ws.cell(row=row_idx, column=3).value
            if c_val:
                result['column_c'].append(str(c_val).strip())
            d_val = ws.cell(row=row_idx, column=4).value
            if d_val:
                result['column_d'].append(str(d_val).strip())
            e_val = ws.cell(row=row_idx, column=5).value
            if e_val:
                result['column_e_emails'].append(str(e_val).strip().lower())
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_max_value__84920c0ca4d240b634af1a90c7988532(env, config: dict):
    """Find maximum value in a specific column range.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path', 'sheet', 'column', 'start_row', 'end_row'

    Returns:
        dict: {'max_value': float, 'row': int} or None if file not found
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[config.get('sheet', 0)]
        column = config['column']
        start_row = config['start_row']
        end_row = config['end_row']
        max_val = None
        max_row = None
        for row in range(start_row, end_row + 1):
            cell_value = ws[f'{column}{row}'].value
            if cell_value is not None and isinstance(cell_value, (int, float)):
                if max_val is None or cell_value > max_val:
                    max_val = cell_value
                    max_row = row
        if max_val is not None:
            return {'max_value': round(max_val, 6), 'row': max_row}
        return None
    finally:
        os.unlink(tmp_path)

def get_sheet2_top5_weeks__6e88cb6b453f6c8703776a30122c0c12(env, config: Dict[str, Any]) -> List[str]:
    """Extract top 5 week numbers from Sheet2.

    This getter reads the result file and extracts the top 5 week numbers
    from Sheet2 in the order they appear (should be ranked by average revenue).

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        List of week numbers (as strings) in order
    """
    file_path = config.get('path', '')
    if not file_path:
        return []
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if 'Sheet2' not in wb.sheetnames:
            return []
        ws = wb['Sheet2']
        week_list = []
        for row_idx in range(1, min(ws.max_row + 1, 20)):
            cell_value = ws.cell(row_idx, 1).value
            if cell_value is not None:
                week_str = str(cell_value).strip()
                lower_val = week_str.lower()
                if lower_val not in ['week', 'rank', 'top 5', 'top', '1', '2', '3', '4', '5', 'number']:
                    try:
                        week_num = int(float(week_str))
                        if 1 <= week_num <= 53:
                            week_list.append(str(week_num))
                    except (ValueError, TypeError):
                        pass
        if len(week_list) < 3:
            week_list = []
            for col_idx in range(1, min(ws.max_column + 1, 20)):
                cell_value = ws.cell(1, col_idx).value
                if cell_value is not None:
                    week_str = str(cell_value).strip()
                    lower_val = week_str.lower()
                    if lower_val not in ['week', 'rank', 'top 5', 'top', '1', '2', '3', '4', '5', 'number']:
                        try:
                            week_num = int(float(week_str))
                            if 1 <= week_num <= 53:
                                week_list.append(str(week_num))
                        except (ValueError, TypeError):
                            pass
        wb.close()
        return week_list[:5]
    finally:
        os.unlink(tmp_path)

