def get_xlsx_row_count__fa635253(env, config: dict):
    """Get number of data rows in specified column range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'start_row', 'end_row', 'column'

    Returns:
        int: Number of non-empty rows
    """
    import openpyxl
    import io
    vm_path = config.get('path', '/home/user/Desktop/my_bookkeeping.xlsx')
    sheet_idx = config.get('sheet', 0)
    start_row = config.get('start_row', 1)
    end_row = config.get('end_row', 100)
    column = config.get('column', 'A')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return 0
    wb = openpyxl.load_workbook(io.BytesIO(file_bytes), data_only=True)
    ws = wb.worksheets[sheet_idx] if isinstance(sheet_idx, int) else wb[sheet_idx]
    count = 0
