def get_xlsx_cell_colors__8a224e68(env, config: dict) -> Dict[str, Any]:
    """Extract background colors for all cells in the specified sheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict mapping cell coordinates to their RGB background colors (as hex strings)
    """
    vm_path = config.get('path', '/home/user/Calendar_Highlight_Weekend_Days.xlsx')
    dest = config.get('dest', 'Calendar_Highlight_Weekend_Days.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    import os
    cache_dir = env.cache_dir
    local_path = os.path.join(cache_dir, dest)
    os.makedirs(os.path.dirname(local_path), exist_ok=True)
    with open(local_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(local_path)
    ws = wb.active
    cell_colors = {}
    for row in ws.iter_rows():
        for cell in row:
            if cell.fill and cell.fill.start_color:
                color = cell.fill.start_color.rgb
                if color and color != '00000000':
                    if len(color) == 8:
                        hex_color = f'#{color[2:].upper()}'
                    else:
                        hex_color = f'#{color.upper()}'
                    cell_colors[cell.coordinate] = hex_color
    wb.close()
    return cell_colors

def get_combined_xlsx_check__06dc70fa7cf93b7501432994b47d9c35(env, config: dict) -> Dict[str, Any]:
    """Extract the top product by quantity and check if it's highlighted.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict with 'top_product' (str) and 'is_highlighted' (bool) keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'top_product': '', 'is_highlighted': False}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_data = openpyxl.load_workbook(tmp_path, data_only=True)
        ws_data = wb_data.active
        product_quantities = {}
        for row in ws_data.iter_rows(min_row=2, max_row=ws_data.max_row, values_only=True):
            if not any(row):
                continue
            product = row[2]
            quantity = row[4]
            if product and quantity:
                product_quantities[product] = product_quantities.get(product, 0) + quantity
        top_product = ''
        if product_quantities:
            max_product = max(product_quantities.items(), key=lambda x: x[1])
            top_product = max_product[0]
        wb_style = openpyxl.load_workbook(tmp_path)
        ws_style = wb_style.active
        is_highlighted = False
        for (row_idx, row) in enumerate(ws_style.iter_rows(min_row=2, max_row=ws_style.max_row), start=2):
            if not any((cell.value for cell in row)):
                continue
            product_cell = row[2]
            product = product_cell.value
            if product == top_product:
                if product_cell.fill and product_cell.fill.start_color:
                    color = product_cell.fill.start_color.rgb
                    if color and color not in ['FFFFFFFF', '00000000', 'FF000000']:
                        is_highlighted = True
                        break
        return {'top_product': top_product, 'is_highlighted': is_highlighted}
    finally:
        os.unlink(tmp_path)

def get_docx_table_cell__95f984dd(env, config: dict):
    """Extract a specific cell value from a table in a docx file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with parameters:
            - path: VM path to the docx file
            - dest: Local destination filename
            - table_index: Which table to extract from (0-based)
            - row: Row index (0-based)
            - col: Column index (0-based)

    Returns:
        Cell text content (stripped)
    """
    try:
        vm_path = config.get('path', '/home/user/Documents/awesome-desktop/awe_desk_env.docx')
        file_bytes = env.controller.get_file(vm_path)
        if not file_bytes:
            logger.error(f'Failed to get file from VM: {vm_path}')
            return None
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.docx') as tmp_file:
            tmp_file.write(file_bytes)
            tmp_path = tmp_file.name
        try:
            doc = Document(tmp_path)
            table_index = config.get('table_index', 0)
            if table_index >= len(doc.tables):
                logger.error(f'Table index {table_index} out of range (only {len(doc.tables)} tables)')
                return None
            table = doc.tables[table_index]
            row = config.get('row', 0)
            col = config.get('col', 0)
            if row >= len(table.rows):
                logger.error(f'Row index {row} out of range (only {len(table.rows)} rows)')
                return None
            if col >= len(table.columns):
                logger.error(f'Column index {col} out of range (only {len(table.columns)} columns)')
                return None
            cell_text = table.cell(row, col).text.strip()
            logger.info(f'Extracted cell ({row}, {col}): {cell_text}')
            return cell_text
        finally:
            os.unlink(tmp_path)
    except Exception as e:
        logger.error(f'Error extracting docx table cell: {e}')
        return None

