def get_xlsx_mark_ranges__f65369be(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Get marks and messages for students to verify completion.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'marks_col', 'message_col', 'start_row', 'end_row'

    Returns:
        Dict with 'students' list containing mark and message for each student,
        and 'range_counts' with distribution analysis
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    marks_col = config.get('marks_col', 'E')
    message_col = config.get('message_col', 'F')
    start_row = config.get('start_row', 10)
    end_row = config.get('end_row', 23)
    ranges = config.get('ranges', [{'name': '0-29', 'min': 0, 'max': 29}, {'name': '30-59', 'min': 30, 'max': 59}, {'name': '60-79', 'min': 60, 'max': 79}, {'name': '80-100', 'min': 80, 'max': 100}])
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'students': [], 'range_counts': {}}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        students = []
        range_counts = {r['name']: 0 for r in ranges}
        for row in range(start_row, end_row + 1):
            mark_cell = ws[f'{marks_col}{row}'].value
            message_cell = ws[f'{message_col}{row}'].value
            if mark_cell is not None:
                try:
                    mark_val = float(mark_cell)
                    range_name = None
                    for r in ranges:
                        if r['min'] <= mark_val <= r['max']:
                            range_name = r['name']
                            range_counts[r['name']] += 1
                            break
                    students.append({'row': row, 'mark': mark_val, 'message': message_cell if message_cell else None, 'range': range_name})
                except:
                    pass
        wb.close()
        return {'students': students, 'range_counts': range_counts}
    finally:
        os.unlink(tmp_path)

