def get_xlsx_product_revenue_table__116fbd3460dada9be380bc664e224d99(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract product revenue table from a new sheet.
    Expects the agent to create a table with products and their total revenue.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'sheet_name'

    Returns:
        Dict with product names as keys and revenue values as floats
    """
    file_path = config.get('path', '/home/user/SummerSales.xlsx')
    sheet_name = config.get('sheet_name', 'Sheet2')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return {}
        ws = wb[sheet_name]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            product = str(row[0]).strip() if row[0] else None
            revenue = row[1] if row[1] is not None else 0.0
            if product:
                try:
                    revenue = float(revenue)
                except (ValueError, TypeError):
                    revenue = 0.0
                result[product] = revenue
        return result
    finally:
        os.unlink(tmp_path)

