def get_xlsx_date_format__34dc6c13(env, config: dict):
    """Extract paper entries from Excel file with date and content validation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'pattern' keys

    Returns:
        dict: Contains:
            - total_dates: Number of dates found
            - properly_formatted: Number of dates matching YYYY.M.D pattern
            - papers: List of all paper entries with titles, dates, formatting info
            - papers_with_oct11_2023: Papers with date 2023.10.11
            - total_papers: Total number of papers in spreadsheet
            - lm_papers_with_oct11: Language model papers from Oct 11 2023
    """
    vm_path = config.get('path', '')
    expected_pattern = config.get('pattern', '^\\d{4}\\.\\d{1,2}\\.\\d{1,2}$')
    file_content = env.controller.get_file(vm_path)
    if not file_content:
        return {'total_dates': 0, 'properly_formatted': 0, 'papers': [], 'papers_with_oct11_2023': [], 'lm_papers_with_oct11': [], 'total_papers': 0}
    wb = openpyxl.load_workbook(io.BytesIO(file_content), data_only=True)
    ws = wb.active
    total_dates = 0
    properly_formatted = 0
    papers = []
    papers_with_oct11_2023 = []
    lm_papers_with_oct11 = []
    lm_keywords = ['language model', 'llm', 'transformer', 'gpt', 'bert', 'nlp', 'natural language processing', 'neural language', 'pre-trained', 'pretrained', 'attention', 'seq2seq', 'encoder-decoder', 'generative', 'text generation', 'chatbot', 'conversational', 't5', 'bart', 'roberta', 'xlnet', 'elmo', 'word2vec', 'embedding']
    for row_idx in range(2, ws.max_row + 1):
        title_value = ws.cell(row_idx, 1).value
        author_value = ws.cell(row_idx, 2).value
        date_value = ws.cell(row_idx, 3).value
        if not title_value and (not date_value):
            continue
        date_str = str(date_value).strip() if date_value else ''
        title_str = str(title_value).strip() if title_value else ''
        if date_str:
            total_dates += 1
            is_formatted = bool(re.match(expected_pattern, date_str))
            if is_formatted:
                properly_formatted += 1
            title_lower = title_str.lower()
            is_lm_paper = any((keyword in title_lower for keyword in lm_keywords))
            paper_entry = {'title': title_str, 'date': date_str, 'is_formatted': is_formatted, 'is_lm_paper': is_lm_paper, 'row': row_idx}
            papers.append(paper_entry)
            if '2023.10.11' in date_str or date_str == '2023.10.11':
                papers_with_oct11_2023.append(paper_entry)
                if is_lm_paper:
                    lm_papers_with_oct11.append(paper_entry)
    wb.close()
    return {'total_dates': total_dates, 'properly_formatted': properly_formatted, 'papers': papers, 'papers_with_oct11_2023': papers_with_oct11_2023, 'lm_papers_with_oct11': lm_papers_with_oct11, 'total_papers': len(papers)}

