def get_max_cell_highlight__86b87e3b(env, config):
    """
    Get information about the maximum value in a specified column and whether that cell is highlighted.

    This function extracts all numeric values from the specified column,
    finds the maximum value, and checks if that cell has background highlighting.

    Args:
        env: Environment object
        config: Configuration dict with:
            - 'path': path to the Excel file
            - 'sheet': sheet index (0-based)
            - 'column': column index (0-based, e.g., 5 for column F)

    Returns:
        dict: {
            'column_values': {cell_coordinate: numeric_value},
            'max_value': float,
            'max_row': int,
            'max_cell': str,
            'highlighted_cells': [list of cell coordinates with background color],
            'max_cell_has_color': bool
        }
    """
    file_path = config.get('path', '/home/user/BoomerangSales.xlsx')
    sheet_index = config.get('sheet', 0)
    column_index = config.get('column', 5)
    with open(file_path, 'rb') as f:
        file_content = f.read()
    wb = openpyxl.load_workbook(BytesIO(file_content))
    sheet = wb.worksheets[sheet_index]
    from openpyxl.utils import get_column_letter
    column_letter = get_column_letter(column_index + 1)
    column_values = {}
    max_value = None
    max_row = None
    max_cell = None
    for row in range(2, sheet.max_row + 1):
        cell = sheet[f'{column_letter}{row}']
        if cell.value is not None:
            try:
                numeric_value = float(cell.value)
                column_values[f'{column_letter}{row}'] = numeric_value
                if max_value is None or numeric_value > max_value:
                    max_value = numeric_value
                    max_row = row
                    max_cell = f'{column_letter}{row}'
            except (ValueError, TypeError):
                pass
    highlighted_cells = []
    for row in range(2, sheet.max_row + 1):
        cell = sheet[f'{column_letter}{row}']
        if cell.fill and cell.fill.start_color:
            color_index = cell.fill.start_color.index
            if color_index is None:
                continue
            if color_index not in ['00000000', 'FFFFFFFF', 'FFFFFF', '00FFFFFF']:
                highlighted_cells.append(f'{column_letter}{row}')
    max_cell_has_color = max_cell in highlighted_cells if max_cell else False
    return {'column_values': column_values, 'max_value': max_value, 'max_row': max_row, 'max_cell': max_cell, 'highlighted_cells': highlighted_cells, 'max_cell_has_color': max_cell_has_color}

def get_xlsx_cell_value__be954fd3(env, config: dict) -> Optional[Any]:
    """
    Extract a cell value from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to the Excel file on VM
            - sheet: Sheet name or index
            - cell: Cell address (e.g., 'A1', 'B5')

    Returns:
        The cell value (str, int, float, datetime, etc.) or None if not found
    """
    file_path = config.get('path')
    sheet_ref = config.get('sheet')
    cell_addr = config.get('cell')
    if not all([file_path, sheet_ref is not None, cell_addr]):
        return None
    try:
        file_bytes = env.controller.get_file(file_path)
        if not file_bytes:
            return None
        import tempfile
        import os
        with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
            tmp.write(file_bytes)
            tmp_path = tmp.name
        try:
            wb = openpyxl.load_workbook(tmp_path, data_only=True)
            if isinstance(sheet_ref, int):
                ws = wb.worksheets[sheet_ref]
            else:
                ws = wb[sheet_ref]
            cell_value = ws[cell_addr].value
            wb.close()
            return cell_value
        finally:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
    except Exception as e:
        print(f'Error reading cell {cell_addr}: {e}')
        return None

def get_xlsx_cell_fill__1b9ec83c(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Read cell fill color from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file on VM
            - sheet: Sheet index (0-based) or sheet name
            - cell: Cell address (e.g., "E2")

    Returns:
        Dict with fill information: {"has_fill": bool, "color": str or None}
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    cell_addr = config.get('cell')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'has_fill': False, 'color': None}
    import tempfile
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        cell = ws[cell_addr]
        fill = cell.fill
        has_fill = fill and fill.start_color and (fill.start_color.rgb is not None)
        color = fill.start_color.rgb if has_fill else None
        wb.close()
        return {'has_fill': has_fill, 'color': color}
    finally:
        import os
        os.unlink(tmp_path)

def get_xlsx_data_validation__d86a23ea(env, config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    Extract data validation rules from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet' (0-indexed)

    Returns:
        List of data validation rules
    """
    from desktop_env.evaluators.getters import file as file_getters
    local_path = file_getters.get_vm_file(env, config)
    wb = openpyxl.load_workbook(local_path)
    sheet_idx = config.get('sheet', 0)
    ws = wb.worksheets[sheet_idx]
    validations = []
    for dv in ws.data_validations.dataValidation:
        validation_info = {'type': dv.type, 'formula1': dv.formula1, 'formula2': dv.formula2, 'ranges': [str(r) for r in dv.cells.ranges], 'showErrorMessage': dv.showErrorMessage, 'errorStyle': dv.errorStyle, 'errorTitle': dv.errorTitle, 'error': dv.error}
        validations.append(validation_info)
    wb.close()
    return validations

def get_xlsx_column_count__675bda97e64ba1b5793556f424b73ddb(env, config: Dict[str, Any]) -> int:
    """Read the numeric value from a specific cell in an Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to Excel file
            - column: Column letter (e.g., 'D')
            - start_row: Row number to read (1-indexed), default 2

    Returns:
        int: The numeric value from the specified cell (or 0 if not a valid number)
    """
    file_path = config.get('path', '')
    column = config.get('column', 'D')
    start_row = config.get('start_row', 2)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return 0
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        cell_ref = f'{column}{start_row}'
        cell_value = ws[cell_ref].value
        wb.close()
        if cell_value is None:
            return 0
        try:
            return int(cell_value)
        except (ValueError, TypeError):
            return 0
    finally:
        os.unlink(tmp_path)

def get_xlsx_column_b_bold__bc1f5b4b(env, config: Dict[str, Any]) -> List[bool]:
    """Check if cells in column B (Professor) are bold.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        List of booleans indicating if each cell is bold
    """
    file_path = config.get('path', '')
    wb = openpyxl.load_workbook(file_path, data_only=False)
    ws = wb.active
    is_bold = []
    for row in range(3, ws.max_row + 1):
        cell = ws.cell(row=row, column=2)
