def get_xlsx_complete_rows__001f18fe(env, config: dict) -> dict:
    """Extract complete restaurant data rows from MUST_VISIT.xlsx.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' parameter

    Returns:
        Dict with row-by-row completeness info
    """
    file_path = config.get('path', '/home/user/Desktop/MUST_VISIT.xlsx')
    file_content = env.controller.get_file(file_path)
    if not file_content:
        return {'complete_rows': 0, 'total_rows': 5}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_content)
