def get_xlsx_channel_revenue_table__22652fc14c0135d2f835816b613f7f8c(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract sales channel revenue table from a new sheet.
    Expects the agent to create a table with sales channels and their total revenue.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'sheet_name'

    Returns:
        Dict with sales channel names as keys and revenue values as floats
    """
    file_path = config.get('path', '/home/user/SummerSales.xlsx')
    sheet_name = config.get('sheet_name', 'Sheet2')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return {}
        ws = wb[sheet_name]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            channel = str(row[0]).strip() if row[0] else None
            revenue = row[1] if row[1] is not None else 0.0
            if channel:
                try:
                    revenue = float(revenue)
                except (ValueError, TypeError):
                    revenue = 0.0
                result[channel] = revenue
        return result
    finally:
        os.unlink(tmp_path)

def get_vm_file(env, config: Dict[str, Any]):
    """Get file from VM - simplified version for this getter."""
    path = config['path']
    dest = config.get('dest', os.path.basename(path))
    try:
        file_content = env.controller.get_file(path)
        if file_content is None:
            logger.warning(f'Failed to get file from VM: {path}')
            return None
        cache_path = os.path.join(env.cache_dir, dest)
        os.makedirs(env.cache_dir, exist_ok=True)
        with open(cache_path, 'wb') as f:
            f.write(file_content)
        return cache_path
    except Exception as e:
        logger.error(f'Error getting file {path}: {e}')
        return None

def get_cell_highlighting__15af78e8(env, config: dict):
    """
    Extract cell highlighting (fill color) information from a specific cell.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet', 'cell' parameters

    Returns:
        dict with 'has_fill' and 'fill_color' keys
    """
    file_bytes = env.controller.get_file(config['path'])
    if file_bytes is None:
        return None
    cache_path = os.path.join(env.cache_dir, config['dest'])
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path)
    sheet_idx = config.get('sheet', 0)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    cell_ref = config['cell']
    cell = ws[cell_ref]
    fill = cell.fill
    has_fill = fill is not None and fill.fill_type == 'solid' and (fill.fgColor is not None)
    fill_color = None
    if has_fill and hasattr(fill.fgColor, 'rgb'):
        fill_color = fill.fgColor.rgb
    return {'has_fill': has_fill, 'fill_color': fill_color, 'cell': cell_ref}

