def get_xlsx_row_fill__6cd04c20c7b4a06ef73430ed7250751b(env, config):
    """Check if an entire row has fill color applied.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path), 'sheet' (sheet index), 'row' (row number)

    Returns:
        bool: True if the entire row has fill color, False otherwise
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return False
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        sheet_idx = config.get('sheet', 0)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        row_num = config.get('row', 1)
        max_col = ws.max_column
        num_cols_to_check = min(max_col, max(10, max_col))
        filled_cells = 0
        total_cells_checked = 0
        for col_num in range(1, num_cols_to_check + 1):
            cell = ws.cell(row=row_num, column=col_num)
            total_cells_checked += 1
            if cell.fill and cell.fill.start_color:
                color_code = cell.fill.start_color.rgb if hasattr(cell.fill.start_color, 'rgb') else None
                if color_code and color_code not in ['00000000', 'FFFFFFFF', None]:
                    filled_cells += 1
        if total_cells_checked > 0 and filled_cells / total_cells_checked >= 0.8:
            return True
        return False
    finally:
        os.unlink(tmp_path)

