def get_xlsx_cell_value__adc491c6(env, config):
    """
    Get the value of a specific cell from an xlsx file.

    Args:
        env: Environment object with controller and cache_dir
        config: Configuration dict with:
            - path (str): absolute path on the VM to the xlsx file
            - sheet (int or str): sheet index (int) or sheet name (str)
            - cell (str): cell reference (e.g., "B5")

    Returns:
        str: Cell value as string, or empty string if cell is empty
    """
    path = config['path']
    sheet = config['sheet']
    cell_ref = config['cell']
    file_data = env.controller.get_file(path)
    if file_data is None:
        logger.warning(f'Failed to get file from VM: {path}')
        return ''
    cache_path = os.path.join(env.cache_dir, os.path.basename(path))
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_data)
    try:
        wb = openpyxl.load_workbook(cache_path, data_only=True)
        if isinstance(sheet, int):
            ws = wb.worksheets[sheet]
        else:
            ws = wb[sheet]
        cell_value = ws[cell_ref].value
        wb.close()
        if cell_value is None:
            return ''
        return str(cell_value)
    except Exception as e:
        logger.error(f'Error reading xlsx file {path}: {e}')
        return ''

def get_xlsx_rep_averages__7c74470573d2b62e58f806df5ff49277(env, config):
    """Extract average monthly sales for each sales rep from a new worksheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        dict: Dictionary mapping rep names to their average monthly sales
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        result = {}
        for sheet_name in wb.sheetnames:
            if sheet_name == 'Sheet1':
                continue
            ws = wb[sheet_name]
            for row_idx in range(2, ws.max_row + 1):
                rep_name = ws.cell(row_idx, 1).value
                average = ws.cell(row_idx, 2).value
                if rep_name is not None:
                    result[str(rep_name)] = float(average) if average is not None else 0.0
            break
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_column_values__12717318(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Read column values and formulas from an Excel file.

    This getter extracts values and formulas from a specified column in an Excel file,
    useful for verifying that formulas have been correctly added to a column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file on VM
            - dest: Destination filename for caching

    Returns:
        Dict with column information: {
            "header": str or None,  # Header value in the column
            "values": List[Any],    # Cell values
            "formulas": List[str or None],  # Cell formulas (None if not a formula)
            "row_count": int        # Number of data rows with formulas
        }
    """
    file_path = config.get('path')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'header': None, 'values': [], 'formulas': [], 'row_count': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=False)
        ws = wb.worksheets[0]
        column_letter = 'C'
        header_cell = ws[f'{column_letter}1']
        header = header_cell.value
        values = []
        formulas = []
        row = 2
        max_row = ws.max_row if ws.max_row else 100
        while row <= max_row:
            cell = ws[f'{column_letter}{row}']
            values.append(cell.value)
            if cell.data_type == 'f':
                formulas.append(cell.value)
            else:
                formulas.append(None)
            row += 1
        row_count = sum((1 for f in formulas if f is not None))
        wb.close()
        return {'header': header, 'values': values, 'formulas': formulas, 'row_count': row_count}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

