def get_xlsx_period_rate_sum__da315cf2edc339756d9b2f4defe564ad(env, config):
    """Extract period rate data, individual values, and sum from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: {
            'header': str (exact column header),
            'period_rate_values': list of dicts with {
                'row': int,
                'annual_rate': float,
                'period_per_year': int,
                'period_rate': float,
                'is_numeric': bool
            },
            'sum_value': float,
            'sum_row': int,
            'sum_row_label': str (label in first column of sum row),
            'total_data_rows': int
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        period_rate_col = None
        header_value = None
        for col in range(1, ws.max_column + 1):
            cell_value = ws.cell(row=1, column=col).value
            if cell_value and 'Period Rate' in str(cell_value):
                period_rate_col = col
                header_value = str(cell_value)
                break
        if period_rate_col is None:
            return {'header': None}
        period_rate_values = []
        data_row_count = 0
        for row in range(2, ws.max_row + 1):
            annual_rate_cell = ws.cell(row=row, column=1)
            period_per_year_cell = ws.cell(row=row, column=2)
            period_rate_cell = ws.cell(row=row, column=period_rate_col)
            annual_rate = annual_rate_cell.value
            period_per_year = period_per_year_cell.value
            period_rate = period_rate_cell.value
            if annual_rate is not None and period_per_year is not None:
                first_col_value = str(annual_rate).lower() if annual_rate else ''
                if any((keyword in first_col_value for keyword in ['sum', 'total', 'average', 'avg'])):
                    sum_value = period_rate
                    sum_row = row
                    sum_row_label = str(annual_rate)
                    break
                data_row_count += 1
                is_numeric = isinstance(period_rate, (int, float))
                period_rate_values.append({'row': row, 'annual_rate': annual_rate if isinstance(annual_rate, (int, float)) else None, 'period_per_year': period_per_year if isinstance(period_per_year, (int, float)) else None, 'period_rate': period_rate if isinstance(period_rate, (int, float)) else None, 'is_numeric': is_numeric})
            elif annual_rate is not None and period_per_year is None:
                sum_value = period_rate
                sum_row = row
                sum_row_label = str(annual_rate)
                break
        if 'sum_value' not in locals() and data_row_count > 0:
            last_data_row = period_rate_values[-1]['row'] if period_rate_values else 1
            sum_row = last_data_row + 1
            if sum_row <= ws.max_row:
                sum_cell = ws.cell(row=sum_row, column=period_rate_col)
                sum_value = sum_cell.value
                sum_row_label_cell = ws.cell(row=sum_row, column=1)
                sum_row_label = str(sum_row_label_cell.value) if sum_row_label_cell.value else ''
            else:
                sum_value = None
                sum_row_label = ''
        elif 'sum_value' not in locals():
            sum_value = None
            sum_row = None
            sum_row_label = ''
        return {'header': header_value, 'period_rate_values': period_rate_values, 'sum_value': sum_value if isinstance(sum_value, (int, float)) else None, 'sum_row': sum_row if 'sum_row' in locals() else None, 'sum_row_label': sum_row_label if 'sum_row_label' in locals() else '', 'total_data_rows': data_row_count}
    finally:
        os.unlink(tmp_path)

