def get_cell_alignment__0bfaa3c8(env, config: dict):
    """
    Extract the alignment (horizontal/vertical) of cells in a column or range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'dest', 'sheet', 'cell' parameters
                'cell' can be a single cell (e.g., 'C2') or a range (e.g., 'C2:C10')

    Returns:
        dict with cells info and their alignments, or single cell info if checking one cell
    """
    file_bytes = env.controller.get_file(config['path'])
    if file_bytes is None:
        return None
    cache_path = os.path.join(env.cache_dir, config['dest'])
    os.makedirs(env.cache_dir, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    sheet_idx = config.get('sheet', 0)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    cell_ref = config['cell']
    if ':' in cell_ref:
        cell_range = ws[cell_ref]
        cells_info = []
        if isinstance(cell_range, tuple):
            for row in cell_range:
                if isinstance(row, tuple):
                    for cell in row:
                        alignment = cell.alignment if cell else None
                        horizontal = alignment.horizontal if alignment else None
                        vertical = alignment.vertical if alignment else None
                        cells_info.append({'cell': cell.coordinate, 'value': cell.value, 'horizontal_alignment': horizontal, 'vertical_alignment': vertical})
                else:
                    cell = row
                    alignment = cell.alignment if cell else None
                    horizontal = alignment.horizontal if alignment else None
                    vertical = alignment.vertical if alignment else None
                    cells_info.append({'cell': cell.coordinate, 'value': cell.value, 'horizontal_alignment': horizontal, 'vertical_alignment': vertical})
        else:
            cell = cell_range
            alignment = cell.alignment if cell else None
            horizontal = alignment.horizontal if alignment else None
            vertical = alignment.vertical if alignment else None
            cells_info.append({'cell': cell.coordinate, 'value': cell.value, 'horizontal_alignment': horizontal, 'vertical_alignment': vertical})
        return {'range': cell_ref, 'cells': cells_info}
    else:
        cell = ws[cell_ref]
        alignment = cell.alignment if cell else None
        horizontal = alignment.horizontal if alignment else None
        vertical = alignment.vertical if alignment else None
        return {'cell': cell_ref, 'value': cell.value, 'horizontal_alignment': horizontal, 'vertical_alignment': vertical}

def get_pptx_table_cells__596ba6d4c15f71147e34917f05806ebb(env, config: dict):
    """Extract table data as a 2D list from a PowerPoint slide.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: Path to the .pptx file on VM
            - slide_index: Index of the slide (0-based)

    Returns:
        List of lists representing table rows and columns
    """
    file_path = config['path']
    slide_index = config['slide_index']
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        if slide_index >= len(prs.slides):
            return []
        slide = prs.slides[slide_index]
        for shape in slide.shapes:
            if shape.has_table:
                table = shape.table
                table_data = []
                for row in table.rows:
                    row_data = [cell.text for cell in row.cells]
                    table_data.append(row_data)
                return table_data
        return []
    finally:
        os.unlink(tmp_path)

