def get_xlsx_acl_awards_data__284beee3d948663e7f9ad155cb9a3f13(env, config: dict):
    """Extract ACL award data from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        dict: Extracted data with 'years', 'titles', 'authors', 'links', 'row_count'
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'row_count': 0, 'years': [], 'titles': [], 'authors': [], 'links': []}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        years = []
        titles = []
        authors = []
        links = []
        row_count = 0
        for row in range(2, ws.max_row + 1):
            has_data = False
            for col in range(1, ws.max_column + 1):
                if ws.cell(row=row, column=col).value is not None:
                    has_data = True
                    break
            if not has_data:
                continue
            row_count += 1
            year_val = ws.cell(row=row, column=1).value
            title_val = ws.cell(row=row, column=2).value
            authors_val = ws.cell(row=row, column=3).value
            link_val = ws.cell(row=row, column=4).value
            years.append(year_val)
            titles.append(title_val if title_val else '')
            authors.append(authors_val if authors_val else '')
            links.append(link_val if link_val else '')
        return {'row_count': row_count, 'years': years, 'titles': titles, 'authors': authors, 'links': links}
    finally:
        os.unlink(tmp_path)

