    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return None
    cache_path = os.path.join(env.cache_dir, 'temp_check.xlsx')
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=False)
    if isinstance(sheet_index, int):
        ws = wb.worksheets[sheet_index]
    else:
        ws = wb[sheet_index]
    bold_status = {}
