def get_xlsx_cell_fill__b9c7b1863a4f058f66e92296140420ff(env, config: dict):
    """Extract cell fill color and verify it contains max value in column B.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column'

    Returns:
        dict: {
            'has_fill': bool,
            'fill_color': str or None,
            'is_max_cell': bool,
            'max_cell': str,
            'highlighted_cell': str or None
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_fill': False, 'fill_color': None, 'is_max_cell': False, 'max_cell': None, 'highlighted_cell': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(config['sheet'], int):
            ws = wb.worksheets[config['sheet']]
        else:
            ws = wb[config['sheet']]
        column = config.get('column', 'B')
        max_value = None
        max_cell_address = None
        row_num = 2
        while True:
            cell_address = f'{column}{row_num}'
            cell = ws[cell_address]
            value = cell.value
            if value is None:
                break
            try:
                numeric_value = float(value)
                if max_value is None or numeric_value > max_value:
                    max_value = numeric_value
                    max_cell_address = cell_address
            except (ValueError, TypeError):
                pass
            row_num += 1
        highlighted_cell = None
        has_fill = False
        fill_color = None
        for row in range(2, row_num):
            cell_address = f'{column}{row}'
            cell = ws[cell_address]
            fill = cell.fill
            if fill and fill.start_color:
                color_rgb = fill.start_color.rgb
                if color_rgb and color_rgb not in ['00000000', '00FFFFFF', None]:
                    highlighted_cell = cell_address
                    has_fill = True
                    fill_color = str(color_rgb)
                    break
        is_max_cell = highlighted_cell == max_cell_address if highlighted_cell else False
        wb.close()
        return {'has_fill': has_fill, 'fill_color': fill_color, 'is_max_cell': is_max_cell, 'max_cell': max_cell_address, 'highlighted_cell': highlighted_cell}
    finally:
        os.unlink(tmp_path)

def get_xlsx_cell_value__5b98084d(env, config):
    """Get the value and formula of a specific cell from an Excel file.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path' (VM file path), 'sheet' (index), and 'cell' (address)

    Returns:
        Dict with 'value' and 'formula' keys, or None if error
    """
    file_path = config.get('path', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    temp_path = '/tmp/temp_excel_file.xlsx'
    with open(temp_path, 'wb') as f:
        f.write(file_bytes)
    try:
        wb = openpyxl.load_workbook(temp_path, data_only=False)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cell_addr = config.get('cell', 'A1')
        cell = ws[cell_addr]
        formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
        wb.close()
        wb_data = openpyxl.load_workbook(temp_path, data_only=True)
        ws_data = wb_data.worksheets[sheet_idx]
        cell_data = ws_data[cell_addr]
        value = cell_data.value
        wb_data.close()
        if os.path.exists(temp_path):
            os.remove(temp_path)
        return {'value': value, 'formula': formula}
    except Exception as e:
        print(f'Error getting cell value: {e}')
        if os.path.exists(temp_path):
            os.remove(temp_path)
        return None

def get_xlsx_value_count__3c927c80(env, config: Dict[str, Any]) -> Dict[str, int]:
    """
    Count occurrences of each value in a specified column range.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'column', 'start_row', 'end_row'

    Returns:
        Dict mapping values to their counts
    """
    vm_path = config.get('path', '')
    file_bytes = env.controller.get_file(vm_path)
    if file_bytes is None:
        return {}
    wb = openpyxl.load_workbook(BytesIO(file_bytes), data_only=True)
    ws = wb.active
    column = config.get('column', 'F')
    start_row = config.get('start_row', 2)
    end_row = config.get('end_row', 12)
    value_counts = {}
    for row in range(start_row, end_row + 1):
        cell_value = ws[f'{column}{row}'].value
        if cell_value:
            value_counts[cell_value] = value_counts.get(cell_value, 0) + 1
    return value_counts

