def get_xlsx_highlighted_rows__17d23e13d57d74d8631a4d846b903a33(env, config):
    """Extract rows that have yellow background fill color applied and verify period rate calculation.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the xlsx file

    Returns:
        dict: Contains verification results including column header, calculations, and highlighted rows
    """
    file_path = config.get('path', '')
    if not file_path:
        return {'has_period_rate_column': False, 'calculations_correct': False, 'highlighted_rows': [], 'count': 0}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'has_period_rate_column': False, 'calculations_correct': False, 'highlighted_rows': [], 'count': 0}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        has_period_rate_column = False
        period_rate_col = None
        for col in range(1, ws.max_column + 1):
            header = ws.cell(1, col).value
            if header and 'Period Rate' in str(header) and ('%' in str(header)):
                has_period_rate_column = True
                period_rate_col = col
                break
        if not has_period_rate_column:
            wb.close()
            return {'has_period_rate_column': False, 'calculations_correct': False, 'highlighted_rows': [], 'count': 0}
        annual_rate_col = None
        period_col = None
        for col in range(1, ws.max_column + 1):
            header = ws.cell(1, col).value
            if header:
                header_str = str(header).strip()
                if 'Annual Rate' in header_str and '%' in header_str:
                    annual_rate_col = col
                elif 'Period' in header_str and 'Annual' not in header_str and ('Rate' not in header_str):
                    period_col = col
        calculations_correct = True
        calculation_errors = []
        for row in range(2, ws.max_row + 1):
            if annual_rate_col and period_col and period_rate_col:
                annual_rate = ws.cell(row, annual_rate_col).value
                period = ws.cell(row, period_col).value
                period_rate = ws.cell(row, period_rate_col).value
                if annual_rate is not None and period is not None and (period_rate is not None):
                    try:
                        annual_rate_float = float(annual_rate)
                        period_float = float(period)
                        period_rate_float = float(period_rate)
                        if period_float != 0:
                            expected_period_rate = annual_rate_float / period_float
                            if abs(period_rate_float - expected_period_rate) > 0.01:
                                calculations_correct = False
                                calculation_errors.append(row)
                    except (ValueError, TypeError):
                        calculations_correct = False
                        calculation_errors.append(row)
        highlighted_rows = []
        for row in range(2, ws.max_row + 1):
            has_yellow_fill = False
            for col in range(1, ws.max_column + 1):
                cell = ws.cell(row, col)
                if cell.fill and cell.fill.start_color:
                    color_value = None
                    if hasattr(cell.fill.start_color, 'rgb'):
                        color_value = cell.fill.start_color.rgb
                    elif hasattr(cell.fill.start_color, 'value'):
                        color_value = cell.fill.start_color.value
                    if color_value:
                        if len(str(color_value)) == 8:
                            rgb = str(color_value)[2:]
                        else:
                            rgb = str(color_value)
                        if len(rgb) >= 6:
                            try:
                                r = int(rgb[0:2], 16)
                                g = int(rgb[2:4], 16)
                                b = int(rgb[4:6], 16)
                                if r > 200 and g > 200 and (b < min(r, g)):
                                    has_yellow_fill = True
                                    break
                            except ValueError:
                                pass
            if has_yellow_fill:
                period_rate = ws.cell(row, period_rate_col).value if period_rate_col else None
                highlighted_rows.append({'row': row, 'period_rate': period_rate})
        result = {'has_period_rate_column': has_period_rate_column, 'calculations_correct': calculations_correct, 'calculation_errors': calculation_errors, 'highlighted_rows': highlighted_rows, 'count': len(highlighted_rows)}
        wb.close()
        return result
    finally:
        os.unlink(tmp_path)

def get_xlsx_weekday_highlights__945bc7e35c7c17397875064b3c531090(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract background colors from all weekday cells in the calendar.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict mapping cell coordinates to their background color (RGB hex string or None)
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        result = {}
        for row_idx in range(3, ws.max_row + 1):
            for col_idx in range(2, ws.max_column + 1):
                cell = ws.cell(row_idx, col_idx)
                value = cell.value
                if isinstance(value, datetime):
                    day_of_week = value.weekday()
                    if day_of_week < 5:
                        bg_color = None
                        if cell.fill and cell.fill.start_color:
                            rgb = cell.fill.start_color.rgb
                            if rgb and rgb != '00000000':
                                bg_color = rgb
                        result[cell.coordinate] = bg_color
        return result
    finally:
        os.unlink(tmp_path)

def get_thunderbird_xlsx_data__d5a65208(env, config: Dict[str, Any]) -> List[List[str]]:
    """
    Extract data from xlsx file created from Thunderbird emails.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key for xlsx file path

    Returns:
        List of rows, each row is a list of cell values as strings
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    vm_path = config.get('path')
    dest_name = config.get('dest', 'result.xlsx')
    local_path = get_vm_file(env, {'path': vm_path, 'dest': dest_name})
    if local_path is None:
        return []
    try:
        wb = openpyxl.load_workbook(local_path, data_only=True)
        ws = wb.active
        data = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row and any((cell is not None for cell in row)):
                data.append([str(cell) if cell is not None else '' for cell in row])
        return data
    except Exception as e:
        return []

