def get_xlsx_cell_value__f6b13ced632f7653f34ef803e35a96e5(env, config: Dict) -> Optional[Dict]:
    """Extract both formula and calculated value from a specific cell in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell' keys

    Returns:
        Dict with 'formula' (str or None) and 'value' (numeric or None)
    """
    import openpyxl
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb_formula = openpyxl.load_workbook(tmp_path, data_only=False)
        sheet_name = config.get('sheet')
        if isinstance(sheet_name, int):
            ws_formula = wb_formula.worksheets[sheet_name]
        else:
            ws_formula = wb_formula[sheet_name]
        cell_addr = config.get('cell')
        cell = ws_formula[cell_addr]
        formula = cell.value if isinstance(cell.value, str) and cell.value.startswith('=') else None
        wb_formula.close()
        wb_value = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_name, int):
            ws_value = wb_value.worksheets[sheet_name]
        else:
            ws_value = wb_value[sheet_name]
        cell_value = ws_value[cell_addr].value
        wb_value.close()
        return {'formula': formula, 'value': cell_value}
    finally:
        os.unlink(tmp_path)

