def get_xlsx_has_freeze_panes__8e837c3a(env, config):
    """Check if freeze panes is set on the sheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'file_path', 'sheet'

    Returns:
        bool: True if freeze panes is set, False otherwise
    """
    file_path = config.get('file_path')
    sheet_idx = config.get('sheet', 0)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return False
    import os
    cache_path = os.path.join(env.cache_dir, os.path.basename(file_path))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path)
    if isinstance(sheet_idx, int):
        ws = wb.worksheets[sheet_idx]
    else:
        ws = wb[sheet_idx]
    if ws.freeze_panes:
        return True
    return False

