def get_xlsx_top_sales_rows__55bad598090981b9f19fc3b8a4c7b402(env, config):
    """Extract the first N data rows from Excel file in their current order.

    This getter reads the spreadsheet in its current visual order WITHOUT sorting,
    to verify that the user has correctly sorted the data by Sales column.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (file path) and 'top_n' (number of rows)

    Returns:
        List of tuples: [(first_name, last_name, sales), ...]
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return []
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        rows_data = []
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row and len(row) >= 6:
                first_name = row[1]
                last_name = row[3]
                sales = row[5]
                if sales is not None:
                    rows_data.append((first_name, last_name, float(sales)))
        top_n = config.get('top_n', 3)
        return rows_data[:top_n]
    finally:
        os.unlink(tmp_path)

