def get_xlsx_row_range__1fd6bc02(env, config: dict):
    """Get detailed information about rows in the Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'baseline_rows' keys

    Returns:
        dict: {
            'total_rows': int,
            'baseline_rows': int,
            'new_rows_count': int,
            'rows': list of dicts containing row data
        }
    """
    vm_path = config.get('path', '')
    baseline_rows = config.get('baseline_rows', 1)
    file_content = env.controller.get_file(vm_path)
    if not file_content:
        return {'total_rows': 0, 'baseline_rows': baseline_rows, 'new_rows_count': 0, 'rows': []}
    wb = openpyxl.load_workbook(io.BytesIO(file_content), data_only=True)
    ws = wb.active
    rows_data = []
    for row_idx in range(2, ws.max_row + 1):
        row_values = []
        has_content = False
        for col_idx in range(1, ws.max_column + 1):
            cell_value = ws.cell(row_idx, col_idx).value
            row_values.append(str(cell_value) if cell_value is not None else '')
            if cell_value:
                has_content = True
        if has_content:
            rows_data.append({'row_idx': row_idx, 'values': row_values})
    wb.close()
    total_rows = len(rows_data)
    new_rows_count = max(0, total_rows - baseline_rows)
    return {'total_rows': total_rows, 'baseline_rows': baseline_rows, 'new_rows_count': new_rows_count, 'rows': rows_data}

