def get_xlsx_row_fill__ec6099e4393d3df1a03fe5d9019f1dca(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract fill color information and sales values from all rows in an Excel file.
    This allows verification that the row with maximum sales is the one highlighted.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with keys:
            - path: VM file path to the Excel file
            - sheet: Sheet index (0-based) or sheet name
            - row: Row number to check for highlighting
            - start_col: Start column index (1-based, default: 1)
            - end_col: End column index (1-based, default: 5)

    Returns:
        Dict with:
            - has_fill: bool - whether target row has fill
            - fill_colors: list - fill colors of target row cells
            - all_rows_data: list[dict] - all rows with sales values and fill status
            - target_row_sales: float/None - sales value of target row
            - max_sales_value: float/None - maximum sales value in all rows
            - max_sales_row: int/None - row number with maximum sales
    """
    file_path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    target_row_num = config.get('row')
    start_col = config.get('start_col', 1)
    end_col = config.get('end_col', 5)
    if not file_path or not target_row_num:
        return {'has_fill': False, 'fill_colors': [], 'all_rows_data': [], 'target_row_sales': None, 'max_sales_value': None, 'max_sales_row': None}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'has_fill': False, 'fill_colors': [], 'all_rows_data': [], 'target_row_sales': None, 'max_sales_value': None, 'max_sales_row': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if isinstance(sheet_idx, int):
            ws = wb.worksheets[sheet_idx]
        else:
            ws = wb[sheet_idx]
        all_rows_data = []
        max_sales_value = None
        max_sales_row = None
        target_row_sales = None
        for row in ws.iter_rows(min_row=2, values_only=False):
            row_num = row[0].row
            sales_cell = ws.cell(row_num, 5)
            sales_value = sales_cell.value
            try:
                sales_float = float(sales_value) if sales_value is not None else None
            except (ValueError, TypeError):
                sales_float = None
            row_has_fill = False
            for col_idx in range(start_col, end_col + 1):
                cell = ws.cell(row_num, col_idx)
                fill = cell.fill
                if fill and fill.start_color:
                    fill_type = fill.fill_type
                    color_value = fill.start_color.rgb if hasattr(fill.start_color, 'rgb') else None
                    if fill_type and fill_type != 'none' and color_value and (color_value != '00000000'):
                        row_has_fill = True
                        break
            all_rows_data.append({'row_num': row_num, 'sales_value': sales_float, 'has_fill': row_has_fill})
            if sales_float is not None:
                if max_sales_value is None or sales_float > max_sales_value:
                    max_sales_value = sales_float
                    max_sales_row = row_num
            if row_num == target_row_num:
                target_row_sales = sales_float
        fill_colors = []
        target_has_fill = False
        for col_idx in range(start_col, end_col + 1):
            cell = ws.cell(target_row_num, col_idx)
            fill = cell.fill
            if fill and fill.start_color:
                fill_type = fill.fill_type
                color_value = fill.start_color.rgb if hasattr(fill.start_color, 'rgb') else None
                if fill_type and fill_type != 'none' and color_value and (color_value != '00000000'):
                    target_has_fill = True
                    fill_colors.append(str(color_value))
                else:
                    fill_colors.append(None)
            else:
                fill_colors.append(None)
        wb.close()
        return {'has_fill': target_has_fill, 'fill_colors': fill_colors, 'all_rows_data': all_rows_data, 'target_row_sales': target_row_sales, 'max_sales_value': max_sales_value, 'max_sales_row': max_sales_row}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

