def get_xlsx_cell_colors__e25bf6ec(env, config: dict) -> Dict[str, Any]:
    """Extract background colors for all cells in the specified sheet.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest' keys

    Returns:
        Dict mapping cell coordinates to their RGB background colors (as hex strings)
    """
    vm_path = config.get('path', '/home/user/Calendar_Highlight_Weekend_Days.xlsx')
    dest = config.get('dest', 'Calendar_Highlight_Weekend_Days.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    import os
    cache_dir = env.cache_dir
    local_path = os.path.join(cache_dir, dest)
    os.makedirs(os.path.dirname(local_path), exist_ok=True)
    with open(local_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(local_path)
    ws = wb.active
    cell_colors = {}
    for row in ws.iter_rows():
        for cell in row:
            if cell.fill and cell.fill.start_color:
                color = cell.fill.start_color.rgb
                if color and color != '00000000':
                    if len(color) == 8:
                        hex_color = f'#{color[2:].upper()}'
                    else:
                        hex_color = f'#{color.upper()}'
                    cell_colors[cell.coordinate] = hex_color
    wb.close()
    return cell_colors

def get_xlsx_multi_row_data__60b726f1(env, config: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    Extract data from multiple rows in Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file
            - sheet: Sheet index (0-based)
            - start_row: First data row (1-based, default: 2)
            - max_rows: Maximum rows to extract (default: 10)

    Returns:
        List of dicts, each containing row data
    """
    path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    start_row = config.get('start_row', 2)
    max_rows = config.get('max_rows', 10)
    import os
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return []
    cache_path = os.path.join(env.cache_dir, os.path.basename(path))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    ws = wb.worksheets[sheet_idx]
    rows_data = []
    for row_idx in range(start_row, min(start_row + max_rows, ws.max_row + 1)):
        row = ws[row_idx]
        has_data = any((cell.value is not None and str(cell.value).strip() for cell in row))
        if not has_data:
            continue
        row_dict = {}
        for (col_idx, cell) in enumerate(row, start=1):
            col_letter = openpyxl.utils.get_column_letter(col_idx)
            row_dict[col_letter] = cell.value
        rows_data.append(row_dict)
    wb.close()
    return rows_data

