def get_xlsx_first_day_highlights__f5c8911b3cca16f0878e0d65734b3523(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract background colors from all cells, separating first-day and non-first-day cells.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to the Excel file

    Returns:
        Dict with two keys:
            - 'first_day_colors': Dict mapping first-day cell coordinates to their background colors
            - 'non_first_day_colors': Dict mapping non-first-day cell coordinates to their background colors
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'first_day_colors': {}, 'non_first_day_colors': {}}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        first_day_colors = {}
        non_first_day_colors = {}
        for row_idx in range(3, ws.max_row + 1):
            for col_idx in range(2, ws.max_column + 1):
                cell = ws.cell(row_idx, col_idx)
                value = cell.value
                if isinstance(value, datetime):
                    bg_color = None
                    if cell.fill and cell.fill.start_color:
                        rgb = cell.fill.start_color.rgb
                        if rgb and rgb != '00000000':
                            bg_color = rgb
                    if value.day == 1:
                        first_day_colors[cell.coordinate] = bg_color
                    else:
                        non_first_day_colors[cell.coordinate] = bg_color
        return {'first_day_colors': first_day_colors, 'non_first_day_colors': non_first_day_colors}
    finally:
        os.unlink(tmp_path)

def get_xlsx_columns_data__906752c021f982d3057437536a20323c(env, config: dict):
    """Extract data from multiple columns in Excel file for comprehensive verification.

    Args:
        env: DesktopEnv instance
        config: Dict with 'path' (VM file path), 'sheet' (sheet index), 'columns' (list of column letters),
                'start_row' (int), 'end_row' (int), 'sum_cell' (optional, e.g., "B31")

    Returns:
        dict: Contains column data and sum cell value, or None if file not found
              {
                'column_B': [list of values from B3:B30],
                'column_D': [list of values from D3:D30],
                'sum_cell': value from B31
              }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[config.get('sheet', 0)]
        columns = config.get('columns', ['B', 'D'])
        start_row = config.get('start_row', 3)
        end_row = config.get('end_row', 30)
        sum_cell = config.get('sum_cell', 'B31')
        result = {}
        for col in columns:
            col_data = []
            for row in range(start_row, end_row + 1):
                cell_value = ws[f'{col}{row}'].value
                col_data.append(cell_value)
            result[f'column_{col}'] = col_data
        if sum_cell:
            result['sum_cell'] = ws[sum_cell].value
        return result
    finally:
        os.unlink(tmp_path)

