def get_calc_chart_info__9851fb15658f615b8fd1e6b26c166e46(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract chart information from LibreOffice Calc file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key (VM file path)

    Returns:
        Dict with chart information from the specified sheet
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        import openpyxl
        from openpyxl.chart import LineChart, BarChart, PieChart, AreaChart, ScatterChart
        wb = openpyxl.load_workbook(tmp_path)
        chart_info = []
        for (sheet_idx, sheet_name) in enumerate(wb.sheetnames):
            ws = wb[sheet_name]
            if hasattr(ws, '_charts') and ws._charts:
                for (chart_idx, chart) in enumerate(ws._charts):
                    chart_type = type(chart).__name__
                    chart_title = chart.title if hasattr(chart, 'title') and chart.title else ''
                    data_ranges = []
                    data_point_count = 0
                    category_ranges = []
                    if hasattr(chart, 'series') and chart.series:
                        for series in chart.series:
                            if hasattr(series, 'val') and series.val:
                                val_ref = str(series.val)
                                data_ranges.append(val_ref)
                                if ':' in val_ref and '$' in val_ref:
                                    try:
                                        parts = val_ref.split('!')[-1]
                                        range_parts = parts.split(':')
                                        if len(range_parts) == 2:
                                            start_row = int(''.join((c for c in range_parts[0] if c.isdigit())))
                                            end_row = int(''.join((c for c in range_parts[1] if c.isdigit())))
                                            data_point_count = max(data_point_count, end_row - start_row + 1)
                                    except:
                                        pass
                            if hasattr(series, 'cat') and series.cat:
                                cat_ref = str(series.cat)
                                category_ranges.append(cat_ref)
                    chart_info.append({'sheet_index': sheet_idx, 'sheet_name': sheet_name, 'chart_index': chart_idx, 'chart_type': chart_type, 'chart_title': chart_title, 'data_ranges': data_ranges, 'category_ranges': category_ranges, 'data_point_count': data_point_count})
        return {'charts': chart_info, 'total_charts': len(chart_info)}
    finally:
        if os.path.exists(tmp_path):
            os.unlink(tmp_path)

