def get_xlsx_channel_stats__2073dc4aaf44c0cf8ae42a16bec77097(env, config: Dict[str, Any]) -> Dict[str, Dict[str, float]]:
    """Extract sales channel count and total revenue from Sheet2.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key

    Returns:
        Dict mapping channel names to {'count': int, 'total': float}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if 'Sheet2' not in wb.sheetnames:
            return {}
        ws = wb['Sheet2']
        channel_stats = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            channel = str(row[0]).strip()
            count = row[1] if row[1] is not None else 0
            total = row[2] if row[2] is not None else 0
            try:
                count = int(count)
            except (ValueError, TypeError):
                count = 0
            try:
                total = float(total)
            except (ValueError, TypeError):
                total = 0.0
            channel_stats[channel] = {'count': count, 'total': total}
        return channel_stats
    finally:
        os.unlink(tmp_path)

