def get_xlsx_table_completeness__5067b5ea(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """
    Check completeness of data in Excel table.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file
            - sheet: Sheet index (0-based)
            - start_row: First data row (1-based, default: 2)
            - columns: List of column letters to check

    Returns:
        Dict with completeness statistics
    """
    path = config.get('path')
    sheet_idx = config.get('sheet', 0)
    start_row = config.get('start_row', 2)
    columns = config.get('columns', ['A', 'B', 'C', 'D'])
    import os
    file_bytes = env.controller.get_file(path)
    if not file_bytes:
        return {'total_rows': 0, 'complete_rows': 0}
    cache_path = os.path.join(env.cache_dir, os.path.basename(path))
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    ws = wb.worksheets[sheet_idx]
    total_rows = 0
    complete_rows = 0
    for row_idx in range(start_row, ws.max_row + 1):
        has_data = False
        for col in columns:
            cell_value = ws[f'{col}{row_idx}'].value
            if cell_value is not None and str(cell_value).strip():
                has_data = True
                break
        if not has_data:
            continue
        total_rows += 1
        all_filled = True
        for col in columns:
            cell_value = ws[f'{col}{row_idx}'].value
            if cell_value is None or not str(cell_value).strip():
                all_filled = False
                break
        if all_filled:
            complete_rows += 1
    wb.close()
    return {'total_rows': total_rows, 'complete_rows': complete_rows}

def get_xlsx_date_sorted__2c45e1ed(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Check if dates in a column are sorted and count rows.

    Returns:
        Dict with keys:
            - 'order': str - 'descending', 'ascending', 'unsorted', or 'unknown'
            - 'row_count': int - number of rows with dates
            - 'is_sorted_descending': bool - True if sorted newest to oldest
            - 'is_sorted_ascending': bool - True if sorted oldest to newest
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    column = config.get('column', 'C')
    try:
        wb = openpyxl.load_workbook(file_path, data_only=True)
        if sheet_idx >= len(wb.sheetnames):
            return {'order': 'unknown', 'row_count': 0, 'is_sorted_descending': False, 'is_sorted_ascending': False}
        ws = wb[wb.sheetnames[sheet_idx]]
        dates_raw = []
        dates_parsed = []
        for row_idx in range(2, ws.max_row + 1):
            cell_value = ws[f'{column}{row_idx}'].value
            if cell_value is not None and str(cell_value).strip():
                date_str = str(cell_value).strip()
                dates_raw.append(date_str)
                try:
                    parts = date_str.split('.')
                    if len(parts) == 3:
                        (year, month, day) = (int(parts[0]), int(parts[1]), int(parts[2]))
                        dates_parsed.append(datetime(year, month, day))
                    else:
                        dates_parsed.append(datetime.strptime(date_str, '%Y.%m.%d'))
                except (ValueError, IndexError):
                    dates_parsed.append(None)
        row_count = len(dates_parsed)
        if row_count < 2:
            return {'order': 'descending' if row_count > 0 else 'unknown', 'row_count': row_count, 'is_sorted_descending': True, 'is_sorted_ascending': True}
        valid_dates = [d for d in dates_parsed if d is not None]
        if len(valid_dates) < len(dates_parsed):
            return {'order': 'unknown', 'row_count': row_count, 'is_sorted_descending': False, 'is_sorted_ascending': False}
        is_sorted_desc = all((valid_dates[i] >= valid_dates[i + 1] for i in range(len(valid_dates) - 1)))
        is_sorted_asc = all((valid_dates[i] <= valid_dates[i + 1] for i in range(len(valid_dates) - 1)))
        if is_sorted_desc and is_sorted_asc:
            order = 'descending'
        elif is_sorted_desc:
            order = 'descending'
        elif is_sorted_asc:
            order = 'ascending'
        else:
            order = 'unsorted'
        return {'order': order, 'row_count': row_count, 'is_sorted_descending': is_sorted_desc, 'is_sorted_ascending': is_sorted_asc}
    except Exception:
        return {'order': 'unknown', 'row_count': 0, 'is_sorted_descending': False, 'is_sorted_ascending': False}

