def get_xlsx_highlighted_column__f071a3f381bbaeb7d60101b95a35963a(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract which column header is highlighted.

    This getter checks which month column (B-G) has highlighting in the header row.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: Path to Excel file on VM
            - sheet: Sheet index (default 0)
            - header_row: Row number for headers (default 1)

    Returns:
        Dict containing the highlighted column letter, month name, and color RGB value
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'highlighted_column': None, 'month_name': None, 'color_rgb': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        header_row = config.get('header_row', 1)
        month_columns = ['B', 'C', 'D', 'E', 'F', 'G']
        for col in month_columns:
            cell = ws[f'{col}{header_row}']
            if cell.fill and cell.fill.start_color and cell.fill.start_color.rgb:
                color = cell.fill.start_color.rgb
                if color not in ['FFFFFFFF', '00000000', 'FF000000']:
                    month_name = cell.value
                    return {'highlighted_column': col, 'month_name': month_name, 'color_rgb': color}
        return {'highlighted_column': None, 'month_name': None, 'color_rgb': None}
    finally:
        os.unlink(tmp_path)

