def get_xlsx_merged_cells__ca24be03(env, config: Dict[str, Any]) -> Optional[Dict[str, str]]:
    """Get the merged range boundaries for a cell.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'cell' keys

    Returns:
        Dict with 'start_cell' and 'end_cell' keys if cell is merged, None otherwise
    """
    file_path = config.get('path', '')
    sheet_name = config.get('sheet', '')
    cell_address = config.get('cell', '')
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    import tempfile
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        if sheet_name.isdigit():
            ws = wb.worksheets[int(sheet_name)]
        else:
            ws = wb[sheet_name]
        cell = ws[cell_address]
        for merged_range in ws.merged_cells.ranges:
            if cell.coordinate in merged_range:
                (min_col, min_row, max_col, max_row) = merged_range.bounds
                start_cell = f'{openpyxl.utils.get_column_letter(min_col)}{min_row}'
                end_cell = f'{openpyxl.utils.get_column_letter(max_col)}{max_row}'
                return {'start_cell': start_cell, 'end_cell': end_cell}
        return None
    finally:
        import os
        os.unlink(tmp_path)

