def get_xlsx_question_stats__4b23efd87229478689a26b35a7006ffe(env, config: Dict[str, Any]) -> Dict[str, int]:
    """Extract statistics of correct answers per question from rows 13-22.

    This getter reads the analysis that the user should have added to rows 13-22,
    where each row should contain a label like 'Q1 Correct Count:' and the count value.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' key pointing to Excel file

    Returns:
        Dict[str, int]: Dictionary mapping question number to count of correct answers
                       extracted from the user's added analysis in rows 13-22
    """
    file_path = config.get('path', '')
    if not file_path:
        return {}
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.active
        question_stats = {}
        for row in range(13, 23):
            label_cell = ws.cell(row=row, column=1).value
            count_cell = ws.cell(row=row, column=2).value
            if label_cell and count_cell is not None:
                label_str = str(label_cell).strip()
                match = re.match('Q(\\d+)\\s*Correct\\s*Count:?', label_str, re.IGNORECASE)
                if match:
                    q_num = match.group(1)
                    q_key = f'Q{q_num}'
                    try:
                        count = int(count_cell)
                        question_stats[q_key] = count
                    except (ValueError, TypeError):
                        pass
        return question_stats
    finally:
        os.unlink(tmp_path)

