def get_xlsx_row_highlighting__5cd720e501b822eea67447b89055c7d2(env, config):
    """Extract highlighting information for a specific row.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (index), and 'row' (row number)

    Returns:
        Dict with highlighting info: {'has_fill': bool, 'fill_color': str or None}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_fill': False, 'fill_color': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        row_num = config.get('row', 1)
        has_fill = False
        fill_color = None
        for cell in ws[row_num]:
            if cell.fill and cell.fill.patternType and (cell.fill.patternType != 'none'):
                has_fill = True
                if cell.fill.fgColor and hasattr(cell.fill.fgColor, 'rgb'):
                    fill_color = cell.fill.fgColor.rgb
                    break
        return {'has_fill': has_fill, 'fill_color': fill_color}
    finally:
        os.unlink(tmp_path)

