def get_calc_sheet_totals__7c4b33fd7a6525bbc17718e725776792(env, config: dict) -> Optional[Dict[str, Any]]:
    """Extract total values from a specific sheet in LibreOffice Calc.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' (VM file path) and 'sheet_name' (sheet to read)

    Returns:
        Dict mapping year to {total_assets, total_liab_oe} or None if error
    """
    file_path = config.get('path')
    sheet_name = config.get('sheet_name', 'Sheet2')
    if not file_path:
        return None
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return None
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        if sheet_name not in wb.sheetnames:
            return None
        ws = wb[sheet_name]
        result = {}
        for row in ws.iter_rows(min_row=2, values_only=True):
            if row[0] is None:
                break
            year = row[0]
            total_assets = row[1]
            total_liab_oe = row[2]
            if year is not None:
                result[int(year)] = {'total_assets': float(total_assets) if total_assets is not None else None, 'total_liab_oe': float(total_liab_oe) if total_liab_oe is not None else None}
        return result
    finally:
        os.unlink(tmp_path)

def get_pptx_table_cell_color__a2fb7fe0c04e0740ecc82f4b948afcee(env, config):
    """Get the font color of all cells in a PowerPoint table.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with:
            - path: VM path to the PPTX file
            - slide_idx: Slide index (0-based)
            - shape_idx: Shape index (0-based)

    Returns:
        dict: {
            "total_cells": int,
            "cells_with_color": int,
            "matching_cells": int,
            "all_cells_match": bool
        }
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'total_cells': 0, 'cells_with_color': 0, 'matching_cells': 0, 'all_cells_match': False}
    with tempfile.NamedTemporaryFile(suffix='.pptx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        prs = Presentation(tmp_path)
        slide = prs.slides[config['slide_idx']]
        shape = slide.shapes[config['shape_idx']]
        if not hasattr(shape, 'table'):
            return {'total_cells': 0, 'cells_with_color': 0, 'matching_cells': 0, 'all_cells_match': False}
        table = shape.table
        total_cells = 0
        cells_with_color = 0
        matching_cells = 0
        target_rgb = [255, 0, 0]
        for row_idx in range(len(table.rows)):
            for col_idx in range(len(table.columns)):
                total_cells += 1
                cell = table.cell(row_idx, col_idx)
                if cell.text_frame.paragraphs:
                    para = cell.text_frame.paragraphs[0]
                    if para.runs:
                        run = para.runs[0]
                        if hasattr(run.font.color, 'rgb') and run.font.color.rgb is not None:
                            cells_with_color += 1
                            rgb_list = list(run.font.color.rgb)
                            if rgb_list == target_rgb:
                                matching_cells += 1
        all_cells_match = total_cells > 0 and matching_cells == total_cells
        return {'total_cells': total_cells, 'cells_with_color': cells_with_color, 'matching_cells': matching_cells, 'all_cells_match': all_cells_match}
    finally:
        os.unlink(tmp_path)

