def get_pivot_channel__d2f4714b(env, config):
    """Extract pivot table data from Sheet2 for Sales Channel analysis.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path' and 'dest'

    Returns:
        dict: Extracted pivot data with channel totals
    """
    vm_path = config.get('path', '/home/user/EntireSummerSales.xlsx')
    file_bytes = env.controller.get_file(vm_path)
    if not file_bytes:
        return {}
    cache_path = os.path.join(env.cache_dir, config.get('dest', 'EntireSummerSales.xlsx'))
    os.makedirs(os.path.dirname(cache_path), exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(file_bytes)
    wb = openpyxl.load_workbook(cache_path, data_only=True)
    if 'Sheet2' not in wb.sheetnames:
        return {}
    ws = wb['Sheet2']
    data = {}
    rows = list(ws.iter_rows(values_only=True))
    if len(rows) < 2:
        return {}
    channels = ['E-mail Coupon', 'In Store Sales', 'Web Site Sales']
    header_row = rows[0]
    for (col_idx, cell_value) in enumerate(header_row):
        if cell_value in channels:
            if len(rows) > 1 and rows[1][col_idx] is not None:
                try:
                    data[cell_value] = float(rows[1][col_idx])
                except (ValueError, TypeError):
                    pass
    if not data:
        for row in rows:
            if row[0] in channels and len(row) > 1:
                try:
                    data[row[0]] = float(row[1])
                except (ValueError, TypeError):
                    pass
    wb.close()
    return data

