def get_xlsx_cell_fill__4f31f8e94f050fe62adc0139e1e07281(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract cell fill/background color from Excel file.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (0-indexed), 'cell' (e.g., 'I18')

    Returns:
        Dict with fill info: {'has_fill': bool, 'color': str or None}
    """
    file_bytes = env.controller.get_file(config['path'])
    if not file_bytes:
        return {'has_fill': False, 'color': None}
    with tempfile.NamedTemporaryFile(suffix='.xlsx', delete=False) as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path)
        sheet_idx = config.get('sheet', 0)
        ws = wb.worksheets[sheet_idx]
        cell_addr = config.get('cell', 'A1')
        cell = ws[cell_addr]
        has_fill = False
        fill_color = None
        if cell.fill and cell.fill.start_color:
            fill_type = cell.fill.fill_type
            if fill_type and fill_type != 'none':
                has_fill = True
                if hasattr(cell.fill.start_color, 'rgb'):
                    fill_color = cell.fill.start_color.rgb
                elif hasattr(cell.fill.start_color, 'index'):
                    fill_color = str(cell.fill.start_color.index)
        wb.close()
        return {'has_fill': has_fill, 'color': fill_color}
    finally:
        os.unlink(tmp_path)

