def get_xlsx_remark_counts__acb4b915(env, config: Dict[str, Any]) -> Dict[str, Any]:
    """Extract student grades and remarks, and count remark occurrences.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet', 'column', 'start_row', 'end_row'

    Returns:
        Dict with 'counts' (remark counts) and 'students' (list of grade-remark pairs)
    """
    file_path = config.get('path', '')
    sheet_idx = config.get('sheet', 0)
    message_column = config.get('column', 'F')
    grade_column = config.get('grade_column', 'E')
    start_row = config.get('start_row', 10)
    end_row = config.get('end_row', 23)
    file_bytes = env.controller.get_file(file_path)
    if not file_bytes:
        return {'counts': {}, 'students': []}
    import tempfile
    import os
    with tempfile.NamedTemporaryFile(delete=False, suffix='.xlsx') as tmp:
        tmp.write(file_bytes)
        tmp_path = tmp.name
    try:
        wb = openpyxl.load_workbook(tmp_path, data_only=True)
        ws = wb.worksheets[sheet_idx]
        remarks = []
        students = []
        for row in range(start_row, end_row + 1):
            grade_value = ws[f'{grade_column}{row}'].value
            message_value = ws[f'{message_column}{row}'].value
            if message_value:
                remarks.append(str(message_value))
            if grade_value is not None and message_value:
                students.append({'grade': int(grade_value) if isinstance(grade_value, (int, float)) else grade_value, 'remark': str(message_value)})
        counts = Counter(remarks)
        wb.close()
        return {'counts': dict(counts), 'students': students}
    finally:
        os.unlink(tmp_path)

