def get_xlsx_highlighted_cells__62c8fae8(env, config):
    """Get list of cells that have background fill/highlighting.

    Args:
        env: DesktopEnv instance
        config: Configuration dict with 'path', 'sheet' (int), 'range' (str like "B16:B20")

    Returns:
        List of cell addresses that have fill color applied
    """
    from desktop_env.evaluators.getters.file import get_vm_file
    file_path = get_vm_file(env, {'path': config['path'], 'dest': os.path.basename(config['path'])})
    if file_path is None:
        logger.error(f"Failed to get file from VM: {config['path']}")
        return []
    wb = openpyxl.load_workbook(file_path)
    if isinstance(config['sheet'], int):
        ws = wb.worksheets[config['sheet']]
    else:
        ws = wb[config['sheet']]
    cell_range = config.get('range', 'A1:Z100')
    highlighted_cells = []
    for row in ws[cell_range]:
        for cell in row:
            if cell.fill and cell.fill.start_color:
                fill_color = cell.fill.start_color.rgb if hasattr(cell.fill.start_color, 'rgb') else None
                if fill_color and fill_color not in ['00000000', 'FFFFFFFF', None]:
                    highlighted_cells.append(cell.coordinate)
    return highlighted_cells

def get_xlsx_column_text__7af19fd1(env, config):
    """
    Get all text values from a specific column in an xlsx file.

    Args:
        env: Environment object with controller
        config: Configuration dict with:
            - 'path': VM path to the xlsx file
            - 'sheet': Sheet index (0-based) or sheet name (default: 0)
            - 'column': Column letter (e.g., 'A', 'B', 'C')
            - 'start_row': Starting row number (default: 1)
            - 'end_row': Ending row number (optional, defaults to last row with data)

    Returns:
        List of text values from the specified column
    """
    file_path = config['path']
    sheet_identifier = config.get('sheet', 0)
    column = config['column']
    start_row = config.get('start_row', 1)
    end_row = config.get('end_row', None)
    file_content = env.controller.get_file(file_path)
    if file_content is None:
        return []
    wb = openpyxl.load_workbook(BytesIO(file_content), data_only=True)
    if isinstance(sheet_identifier, int):
        sheet = wb.worksheets[sheet_identifier]
    else:
        sheet = wb[sheet_identifier]
    if end_row is None:
        end_row = sheet.max_row
    values = []
    for row in range(start_row, end_row + 1):
        cell_ref = f'{column}{row}'
        cell_value = sheet[cell_ref].value
        if cell_value is not None:
            values.append(str(cell_value))
    return values

